  Stage_122186_Name = {
    Text = "切断盲腸・第一幕"
  },
  Stage_122601_Name = {
    Text = "モシャ試遊ステージ"
  },
  Stage_123112_Desc = {
    Text = "霧が私の目を覆い、自分の世界との繋がりを失わせた。しかし、あなたの瞳を通して、私はもう戻れない過去や、二度と会えない人々を見た。\n私たちは似ている。"
  },
  Stage_123112_Name = {
    Text = "あなたの瞳を通して"
  },
  Stage_123113_Desc = {
    Text = "霧が私の目を覆い、自分の世界との繋がりを失わせた。しかし、あなたの瞳を通して、私はもう戻れない過去や、二度と会えない人々を見た。\n私たちは似ている。"
  },
  Stage_123113_Name = {
    Text = "あなたの瞳を通して"
  },
  Stage_125199_Desc = {
    Text = "愛に耽る虫だけが、こんなに脆弱で、こんなに強靭で、こんなに滑稽で、そしてこんなに非凡なのです。\nああ、私と一緒にもっと素晴らしいものを見に行きましょう。あなたたちはお互いを支え合い、これからずっと緊密に結びつくでしょう。"
  },
  Stage_125199_Name = {
    Text = "羅織・三つ目"
  },
  Stage_125200_Desc = {
    Text = "情熱は常に帰る場所があるが、必ずしも共に老いることには帰らず、無念の死に帰ることの方が多いかもしれない。\n時には愛が無念の死を迎え、時にはあなたが無念の死を迎えることもある。"
  },
  Stage_125200_Name = {
    Text = "無念の死・狂気"
  },
  Stage_125201_Desc = {
    Text = "旧愛はあなたのもとを去ったのに、なぜ今になって後悔し始めたのですか？\nふふ、遅くはない、急ぐこともない、ほら——郎君。太陽が沈むと、すべての灯り、すべての赤いろうそくが、窓の後ろに彼女の姿、彼女の影を映し出します。"
  },
  Stage_125201_Name = {
    Text = "窓の後ろの影・の二"
  },
  Stage_125202_Desc = {
    Text = "「…………蝉の抜け殻と骨を交換することを屍解と呼び、仙人に昇る…………」\nああ、実際にはそうではない、それは一つの荒唐無稽な話だが、何の関係があるだろう？彼女たちは血と涙で祈り、そこから戦慄する美と恐怖が蘇生した。"
  },
  Stage_125202_Name = {
    Text = "屍解·の六"
  },
  Stage_125203_Desc = {
    Text = "旧愛はあなたのもとを去ったのに、なぜ今になって後悔し始めたのですか？\nふふ、遅くはない、急ぐこともない、ほら——郎君。太陽が沈むと、すべての灯り、すべての赤いろうそくが、窓の後ろに彼女の姿、彼女の影を映し出します。"
  },
  Stage_125203_Name = {
    Text = "窓の後ろの影・の一つ"
  },
  Stage_125204_Desc = {
    Text = "彼らは香案の供え物の下に共にひざまずき、無相の玄女は探ることも定義することもできず、逆らうこともできない。\nすべてを捧げ、すべてに従い、唯一の極楽に昇り、永遠の混乱に至る。"
  },
  Stage_125204_Name = {
    Text = "極楽·狂気"
  },
  Stage_125205_Desc = {
    Text = "私があなたの香りを好み、あなたの敵を味わってあげます。"
  },
  Stage_125205_Name = {
    Text = "香を循環させる・の二"
  },
  Stage_125206_Desc = {
    Text = "その神秘的な結社は東方の古国の史書の外に漂い、探知されることも、定義されることもない。今なお消え去ることのないごく少数の個体だけが、かつて彼らが崇拝していた神の名を知っていた。\n彼女は「@4」と呼ばれている。"
  },
  Stage_125206_Name = {
    Text = "臃容衆・第一幕"
