  },
  Stage_125654_Desc = {
    Text = "入念にリハーサルされた新作劇、観覧無料、離席禁止。"
  },
  Stage_125654_Name = {
    Text = "劇中の人"
  },
  Stage_125655_Desc = {
    Text = "笑え！歌え！我が友よ！運命の舞台で、歓楽こそが唯一の主役だ。"
  },
  Stage_125655_Name = {
    Text = "即興喜劇"
  },
  Stage_125656_Desc = {
    Text = "劇場に足を踏み入れた時、我々の役柄はすでに選ぶ余地などなかった。"
  },
  Stage_125656_Name = {
    Text = "観客、役者、作者"
  },
  Stage_125657_Desc = {
    Text = "棘と炎よりも苛酷な刑罰。"
  },
  Stage_125657_Name = {
    Text = "優しき枷"
  },
  Stage_125658_Desc = {
    Text = "最も美しい舞は、常に死と破壊の中で咲き誇る。"
  },
  Stage_125658_Name = {
    Text = "白鳥の飛翔"
  },
  Stage_125659_Desc = {
    Text = "90分の真夜中、15インチの仮面、10ガロンの夢、2オンスのアルコール――幸福の唯一のレシピ。"
  },
  Stage_125659_Name = {
    Text = "仮面パーティー"
  },
  Stage_125660_Desc = {
    Text = "カドリン荘園は栄華と衰退の芝居を見ることを好む。荘園を喜ばせる術を知る者だけが、招待状を手にできる。"
  },
  Stage_125660_Name = {
    Text = "荘園の招待状"
  },
  Stage_125661_Desc = {
    Text = "役者は登場し、作者は不詳。"
  },
  Stage_125662_Desc = {
    Text = "大洋の彼方のハリケーンは、実のところあの蝶の選択とは何の関係もなかった。"
  },
  Stage_125662_Name = {Text = "銃火"},
  Stage_125663_Desc = {
    Text = "不朽の牢獄は、囚人自らの手で編み上げられた。\n彼女たちは永遠に編み続ける。彼女たちは決して逃れられない。"
  },
  Stage_125663_Name = {Text = "繭"},
  Stage_126202_Desc = {
    Text = "花束、歓声、拍手。世界が再びその傍らに戻ってくる。\n語りの魔術師はその演技を終え、観客の記憶は優雅なカーテンコールの中で消え去る。\nいかなる秘密も、舞台の廃墟から持ち出すことはできない。"
  },
  Stage_126202_Name = {
    Text = "ネタバレ厳禁·その四"
  },
  Stage_126203_Desc = {
    Text = "迎えよ、物語のクライマックスを！すべての伏線は燃料であり、すべての準備は、舞台を燃え上がらせるこの瞬間のためにあった。"
  },
  Stage_126203_Name = {
    Text = "燃焼·その四"
  },
  Stage_126204_Desc = {
    Text = "退屈は操り人形にとって死罪である。"
  },
  Stage_126204_Name = {
    Text = "反転、反転·その四"
  },
  Stage_126208_Desc = {
    Text = "幕が上がり、観客も拍手ももはや存在しない。\n世界はがらんとして、ただ一つの照明だけが、この唯一の舞台を照らしている。"
  },
  Stage_126208_Name = {
    Text = "入場·その六"
  },
