  Stage_126263_Name = {
    Text = "入場·その一"
  },
  Stage_129163_Name = {
    Text = "疾走する歓楽特急・通常"
  },
  Stage_129164_Name = {
    Text = "疾走する歓楽特急・高難度"
  },
  Stage_129165_Name = {
    Text = "疾走する歓楽特急・狂気"
  },
  Stage_129500_Desc = {
    Text = "磐龍古国の祈歳節では、南でも北でも、どの家も集まります。\n彼らは祈歳節が近づくと、遠くへ向かう列車に乗り、憧れの気持ちを抱いて久しぶりの再会の瞬間を待ち望みます。"
  },
  Stage_129500_Name = {
    Text = "祈歳列車"
  },
  Stage_129501_Desc = {
    Text = "怖がらないで、これはただのゲームだ。\n残酷で、ひどいゲームだ。"
  },
  Stage_129501_Name = {
    Text = "ゲーム開始"
  },
  Stage_129502_Desc = {
    Text = "止まらないで、後退しないで。\nもし善意の人が手に持っている銃を下ろせば、邪悪が勝ちを得て追撃してくるでしょう。"
  },
  Stage_129502_Name = {
    Text = "第二の犠牲者"
  },
  Stage_129503_Desc = {
    Text = "これは正義のための絶地反撃…………か？"
  },
  Stage_129503_Name = {
    Text = "隠された殺し手"
  },
  Stage_129504_Desc = {
    Text = "そのラッチはよくあなたの夢に現れる。\nそれを押すべきか、引くべきか、それが問題だ。"
  },
  Stage_129504_Name = {
    Text = "常闇の車両"
  },
  Stage_129505_Desc = {
    Text = "焰火は天を連ねて旧年を辞し、往日の灰は追うことができない。"
  },
  Stage_129505_Name = {
    Text = "往日の焔火"
  },
  Stage_130109_Desc = {
    Text = "人は学校に通う。それに覚醒体も。\n今や彼女も覚醒体。当然、学校に通うことになる。\nくれぐれも……安全には注意するように。"
  },
  Stage_130109_Name = {
    Text = "学校·の二"
  },
  Stage_130110_Desc = {
    Text = "どうすれば伝説の調査員になれるのか？\nひとつ、深い井戸には数えきれないほどの秘密が隠されている。\nふたつ、井戸の底へ踏み込む前に覚えておくといい——ショットガンの所持は、必ずしも合法的である必要はない。"
  },
  Stage_130110_Name = {
    Text = "井戸·の六"
  },
  Stage_130111_Desc = {
    Text = "どうすれば伝説の調査員になれるのか？\nひとつ、深い井戸には数えきれないほどの秘密が隠されている。\nふたつ、井戸の底へ踏み込む前に覚えておくといい——ショットガンの所持は、必ずしも合法的である必要はない。"
  },
  Stage_130111_Name = {
    Text = "井戸·の二"
  },
  Stage_130112_Desc = {
    Text = "そう、伝説の調査員でも、毎度必ず勝てるとは限らない。\n…いや大丈夫だ。まだウォッカは最後の一滴が残っている。"
  },
  Stage_130112_Name = {
    Text = "最後の一杯·の四"
  },
  Stage_130113_Desc = {
    Text = "愛し合う人たちが食事をし、それぞれの思いを話し合う。\n食べ物は多くの秘密を聞いているが、当然、言葉を発することはない。"
  },
  Stage_130113_Name = {
    Text = "食卓·の四"
  },
  Stage_130114_Desc = {
    Text = "人は学校に通う。それに覚醒体も。\n今や彼女も覚醒体。当然、学校に通うことになる。\nくれぐれも……安全には注意するように。"
  },
  Stage_130114_Name = {
    Text = "学校·狂気"
  },
  Stage_130115_Desc = {
    Text = "人は学校に通う。それに覚醒体も。\n今や彼女も覚醒体。当然、学校に通うことになる。\nくれぐれも……安全には注意するように。"
  },
  Stage_130115_Name = {
    Text = "学校·三つ目"
  },
  Stage_130116_Desc = {
    Text = "天井を好きな色に塗って、壁も好きな色に塗って。\n冷蔵庫を好きな食べ物でいっぱいにして、二人が好きなペットを飼って。\nここはあなたと私だけの家。"
  },
  Stage_130116_Name = {
    Text = "我が家·之六"
  },
  Stage_130117_Desc = {
    Text = "愛し合う人たちが食事をし、それぞれの思いを話し合う。\n食べ物は多くの秘密を聞いているが、当然、言葉を発することはない。"
  },
  Stage_130117_Name = {
    Text = "食卓·三つ目"
  },
  Stage_130118_Desc = {
    Text = "病院は不思議な場所だ。誕生、死、そして再生。\nこの世で最も大きな苦しみと、この世で最も大きな喜びが、どれもここに集まっている。\nそれなのに、人々の喜びや悲しみ、すべての感情は、互いにまったく通じ合わない。"
  },
  Stage_130118_Name = {
    Text = "病院·その二"
  },
