  Stage_130125_Name = {
    Text = "病院・その一"
  },
  Stage_130126_Desc = {
    Text = "天井を好きな色に塗って、壁も好きな色に塗って。\n冷蔵庫を好きな食べ物でいっぱいにして、二人が好きなペットを飼って。\nここはあなたと私だけの家。"
  },
  Stage_130126_Name = {
    Text = "我が家·之二"
  },
  Stage_130127_Desc = {
    Text = "記憶とは一粒の種のようだ。それはあらゆるものを内に秘めたまま、決して語りはしない。\nやがて、水を与えられ、根を張って芽吹き、大地が包み込み、現実から力を吸い上げることを許すその時まで。"
  },
  Stage_130127_Name = {
    Text = "「記憶」"
  },
  Stage_130128_Desc = {
    Text = "天井を好きな色に塗って、壁も好きな色に塗って。\n冷蔵庫を好きな食べ物でいっぱいにして、二人が好きなペットを飼って。\nここはあなたと私だけの家。"
  },
  Stage_130128_Name = {
    Text = "我が家·之四"
  },
  Stage_130129_Desc = {
    Text = "病院は不思議な場所だ。誕生、死、そして再生。\nこの世で最も大きな苦しみと、この世で最も大きな喜びが、どれもここに集まっている。\nそれなのに、人々の喜びや悲しみ、すべての感情は、互いにまったく通じ合わない。"
  },
  Stage_130129_Name = {
    Text = "病院·その四"
  },
  Stage_130130_Desc = {
    Text = "愛し合う人たちが食事をし、それぞれの思いを話し合う。\n食べ物は多くの秘密を聞いているが、当然、言葉を発することはない。"
  },
  Stage_130130_Name = {
    Text = "食卓·の六"
  },
  Stage_130131_Desc = {
    Text = "どうすれば伝説の調査員になれるのか？\nひとつ、深い井戸には数えきれないほどの秘密が隠されている。\nふたつ、井戸の底へ踏み込む前に覚えておくといい——ショットガンの所持は、必ずしも合法的である必要はない。"
  },
  Stage_130131_Name = {
    Text = "井戸·の四"
  },
  Stage_130132_Desc = {
    Text = "世界は一瞬にして地獄へと変わる——本当にそうだろうか？\nもしかすると、何も変わってないのかもしれない。\nただ、これまであなたが我慢していただけなのでは。"
  },
  Stage_130132_Name = {
    Text = "脳損傷·の四"
  },
  Stage_130133_Desc = {
