  Stage_130819_Desc = {
    Text = "陽光が窓を通り抜け、オークの香りを漂わせる机に降り注ぐ。\n本が横に散らばり、モスクはだらりと机に伏せている。\n「ナウティラZzz…………小さな石炭球Zzz…………楽しい〜」\n長い冷たさと孤独は終わった。\n次はもっと良い明日だ。"
  },
  Stage_130819_Name = {
    Text = "よし、もっとよく、もっともっとよく"
  },
  Stage_130820_Desc = {
    Text = "魚を捕まえて、食べて、果物を食べて、貝殻を集めて、隠して、寝る"
  },
  Stage_130820_Name = {
    Text = "平凡な毎日·の四"
  },
  Stage_130821_Desc = {
