  Stage_130823_Name = {
    Text = "帰還の道・の五"
  },
  Stage_130824_Desc = {
    Text = "パタ。\n雨が船に当たる音がとても大きい。\nモスク、こんなの嫌だ。\nパタ。"
  },
  Stage_130824_Name = {
    Text = "ぱたっ、ぱたっ。"
  },
  Stage_130825_Desc = {
    Text = "バシャ〜バシャ〜\n「チュ！(受けてみろ、大男！)」\n「ふんふん、小さな石炭球、遅い！」\nバシャ〜バシャ〜\n「モスク！待って、待って、涼しい。」\n「友よ、遊びに来て！」\n"
  },
  Stage_130825_Name = {
