  Stage_131105_Desc = {
    Text = "不朽の牢獄は、囚人自らの手で編み上げられた。\n彼女たちは永遠に編み続ける。彼女たちは決して逃れられない。"
  },
  Stage_131105_Name = {Text = "繭"},
  Stage_132466_Desc = {
    Text = "内部テスト専用"
  },
  Stage_132466_Name = {
    Text = "テスト環境·忘却篇"
  },
  Stage_139577_Desc = {
    Text = "最高だ、この…………いやいや、この黒猫どもは最悪だってことさ！"
  },
  Stage_139577_Name = {
    Text = "ブラックゴールドラッシュ"
  },
  Stage_139578_Desc = {
    Text = "銀キューブとゴールド券でポケットはいっぱい、勝利の将軍は意気揚々と凱旋する。"
  },
  Stage_139578_Name = {
    Text = "大漁御礼"
  },
  Stage_139579_Desc = {
    Text = "君は一番大きな猫に目をつけた。そして、あちらも君に目をつけていた。"
  },
  Stage_139579_Name = {
    Text = "巨大な獲物"
  },
  Stage_139580_Desc = {
    Text = "でも猫はまだたくさんいる、もう一回だけ…………最後にしよう？"
  },
  Stage_139580_Name = {
    Text = "もう一度やる"
  },
  Stage_139581_Desc = {
    Text = "漆黒の海に最初の銀色の輝きが現れた時、君の手にした猫捕り網はより力強く振られた。"
  },
  Stage_139581_Name = {
    Text = "最初の銀キューブ"
  },
  Stage_139582_Desc = {
    Text = "黒猫が抵抗するということは、君のやっていることが正しい証拠だ。"
  },
  Stage_139582_Name = {
    Text = "逮捕拒否"
  },
  Stage_139583_Desc = {
    Text = "網が大きいほど猫も多い、大きな猫には大きな網を、引けぇ！"
  },
  Stage_139583_Name = {
    Text = "網を引け！引け！"
  },
  Stage_140299_Desc = {
    Text = "咲き誇り、舞い上がれ。\nたとえこの先にどれほどの困難が待ち受けていようと、あなたは決して彼女の手を離さないと決めたのだ。\nあなたとわたしが別れを告げるその瞬間、倒錯した世界を「真実」で染め上げて。"
  },
  Stage_140299_Name = {Text = "別れ"},
  Stage_140300_Desc = {
    Text = "記憶とは一粒の種のようだ。それはあらゆるものを内に秘めたまま、決して語りはしない。\nやがて、水を与えられ、根を張って芽吹き、大地が包み込み、現実から力を吸い上げることを許すその時まで。"
  },
