  },
  Stage_141235_Desc = {
    Text = "あなたはゲームが好きで、すべてを茶番と見なしている。だから私たちはあの信者たちの喉を切り裂き、脊椎を踏み砕き、自分たちがいかに愚かで滑稽な汚れたものを信仰しているかを思い知らせてやる。\nずっと逃げ続けるがいい、さもなければ、湮滅でさえただ美しい妄想に過ぎないと発見することになる。"
  },
  Stage_141235_Name = {
    Text = "追走ゲーム·の一つ"
  },
  Stage_141236_Desc = {
    Text = "手に入れやすく、美味しく、堅固で、緻密で、息が詰まるような。\n脆弱な。\nそれはここに存在する。"
  },
  Stage_141236_Name = {
    Text = "肋軟骨·の六"
  },
  Stage_141237_Desc = {
    Text = "そう、もちろん知っている。\n最初から最後まで、ただ「私」がいるだけで、「私たち」などいなかった。"
  },
  Stage_141237_Name = {
    Text = "告白·狂気"
  },
  Stage_141238_Desc = {
    Text = "ハンターと獲物の立場はしばしば一瞬にして入れ替わり、幾千年もの間、サイクルを繰り返してきた。一方が道具の使い方を覚え、一方が真の力を手にするまで。"
  },
  Stage_141238_Name = {
    Text = "森林法典·の五"
  },
  Stage_141239_Desc = {
    Text = "彼は海よりも古い存在に選ばれ、戻ることのできない場所に留まった。"
  },
  Stage_141239_Name = {
    Text = "哨笛·の六"
  },
  Stage_141240_Desc = {
    Text = "最も賑やかな食べ物、最も祝いに相応しい食べ物、私たちは杯を交わし、集う。\n誰も気にしない、幾つもの躯の下に同じ意志があるかどうかを、誰も気にしない、幾つもの空殻の下にまだ魂があるかどうかを。"
  },
