  },
  Stage_141289_Desc = {
    Text = "祂は気づかれにくく、祂は物音一つ立てず、祂は突然やってくる。\n人々は活気ある日々の中で他人事のように祂の名を口にし、やがて人々が気づいた時には、祂はすでに影のように寄り添う友となっていた。"
