  },
  Stage_141290_Name = {
    Text = "麦酒と香辛料·の一つ"
  },
  Stage_141291_Desc = {
    Text = "ハンターと獲物の立場はしばしば一瞬にして入れ替わり、幾千年もの間、サイクルを繰り返してきた。一方が道具の使い方を覚え、一方が真の力を手にするまで。"
  },
  Stage_141291_Name = {
    Text = "森林法典·の四"
  },
  Stage_141742_Desc = {
    Text = "♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n仲間を探す孤独な号鳥がいた、彼の仲間は翼を失い、彼の仲間は羽をすべて抜かれてしまった。\n彼は叶えられない願いを叶えようとした、彼の仲間は彼との思い出さえも忘れてしまった。\n ♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n大丈夫、大丈夫。彼らにはまだ甘い、甘い、共通の帰り場所がある。彼らは安らかな、安らかな、永遠に乱されることのない夢の国へと入っていく。"
  },
  Stage_141742_Name = {
    Text = "羽根·三つ目"
  },
  Stage_141743_Desc = {
    Text = "♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n仲間を探す孤独な号鳥がいた、彼の仲間は翼を失い、彼の仲間は羽をすべて抜かれてしまった。\n彼は叶えられない願いを叶えようとした、彼の仲間は彼との思い出さえも忘れてしまった。\n ♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n大丈夫、大丈夫。彼らにはまだ甘い、甘い、共通の帰り場所がある。彼らは安らかな、安らかな、永遠に乱されることのない夢の国へと入っていく。"
  },
  Stage_141743_Name = {
    Text = "羽根·の六"
  },
  Stage_141744_Desc = {
    Text = "私の話は好き？好きじゃない？えっ？！どう言えば信じてもらえるの、もういい加減に根掘り葉掘り聞くのはやめてよ、そんなことしたら悲しくなっちゃうよ？\nこのリンゴをひとくち食べてみて、すっごく甘いから、本当だって保証する！\nこの物語の一字一字と同じくらい本当のことだよ！"
  },
  Stage_141744_Name = {
    Text = "リンゴ·狂気"
  },
  Stage_141745_Desc = {
    Text = "私の話は好き？好きじゃない？えっ？！どう言えば信じてもらえるの、もういい加減に根掘り葉掘り聞くのはやめてよ、そんなことしたら悲しくなっちゃうよ？\nこのリンゴをひとくち食べてみて、すっごく甘いから、本当だって保証する！\nこの物語の一字一字と同じくらい本当のことだよ！"
  },
  Stage_141745_Name = {
    Text = "リンゴ·の二"
  },
  Stage_141746_Desc = {
    Text = "私の話は好き？好きじゃない？えっ？！どう言えば信じてもらえるの、もういい加減に根掘り葉掘り聞くのはやめてよ、そんなことしたら悲しくなっちゃうよ？\nこのリンゴをひとくち食べてみて、すっごく甘いから、本当だって保証する！\nこの物語の一字一字と同じくらい本当のことだよ！"
  },
  Stage_141746_Name = {
    Text = "リンゴ·の一つ"
  },
  Stage_141747_Desc = {
    Text = "そう、そう、人はここまで不運になれるものだ。\n彼女の一生には嘘以外何もなく、今回も信じ、次もまた信じ、ほんのわずかな希望のために、すべての嘘の苦い実を飲み込んだ。\nだからこの嘘の果てに、彼女の一生の果てに……\n私たちは彼女の瞳の中に、憎しみ以外、何も見つけることができない。"
  },
  Stage_141747_Name = {
    Text = "目·狂気"
  },
  Stage_141748_Desc = {
    Text = "物語がここまで進むと、あなたは少し躊躇い始める。\n手がかりは最初からすでに現れていた、運命はあなたを何かの証人として引き寄せたのか？糸の向こう端には、どんな真実が繋がっているのか？\n雪の下に何が埋まっているのか、一体何人が望みを叶えられるのか？\nあなたにはわからない、旅はまだ半ばにも達していない、あなたはただその導きに従い続けるしかない。"
  },
  Stage_141748_Name = {
    Text = "糸·の六"
  },
  Stage_141749_Desc = {
    Text = "♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n仲間を探す孤独な号鳥がいた、彼の仲間は翼を失い、彼の仲間は羽をすべて抜かれてしまった。\n彼は叶えられない願いを叶えようとした、彼の仲間は彼との思い出さえも忘れてしまった。\n ♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n大丈夫、大丈夫。彼らにはまだ甘い、甘い、共通の帰り場所がある。彼らは安らかな、安らかな、永遠に乱されることのない夢の国へと入っていく。"
  },
  Stage_141749_Name = {
    Text = "羽根·の四"
  },
  Stage_141750_Desc = {
    Text = "ああ、小さな神の欠片よ、カダスの救世主よ、あらゆる滅びの希望よ、あらゆる絶境における新生よ、ミサゴ唯一のシークレットキーパーよ。\nあなたは今日まで共に歩んできた鍵をしっかりと握りしめ、その心は決意に満ちている。\nそう、あの言葉はなんと言うのでしたっけ……？銀の鍵が私たちを導きますように！"
  },
  Stage_141750_Name = {
    Text = "鍵·三つ目"
  },
  Stage_141751_Desc = {
    Text = "♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n小さな女の子は道をあまりにも長く歩きすぎた、孤独が彼女の肩にのしかかり、恋しさが彼女の心を蝕んでいく。\nどこを探しても見つからない、どんな方法も効かない。\n♬〜〜♫〜〜♪〜〜♫〜〜♪〜〜♫〜〜\n大丈夫、大丈夫、女の子が探しているものはすべて鏡の中にある、鏡は空の月を映し、月は鏡の中の波紋へと落ちていく。"
  },
  Stage_141751_Name = {
    Text = "鏡・第一幕"
  },
  Stage_141752_Desc = {
    Text = "他のことはすべてわかっているが、なぜ王冠がこの場所に現れたのか？？誰がこんなにうっかりして、詐欺師の罠にはまったのか？\nこれは明らかにこの部分で考えるべき内容ではない、続きが気になるなら……\n次の物語のときに説明しよう！"
  },
  Stage_141752_Name = {
