  Stage_143315_Name = {
    Text = "彼女と彼"
  },
  Stage_143876_Desc = {
    Text = "どうすれば伝説の調査員になれるのか？\nひとつ、深い井戸には数えきれないほどの秘密が隠されている。\nふたつ、井戸の底へ踏み込む前に覚えておくといい——ショットガンの所持は、必ずしも合法的である必要はない。"
