    Text = "井戸·の六"
  },
  Stage_143877_Desc = {
    Text = "人は学校に通う。それに覚醒体も。\n今や彼女も覚醒体。当然、学校に通うことになる。\nくれぐれも……安全には注意するように。"
  },
  Stage_143877_Name = {
    Text = "学校·の六"
