  Stage_143879_Desc = {
    Text = "世界は一瞬にして地獄へと変わる——本当にそうだろうか？\nもしかすると、何も変わってないのかもしれない。\nただ、これまであなたが我慢していただけなのでは。"
  },
  Stage_143879_Name = {
    Text = "脳損傷·の一つ"
  },
  Stage_143880_Desc = {
    Text = "病院は不思議な場所だ。誕生、死、そして再生。\nこの世で最も大きな苦しみと、この世で最も大きな喜びが、どれもここに集まっている。\nそれなのに、人々の喜びや悲しみ、すべての感情は、互いにまったく通じ合わない。"
  },
  Stage_143880_Name = {
    Text = "病院·その六"
  },
  Stage_143881_Desc = {
    Text = "病院は不思議な場所だ。誕生、死、そして再生。\nこの世で最も大きな苦しみと、この世で最も大きな喜びが、どれもここに集まっている。\nそれなのに、人々の喜びや悲しみ、すべての感情は、互いにまったく通じ合わない。"
  },
  Stage_143881_Name = {
    Text = "病院·狂乱"
  },
  Stage_143882_Desc = {
    Text = "どうすれば伝説の調査員になれるのか？\nひとつ、深い井戸には数えきれないほどの秘密が隠されている。\nふたつ、井戸の底へ踏み込む前に覚えておくといい——ショットガンの所持は、必ずしも合法的である必要はない。"
  },
  Stage_143882_Name = {
    Text = "井戸·狂気"
  },
  Stage_143883_Desc = {
    Text = "そう、伝説の調査員でも、毎度必ず勝てるとは限らない。\n…いや大丈夫だ。まだウォッカは最後の一滴が残っている。"
  },
