  Stage_144352_Desc = {
    Text = "一時的なテキスト"
  },
  Stage_144352_Name = {
    Text = "一時的なテキスト"
  },
  Stage_144353_Desc = {
    Text = "一時的なテキスト"
  },
  Stage_144353_Name = {
    Text = "一時的なテキスト"
  },
  Stage_145312_Desc = {
    Text = "ようこそ！星天の鯨のコロセウムへようこそ！この殺戮の殿堂へようこそ！\n将軍、暗殺者、賞金稼ぎ、グラディエイター……生きとし生ける伝説がここに集う。\n殺し合い、同盟を結び、裏切り、あなたのあらゆる手段を尽くせ、生存者よ。\nルールはただ一つ：最後に立っている者のみが、あのドアを開けることができる。"
  },
  Stage_145312_Name = {
    Text = "殺戮の殿堂·の四"
  },
  Stage_145313_Desc = {
    Text = "名誉、公正、尊厳……これらはすべて弱者が自らのために編んだ鎖だ。\n彼女はより強いものにしか興味がない。この血に染まったコロセウムで、彼女が真剣に向き合うに値する者が、あるいはまだ一人いるかもしれない。"
  },
  Stage_145314_Desc = {
    Text = "星天の鯨を喜ばせる方法は至ってシンプルだ：十分な血、十分に強大な力、十分に強烈な欲望……\nあなたが幾千万の屍を踏み越えたとき、おめでとう、あなたはこの争いに参加する資格を得た。"
  },
  Stage_145314_Name = {
    Text = "謁献·三つ目"
  },
  Stage_145315_Desc = {
    Text = "ようこそ！星天の鯨のコロセウムへようこそ！この殺戮の殿堂へようこそ！\n将軍、暗殺者、賞金稼ぎ、グラディエイター……生きとし生ける伝説がここに集う。\n殺し合い、同盟を結び、裏切り、あなたのあらゆる手段を尽くせ、生存者よ。\nルールはただ一つ：最後に立っている者のみが、あのドアを開けることができる。"
  },
  Stage_145315_Name = {
    Text = "殺戮の殿堂·三つ目"
  },
  Stage_145316_Desc = {
    Text = "星天の鯨を喜ばせる方法は至ってシンプルだ：十分な血、十分に強大な力、十分に強烈な欲望……\nあなたが幾千万の屍を踏み越えたとき、おめでとう、あなたはこの争いに参加する資格を得た。"
  },
  Stage_145316_Name = {
    Text = "謁献·の一つ"
  },
  Stage_145317_Desc = {
    Text = "あらゆる危険の中で、猛獣は最も優しい存在だ。"
  },
  Stage_145317_Name = {
    Text = "囚われの獣·の五"
  },
  Stage_145318_Desc = {
    Text = "ついに、あなたは望むものすべてを手に入れた。力、富、栄光、尽きることのない権力。\n鮮血が王冠から滴り落ち、あなたの両眼を赤く染める。思う存分笑うがいい、偉大なる新王よ。この権欲の鮮血の中で、必ず訪れるあなたの腐敗を待つがいい。"
  },
  Stage_145318_Name = {
    Text = "権欲の王冠·の一つ"
  },
