  },
  Stage_145321_Desc = {
    Text = "ようこそ！星天の鯨のコロセウムへようこそ！この殺戮の殿堂へようこそ！\n将軍、暗殺者、賞金稼ぎ、グラディエイター……生きとし生ける伝説がここに集う。\n殺し合い、同盟を結び、裏切り、あなたのあらゆる手段を尽くせ、生存者よ。\nルールはただ一つ：最後に立っている者のみが、あのドアを開けることができる。"
  },
  Stage_145321_Name = {
    Text = "殺戮の殿堂·の五"
  },
  Stage_145322_Desc = {
    Text = "ついに、あなたは望むものすべてを手に入れた。力、富、栄光、尽きることのない権力。\n鮮血が王冠から滴り落ち、あなたの両眼を赤く染める。思う存分笑うがいい、偉大なる新王よ。この権欲の鮮血の中で、必ず訪れるあなたの腐敗を待つがいい。"
  },
  Stage_145322_Name = {
    Text = "権欲の王冠·の五"
  },
  Stage_145323_Desc = {
    Text = "あなたの身を屈め、頭を垂れよ。\nそれが蟻が神明に向き合うとき、唯一ふさわしい姿勢だ。"
  },
  Stage_145323_Name = {Text = "蟻"},
  Stage_145324_Desc = {
    Text = "彼女の背後には何もなく、彼女の前方には果てがない。彼女はそれを喜んだ。"
  },
  Stage_145324_Name = {
    Text = "王冠の軽さ"
  },
  Stage_145325_Desc = {
