  Stage_146229_Desc = {
    Text = "席に着く者は揃い、眠り続けていた神明がついに笑い声を上げた。\nあなたたちは最初から、宴に招かれたゲストではなかった。"
  },
  Stage_146229_Name = {Text = "宴の人"},
  Stage_146230_Desc = {
    Text = "雪山にはただ一つの掟がある：何を聞いても、答えないで。"
  },
  Stage_146230_Name = {
    Text = "答えないで"
  },
  Stage_146231_Desc = {
    Text = "七枚の生贄、七つの台座、世界の原点へと続く一枚のドア。\n願いは決して無償の贈り物ではない。"
  },
  Stage_146231_Name = {
    Text = "無願の尖峰"
  },
  Stage_146232_Desc = {
    Text = "鳥はついにもう一羽の鳥を見つけ出した。\n今日は遠く旅立ち、帰る日は問わない。"
  },
  Stage_146232_Name = {
    Text = "飛鳥、今日遠く旅立つ"
  },
  Stage_146233_Desc = {
    Text = "澄んだ湖面に星空が映り、認めたくない渇望もまた映し出される。\n嘘が火に投じられても、残ったものが必ずしも真実とは限らない。"
  },
  Stage_146233_Name = {
    Text = "凍らぬ月"
  },
  Stage_146234_Desc = {
    Text = "伝説によれば、冥王はオルフェウスに、決して振り返るなと言い聞かせた。振り返れば愛する妻を永遠に失うと。\nしかし彼が愛する者の呼びかけを無視できるほど冷酷であったなら、そもそも彼女を求めて琴を抱き、死の川を渡り、幽谷を越え、ダークの冥府へと歩み入ることなどできただろうか？"
  },
  Stage_146234_Name = {Text = "逆行"},
  Stage_146235_Desc = {
    Text = "風雪が来た道を塞ぎ、見知らぬ旅の伴を連れてきた。\nダークの奥でがさがさと音がして、まるで雪山全体が迷い込んだ人々をのぞき見ているようだ。"
  },
  Stage_146235_Name = {
    Text = "七番目の旅人"
  },
  Stage_146236_Desc = {
    Text = "同行者もまた先駆者であり、彼女はあなたたちより早く雪線の上に辿り着いていた。\n向き合え、最初から、それは逃れられない存在だったのだから。"
  },
  Stage_146236_Name = {Text = "先駆者"},
  Stage_146237_Desc = {
    Text = "マントが風雪にめくられ、長く隠されていた秘密がついに羽ばたく。\n翼の中には、飛ぶためではなく生まれついたものもある。"
  },
  Stage_146237_Name = {
    Text = "巣立ちの日"
  },
  Stage_146238_Desc = {
