  Stage_146928_Desc = {
    Text = "囚われの姫君が騎士に救われる——それは誰もが知る、古くからの物語。"
  },
  Stage_146928_Name = {Text = "姫"},
  Stage_146929_Desc = {
    Text = "巨竜が目覚め、憎しみが再び燃え上がる。獣の息吹が岩の間から噴き出し、戦争の毒液が轟々と燃え盛り、今なお消えることはない。\n大地が雷鳴のごとく轟いた。"
  },
  Stage_146929_Name = {Text = "龍の巣"},
  Stage_146930_Desc = {
    Text = "騎士は見知らぬ道を歩み、荒れ果てた野と丘を越えていった。影だけが寄り添っていた。\nあるいは彼はとうに死んでいたのかもしれない。しかし証人もなく、それゆえ忘れ去られた。\n世界はかくも静かに息をひそめている。"
  },
  Stage_146930_Name = {Text = "墓塚"},
  Stage_146931_Desc = {
    Text = "四十昼夜の大雨が地に降り注ぎ、私たちは進めない、それでも私たちは進み続ける。"
  },
  Stage_146931_Name = {
    Text = "リンゴ島"
  },
  Stage_146932_Desc = {
    Text = "巨竜が目覚め、憎しみが再び燃え上がる。獣の息吹が岩の間から噴き出し、戦争の毒液が轟々と燃え盛り、今なお消えることはない。\n大地が雷鳴のごとく轟いた。"
  },
  Stage_146932_Name = {Text = "龍の巣"},
  Stage_146933_Desc = {
    Text = "それは天国の園の根と花、この世のあらゆる願いの冠冕、尽きることなき豊穣。\n杯の酒を飲み干せば、あなたが最も渇望するものが見えるだろう。"
  },
  Stage_146933_Name = {Text = "聖杯"},
  Stage_146934_Desc = {
    Text = "巨竜が目覚め、憎しみが再び燃え上がる。獣の息吹が岩の間から噴き出し、戦争の毒液が轟々と燃え盛り、今なお消えることはない。\n大地が雷鳴のごとく轟いた。"
  },
  Stage_146934_Name = {Text = "龍の巣"},
