    Text = "マダム・レッド試遊ステージ"
  },
  Stage_24184_Name = {
    Text = "泥濘の花試遊ステージ"
  },
  Stage_24423_Desc = {
    Text = "ロンディニウム人は誰もが新鮮な熱いお茶を拒まない。\nたとえそれがヤツメウナギ入りの烏龍茶でも。"
  },
  Stage_24423_Name = {
    Text = "特製ヤツメウナギ"
  },
  Stage_24424_Desc = {
    Text = "運命に選ばれた者は皆、自分が例外だと思っている。\n運命は確率を嘲笑う。"
  },
  Stage_24424_Name = {
    Text = "運命の囚人"
  },
  Stage_24425_Desc = {
    Text = "パチン。\n彼女は過去の生活と完全に決別することを誓いました。\nまるでリボンをハサミで二つに切るように。"
  },
  Stage_24425_Name = {
    Text = "ソレールに捧ぐ"
  },
  Stage_24426_Desc = {
    Text = "また、あなたは同情の虜になり、彼女の魂に深く堕ちた。"
  },
  Stage_24426_Name = {
    Text = "堕ちた審判"
  },
  Stage_24427_Desc = {
    Text = "物語の始まり、華麗な死を目撃するだろう。\nそれは始まりに過ぎず、終わりではない。"
  },
  Stage_24427_Name = {
    Text = "宴の始まり"
  },
  Stage_24428_Desc = {
    Text = "少女の名前はソレール、村の誇りだ。\n彼女は従順で清潔、真っ白な姿で小さな歩みを進め、本物の淑女のようだ。\nただ、少女は淑女とは違い——夢を見ない。"
  },
  Stage_24429_Desc = {
    Text = "論理はウイスキーのようなもの、摂りすぎると益を失う。"
  },
  Stage_24429_Name = {
    Text = "仮面の声"
  },
  Stage_24430_Desc = {
    Text = "彼の細心の手入れの下、権力欲という名の癌細胞は薔薇のように広がった。"
  },
  Stage_24430_Name = {
    Text = "紅の祝祭"
  },
  Stage_24431_Desc = {
    Text = "ずるずる吸う。暗闇に蠢き、ひそひそ囁く。\n太った身体が月光の下で曲がった涙痕を引きずる——塩辛い涙。"
  },
  Stage_24432_Desc = {
    Text = "スコーン、マカロン、そして温かいココア…\n侍女の願いは簡単です。もっと美味しいものを食べたい、それだけです。"
  },
  Stage_24432_Name = {
    Text = "侍女の願い"
  },
  Stage_24433_Desc = {
    Text = "気をつけて、気をつけて。\nあなたたちが崇拝するあの夫人は、本当の淑女ではない。\nでも、誰が気にするの？"
  },
  Stage_24433_Name = {
    Text = "淑女の心得"
  },
  Stage_24434_Desc = {
    Text = "薔薇が鐘の音に垂れ、ハゲワシが臭い花の中で迷います。\n誰も歌わず、誰も語らず。彼女の死で世界は色を失います。"
  },
  Stage_24434_Name = {
    Text = "薔薇の葬儀"
  },
  Stage_24435_Desc = {
    Text = "彼女は泉水を汲み尽くし、純真な鳥を殺した。\n彼女は金色の風をもたらし、それは流星のように野原を駆け抜けた。\n彼女は世界全体を欲望の炎に包み、それを灰にした。"
  },
  Stage_24435_Name = {Text = "椿姫"},
