  Stage_24456_Name = {
    Text = "仮面の声"
  },
  Stage_24528_Desc = {
    Text = "何が起きても、どんなに変わっても、君の呼びかけは必ず届く。"
  },
  Stage_24528_Name = {
    Text = "それは今生の別れじゃない"
  },
  Stage_24529_Desc = {
    Text = "一度、二度、三度……シーシュポスは巨石を押しながら、越えられない山を登り続ける。"
  },
  Stage_24529_Name = {
    Text = "シーシュポス"
  },
  Stage_24530_Desc = {
    Text = "気心知れた少女がまるで他人のように冷たくなってしまった。\nこの少女は本当にあなたの知っているラモンナ……？"
  },
  Stage_24530_Name = {
    Text = "一か八か"
  },
  Stage_24531_Desc = {
    Text = "普通の日は、非凡な夢から始まった。"
  },
  Stage_24531_Name = {
    Text = "その涙は雨のようで"
  },
  Stage_24532_Desc = {
    Text = "気心知れた少女がまるで他人のように冷たくなってしまった。\nこの少女は本当にあなたの知っているラモンナ……？"
  },
  Stage_24532_Name = {
    Text = "一か八か"
  },
  Stage_24533_Desc = {
    Text = "気心知れた少女がまるで他人のように冷たくなってしまった。\nこの少女は本当にあなたの知っているラモンナ……？"
  },
  Stage_24533_Name = {
    Text = "一か八か"
  },
  Stage_34716_Desc = {
    Text = "急転直下、突発的な展開、物語の急変——\n守秘者は、これが自分自身のことを描写しているように時々感じた。"
  },
  Stage_34716_Name = {
    Text = "Ⅲ・シナリオローテーション"
  },
  Stage_34717_Desc = {
    Text = "これは、ラモンナさえ聞いたことのない言葉だったが、何人かの年長の覚醒体の助けを借りて、ようやく誰もが理解した。\n『時には、大泣きすることが悪い感情を処理する唯一の方法である』"
  },
  Stage_34717_Name = {
    Text = "Ⅱ・カタシス"
  },
  Stage_34718_Desc = {
    Text = "カーシアが見つけた理論書によれば『物語の時間は一日を超えてはならず、舞台も一箇所に限る……』とあり、守秘者はここで読むのをやめた。結局、一日という時間では、守秘者が「融蝕と災厄処理」の課題論文を終えるには足りないこともあるのだ。"
  },
  Stage_34718_Name = {
    Text = "Ⅰ・三一律"
  },
  Stage_34719_Desc = {
    Text = "カーシアが見つけた理論書によれば『ピラミッドモデルは、一つの危機の解決に焦点を当てることが多い』とあった。しかし、現実世界ではすべての危機を解決はできない。それらは偽りの平和に覆い隠され、増殖し、新たな「ピラミッド」として爆発する。"
  },
  Stage_34719_Name = {
    Text = "Ⅶ·劇作ピラミッド"
  },
  Stage_34720_Desc = {
    Text = "『物語の登場人物は、結末までの成長や変化を弧のように描く必要がある』\nしかし、現実の生活では、その変化はしばしば弧ではなく、円を描く。"
  },
  Stage_34720_Name = {
    Text = "Ⅵ・弧光理論"
  },
  Stage_34721_Desc = {
    Text = "あらかじめ設定されたシーン、お互いをよく知った数人の役者。\n残りは、インスピレーションとぶつかり合いに任せる。"
  },
  Stage_34721_Name = {
    Text = "Ⅴ・仮面喜劇"
  },
  Stage_34722_Desc = {
    Text = "『絶え間なく、観客の脳を内容で攻撃してはならない。彼らに、考える余地を与えよ。できれば完全に静止した状態が望ましい』\nドールが授業にこの技術を使ってくれたならなぁ……と守秘者が呟き、皆が賛同した。"
  },
  Stage_34722_Name = {
    Text = "Ⅳ・静止の瞬間"
  },
  Stage_34912_Desc = {
    Text = "古き災厄は今まさに蘇り、現世の境界を踏み越え、堕落の大海を燃え上がらせる。"
  },
  Stage_34912_Name = {
    Text = "融災禁区・第1波・Ⅲ級警報"
  },
