  },
  Stage_35099_Desc = {
    Text = "「しーっ……ねえ、君の目を通して、私には何が見えてるかわかる？」\nオレッタが守秘者に泣かされた結果、守秘者の部屋の第四の壁は、ロータンによって壊されそうになった。オレッタの泣き声があまりに心をかき乱すものだったからだ。"
  },
  Stage_35099_Name = {
    Text = "Ⅸ・劇の第四壁"
  },
  Stage_35100_Desc = {
    Text = "『観客をストーリーに完全に没頭させてはならない。舞台で起きていることを分析し、批判させよ』この理論に対し、オレッタはこうコメントした。\n「オレッタは誰にも怒られたくない！オレッタはみんなと仲良くなりたいだけなの！」"
  },
  Stage_35100_Name = {
    Text = "Ⅷ・異化効果"
  },
  Stage_35129_Desc = {
    Text = "彼女は夢と現実の境界、夜空を見上げる魂の深層の反映。"
  },
  Stage_35129_Name = {
    Text = "倒錯した星々"
  },
  Stage_35129_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_35130_Desc = {
    Text = "彼女は、もう準備ができていた。"
  },
  Stage_35130_Name = {
    Text = "内に宿る火種"
  },
  Stage_35571_Desc = {
    Text = "あなたがオレッタの友達だから、彼女はあなたにすべての友達を紹介したい。"
  },
  Stage_35571_Name = {
    Text = "友達大収集"
  },
  Stage_35572_Desc = {
    Text = "あなたがオレッタの友達だから、彼女はあなたにすべての友達を紹介したい。"
  },
  Stage_35572_Name = {
    Text = "友達大収集"
  },
  Stage_35573_Desc = {
    Text = "あなたがオレッタの友達だから、彼女はあなたにすべての友達を紹介したい。"
  },
  Stage_35573_Name = {
    Text = "友達大収集"
  },
  Stage_35574_Desc = {
    Text = "オレッタは君が彼女の日常に加わる友達になることが好き。"
  },
  Stage_35574_Name = {
    Text = "静かな昼"
  },
  Stage_35575_Desc = {
    Text = "皆がオレッタのそばにいるから、オレッタは全然怖くない。"
  },
  Stage_35575_Name = {
    Text = "海の中のおうち"
  },
  Stage_35843_Name = {
    Text = "深海の淑女試遊ステージ"
  },
  Stage_35857_Desc = {
    Text = "星々はそれぞれ然るべき場所へと向かい、人智を超えた方法で互いに語らう。\nそうして、目に見えぬ網で、流れゆく時間と失われた光年を捕らえていく。"
  },
  Stage_35857_Name = {
    Text = "未知の星の軌跡"
  },
  Stage_36125_Desc = {
    Text = "祝福されざる子は、海の中で聖なる歌をうたう。\nシーッ……静かに。神の長き眠りを、妨げてはならない。"
  },
  Stage_36125_Name = {
    Text = "聖胎の詩Ⅲ"
