  Stage_36620_Name = {
    Text = "群れを離れた女王"
  },
  Stage_36621_Desc = {
    Text = "災厄前、城は彼女の野心と欲望の延長だった。\n災厄後、城は闇と孤独の牢獄となった。"
  },
  Stage_36621_Name = {
    Text = "笛吹き男"
  },
  Stage_36887_Name = {
    Text = "茨の女王試遊ステージ"
  },
  Stage_38756_Desc = {
    Text = "彼女は目を閉じ、宇宙の虚空を漂った。一年、百年……\nそして、ついに彼女は自分に言った。「大丈夫。真実と虚構は、あたしが決める」\n女王とその不朽の都——イサラウは、宇宙の果て、星々の海に静かに留まり続ける。\n彼女はイサラウの物語を私に語った……それが永遠に記憶されるようにと。"
  },
