  Stage_38769_Name = {
    Text = "蜃気楼・追憶の四"
  },
  Stage_38770_Desc = {
    Text = "夜、女王は宮殿のテラスに立ち、数千フィート下の都を見つめていた。\n日々、宮殿を一歩出ようとすると、眩暈、涙、そして大きな記憶の空白が襲ってくる。\n「準備はいいか？この世界の真実を迎える覚悟は」\n深く息を吸い込み、彼女はテラスから飛び降りた。"
  },
  Stage_38770_Name = {
    Text = "リアル・追憶の1つ"
  },
  Stage_38771_Desc = {
    Text = "夜、女王は宮殿のテラスに立ち、数千フィート下の都を見つめていた。\n日々、宮殿を一歩出ようとすると、眩暈、涙、そして大きな記憶の空白が襲ってくる。\n「準備はいいか？この世界の真実を迎える覚悟は」\n深く息を吸い込み、彼女はテラスから飛び降りた。"
  },
  Stage_38771_Name = {
    Text = "リアル・追憶の三"
  },
  Stage_38772_Desc = {
    Text = "彼女が目を開けた時、世界は崩壊していた。\nすべての建物が崩れ、黒い粘液が空を舐め、白いフリージアは永遠の虚空に消えた。\nすべてが静かだった。すべてが眠っているかのようだった。\nただ涙だけが冷たく彼女の頬を伝い、髪の先を濡らしていた。"
  },
