    Text = "黄金の都——イサラウ。その富は尽きることなく、その欲望は果てしない。\nそれはスポンジのように、押し寄せる黄金の潮流を吸い上げ、膨れ上がっていく。\n「これがあたしの都」と女王は言った。彼女はそれを誇りに思っていた。"
  },
  Stage_38791_Name = {
    Text = "黄金の街・追憶の一"
  },
  Stage_38792_Desc = {
    Text = "彼女が目を開けた時、世界は崩壊していた。\nすべての建物が崩れ、黒い粘液が空を舐め、白いフリージアは永遠の虚空に消えた。\nすべてが静かだった。すべてが眠っているかのようだった。\nただ涙だけが冷たく彼女の頬を伝い、髪の先を濡らしていた。"
  },
  Stage_38792_Name = {
    Text = "井・追憶の五"
  },
  Stage_38793_Desc = {
    Text = "女王とその不朽の都——イサラウ。\n宇宙に祝福された双子よ、あなたたちは運命の臍の緒に絡め取られている。\nある者は言う——賢き女王が民をイサラウへと導くさまは《黙示録》の一節のよう。\nある者は言う——イサラウの河床が絶えずうねり流れ、女王を生み出したのだと。"
  },
