  },
  Stage_38800_Name = {
    Text = "井・追憶の七"
  },
  Stage_38801_Desc = {
    Text = "「僕は何も持ってないから」片目の浮浪児は言った。「この花だけが、偉大な女王様に捧げられるものです」彼女は白いフリージアを受け取ったが、困惑を覚えた。\nその光景は、彼女の記憶の奥底で何度も繰り返されていたように思えた。\nまるで、ミノタウロスを閉じ込めた迷宮のように、繰り返し、循環していた。"
  },
  Stage_38801_Name = {
    Text = "フリージア・追憶の七"
  },
  Stage_38802_Desc = {
    Text = "夜、女王は宮殿のテラスに立ち、数千フィート下の都を見つめていた。\n日々、宮殿を一歩出ようとすると、眩暈、涙、そして大きな記憶の空白が襲ってくる。\n「準備はいいか？この世界の真実を迎える覚悟は」\n深く息を吸い込み、彼女はテラスから飛び降りた。"
  },
