  Stage_43506_Desc = {
    Text = "さようなら、と巨人は言った。\n歴史に戻る、そこでは無敵で、無双だ。\n私は不滅だ。"
  },
  Stage_43506_Name = {
    Text = "沈没の号角"
  },
  Stage_43508_Desc = {
    Text = "時間に忘れられた人よ、どこへ向かうのか？\n——遥か彼方の無依の地へ。そこには星月の静寂、海の無声がある。\n世界には君と私だけが残る。"
  },
