  },
  Stage_44202_Desc = {
    Text = "病気への恐怖が彼らを不満にさせる。\n「なぜ彼だけが祝福されるの？私も病気なのに！」\n「私の方が重症だ、私が最初に祝福されるべきだ！」"
  },
  Stage_44202_Name = {
    Text = "争奪・繁殖その四"
  },
  Stage_44203_Desc = {
    Text = "彼らに利益をもたらすものだけが良いものであり、彼らに降りかからない祝福はすべて呪いだ。\n「何の祝福だ、これは邪悪な血の魔法だ！」\n「これは魔術だ、彼は悪魔だ！」"
  },
  Stage_44203_Name = {
    Text = "非難・成長その二"
  },
  Stage_44204_Desc = {
    Text = "彼らは理解を拒み、受け入れを拒む。\n彼らの世界には黒と白しかなく、自分たちでさえその定義を制御できない。\n「焼き殺せ、焼き殺せ！」\n「この異端の司教を焼き殺せ！邪悪を滅ぼせ！」"
