  },
  Stage_44551_Desc = {
    Text = "慈悲深き父なる神よ。どうか私をお赦しください。\n過ちを正し、償わせてください。"
  },
  Stage_44551_Name = {
    Text = "我らの過ち"
  },
  Stage_44552_Desc = {
    Text = "塵が舞い落ちるとき、罪ある者は裁きを受け、進む者はその道を歩み続ける。\n明日は、再び新しい一日となる。"
  },
  Stage_44552_Name = {
    Text = "白き希望を灯して"
  },
  Stage_44553_Desc = {
    Text = "今日は何もない普通の午後になるはずだった。\nだが、ミサゴ大学の守秘者に平穏な日常というものは、叶わぬ贅沢な願いらしい。"
  },
  Stage_44553_Name = {Text = "懺悔"},
  Stage_44554_Desc = {
    Text = "浄化せよ、浄化せよ……\nこれは狂人の戯言か、それとも何かの狂信か？"
  },
  Stage_44554_Name = {
    Text = "血に染まるシンボル"
  },
  Stage_44555_Desc = {
    Text = "彼らはすでに炎に飲み込まれ、理性を失っている。"
  },
  Stage_44555_Name = {
    Text = "怒りによる狂気"
  },
  Stage_44556_Desc = {
    Text = "他人が持つものを欲しがり、他人が持たぬむもはなおさら欲しがる——\nどんなに無意味なものでも、どんなに馬鹿げたものでも。"
  },
  Stage_44556_Name = {
    Text = "嫉妬による殺戮"
  },
  Stage_44557_Desc = {
    Text = "止まっていい。休め。もう十分だ。\n横になっていい。眠れ。誰も責めない。"
  },
  Stage_44557_Name = {
    Text = "怠惰による妥協"
  },
  Stage_44558_Desc = {
    Text = "疲れた体で帰路に着くが、飢えた牙に遭遇する。"
  },
  Stage_44558_Name = {
    Text = "空腹を満たせ"
  },
  Stage_44559_Desc = {
    Text = "鏡に映るのは虚構か、それとも本物の欲望か？"
  },
  Stage_44559_Name = {
    Text = "罪の浄化"
  },
  Stage_44560_Desc = {
    Text = "慈悲深き父なる神よ。どうか私をお赦しください。\n過ちを正し、償わせてください。"
  },
