  Stage_44715_Name = {
    Text = "仁愛の司教試遊ステージ"
  },
  Stage_45411_Name = {
    Text = "別れの口づけ"
  },
  Stage_46169_Desc = {
    Text = "彼女はあらゆる確率を心に刻みながら、幼い学生のように戸惑っていた。\nなぜなら狂気は予想できないから。不幸にも、それが世界の常である。"
  },
  Stage_46169_Name = {
    Text = "すべてを賭けたゲーム"
  },
  Stage_46170_Desc = {
    Text = "彼女はあらゆる確率を心に刻みながら、幼い学生のように戸惑っていた。\nなぜなら狂気は予想できないから。不幸にも、それが世界の常である。"
  },
  Stage_46170_Name = {
    Text = "すべてを賭けたゲーム"
  },
  Stage_46171_Desc = {
    Text = "その呪いは、あなたを永遠の冬眠に沈む蛇へと変える。\nそれは、あなたの臍の緒と同じくらい古い。"
  },
  Stage_46171_Name = {
    Text = "苦しみの呪縛"
  },
  Stage_46172_Desc = {
    Text = "少女はかつてメイソンだった。\nまもなく、彼女はユリシーズのように誰でもなくなる。\nまもなく、彼女は「すべて」となる。"
  },
  Stage_46173_Desc = {
    Text = "その呪いは、あなたを永遠の冬眠に沈む蛇へと変える。\nそれは、あなたの臍の緒と同じくらい古い。"
  },
  Stage_46173_Name = {
    Text = "苦しみの呪縛"
  },
  Stage_46174_Desc = {
    Text = "ここで終わる。私で終わる。\n主を試してはならない。"
  },
  Stage_46174_Name = {
    Text = "ここまで"
  },
  Stage_46175_Desc = {
    Text = "長年、巡礼者たちは雪山に道を刻み、現実をこの地に繋ぎとめた。\n彼らは動かず、口を大きく開き、まるで永遠の咆哮を放つかのように——"
  },
  Stage_46175_Name = {
    Text = "巡礼者の歌"
  },
  Stage_46176_Desc = {
    Text = "その呪いは、あなたを永遠の冬眠に沈む蛇へと変える。\nそれは、あなたの臍の緒と同じくらい古い。"
  },
