  },
  Stage_46177_Name = {
    Text = "すべてを賭けたゲーム"
  },
  Stage_46178_Desc = {
    Text = "彼女は、自らが世界を支配していく光景を見た。\n細く長い影をじっと見つめ、何も言わずに立ち尽くしている。"
  },
  Stage_46178_Name = {
    Text = "影の童話"
  },
  Stage_46179_Desc = {
    Text = "彼女の喜劇は唯一無二。\nそれは果てなき孤独の夜と、月と、涙からできている。"
  },
  Stage_46179_Name = {
    Text = "喜劇を待ちながら"
  },
  Stage_46180_Desc = {
    Text = "すべてが眠るとき、蛇は目を覚ます。\nすべてが崩れ落ちるとき、蛇は本来の姿に戻る。"
  },
  Stage_46180_Name = {
    Text = "不眠の蛇"
  },
  Stage_46181_Desc = {
    Text = "猫は自分の感情を18個に分け、それぞれに違う調子の「ニャー」を与えた。\nこれで「お腹空いた」「遊んで」「邪魔しないで」\nそして、「会いたかった」も言える。"
  },
  Stage_46181_Name = {
    Text = "猫はすべてを知っている"
  },
  Stage_46182_Desc = {
    Text = "古い鐘の音と共に響く、微かな息と、消えゆく祝福。\nメリークリスマス。メリークリスマス。メリークリスマス。"
  },
