  Stage_46557_Desc = {
    Text = "地獄は無数の鏡が置かれた空っぽの部屋です。\n彼女は目を開けることができません。なぜなら、どこを見ても彼女の青白く恐怖に満ちた顔が映っているからです。\nどこからか声が聞こえます：\nこれは報いだ。生前はただの皮袋だったが、死後の報いは無数の皮袋だ。"
  },
  Stage_46557_Name = {
    Text = "鏡・出現その七"
  },
