  Stage_48034_Desc = {
    Text = "水源は砂漠の血脈、オアシスは心臓が送り出す血の水脈。"
  },
  Stage_48034_Name = {
    Text = "オアシス"
  },
  Stage_48035_Desc = {
    Text = "母樹はアラン族に生命を与えるが、魂を捕食する。"
  },
  Stage_48035_Name = {Text = "繁殖"},
  Stage_48036_Desc = {
    Text = "黄砂は外界との情報の行き来を遮り、古い文明はここに生き続けてきた。\nアラン族は代々この地に生まれ、この地で世代を重ねてきた。"
  },
  Stage_48036_Name = {Text = "集落"},
  Stage_48037_Desc = {
    Text = "アラン文明では、首飾りは恋人同士の重要な愛の証である。"
  },
  Stage_48037_Name = {Text = "首飾り"},
  Stage_48038_Desc = {
    Text = "樹より来たり。源より来たり。"
  },
  Stage_48039_Desc = {
    Text = "盤面の向こう側の影に注意を払え。\n本当の敵は、いつだって盤上にはいない。"
  },
  Stage_48039_Name = {Text = "敵"},
  Stage_48040_Desc = {
    Text = "太古の遺骸は、文明の廃墟にひっそりと隠されている。"
  },
  Stage_48040_Name = {Text = "遺骸"},
  Stage_48041_Desc = {
    Text = "嵐は、太古の獣が咆哮するかのようだった。"
  },
  Stage_48041_Name = {Text = "嵐の壁"},
  Stage_48042_Desc = {
