  Stage_49361_Name = {
    Text = "蜜腺・夢語りの四"
  },
  Stage_49362_Desc = {
    Text = "落果、それは残酷な予兆。\n環境が過酷であるほど、生存競争は早く訪れる。\n新たな芽が大地に触れる前から、死はすでに影のように寄り添っている。"
  },
  Stage_49362_Name = {
    Text = "落果・夢語りの三"
  },
  Stage_49363_Desc = {
    Text = "受粉、それは遠方の邂逅。\n花の枝は揺れながら舞の使者を誘い、花粉を摘み取らせ、花々の間を漂わせる。\nそして自然の律動の中で、新たな命の源を、待ち望む別の懐へと届ける。"
  },
