  Stage_49369_Desc = {
    Text = "幼根、それは無鉄砲な冒険。\n種子は、一寸先の土が肥沃な黒土なのか、冷たい荒れ地なのかを知らない。\nただ、果てしなく、恐れずに、大地へと根の先端を伸ばしていく。"
  },
