  },
  Stage_51645_Desc = {
    Text = "見えざる災厄が蘇り、物理世界の歴史と存在は、深淵へと沈みゆく。"
  },
  Stage_51645_Name = {
    Text = "融災禁区・第2波・Ⅳ級警報"
  },
  Stage_51646_Desc = {
    Text = "見えざる災厄が蘇り、物理世界の歴史と存在は、深淵へと沈みゆく。"
  },
  Stage_51646_Name = {
    Text = "融災禁区・第1波・Ⅳ級警報"
  },
  Stage_51761_Desc = {
    Text = "最後に彼女はかつて、王の像が立っていた場所を見つめた。\nそこに像はなく、王もまたいなかった。"
  },
  Stage_51761_Name = {
    Text = "夢はリモリアへと帰る"
  },
  Stage_51762_Desc = {
    Text = "像は彼女と遠くから見つめ合っている。\n彼らの間を長い時間と覚めない夢が隔てている。"
  },
  Stage_51762_Name = {
    Text = "暗色の彫像"
  },
  Stage_51763_Desc = {
    Text = "希望はリモリアで最も貴重な毒薬だ。\n彼らは狂ったように歌い、飲み干し、甘んじて受け入れる。"
  },
  Stage_51763_Name = {
    Text = "祭司の儀式"
  },
  Stage_51764_Desc = {
    Text = "星々、運命、神々……彼らを前に、公平という言葉は無意味だ。"
  },
  Stage_51764_Name = {
    Text = "嘘の美徳"
  },
  Stage_51765_Desc = {
    Text = "雨の中での苦しみ。\n雨の中での別れ。"
  },
  Stage_51765_Name = {
    Text = "雨の中で"
  },
  Stage_51766_Desc = {
    Text = "お応えください、主よ。わたくしの一番大切なものを捧げます。"
  },
  Stage_51766_Name = {
    Text = "王への献上"
  },
  Stage_51767_Desc = {
    Text = "食べよ、と彼の者は告げた。卑しい温情を、調理された運命を。"
  },
  Stage_51767_Name = {Text = "魚"},
  Stage_51768_Desc = {
    Text = "かの神格の意志は星々の網のように交差する。\nかの神格は永遠の虚無の中で汝が夢に至るのを待つ。"
  },
  Stage_51768_Name = {
    Text = "深海にて祈る"
  },
  Stage_51769_Desc = {
    Text = "祈りは、リモリア人が生まれて最初に学ぶことだ。"
  },
  Stage_51769_Name = {Text = "予言"},
  Stage_51770_Desc = {
    Text = "その平和な至福の地で、昔の親友たちは互いに見つめ合っていた。\n彼らは手を取り合い、共に神の国への階段を登る。"
  },
  Stage_51770_Name = {Text = "親友"},
  Stage_51771_Desc = {
    Text = "血。涙。祭祀。狂乱。殺戮。\nまた星々の物語が始まるが、星々は気にも留めない。\nそれらは永遠に輝き続ける。"
  },
  Stage_51771_Name = {
    Text = "聞け、星々の声を"
  },
  Stage_51772_Desc = {
    Text = "彼女は彼女の最良の友人だった。\nずっとそうだった。"
  },
  Stage_51772_Name = {Text = "旧友"},
  Stage_51773_Desc = {
    Text = "飲め、この甘美な酒を。踊れ、この熱烈な舞を。\n故国の祭司は祭殿に歩み入り、新たな信徒を撫でる。"
  },
  Stage_51773_Name = {Text = "血の宴"},
  Stage_51774_Desc = {
    Text = "霧が求道者の顔を覆い、霧が王を求める者の心を覆う。"
  },
  Stage_51774_Name = {
    Text = "霧に潜む者"
  },
  Stage_51775_Desc = {
    Text = "在りし日の宮殿は消え去り、在りし日の夢はむなしく響きだけが残る。\n枯れた玉座には王の死体だけがあり、昔話を語っている。"
  },
  Stage_51775_Name = {
    Text = "在りし日の幻"
  },
  Stage_51785_Desc = {
    Text = "見えざる災厄が蘇り、物理世界の歴史と存在は、深淵へと沈みゆく。"
  },
