    Text = "生け花、刺繍、茶道……彼女の生活は無意味な記号で構成されている。\n「おはよう、ソレールさん」「すごいですね、ソレールさん」……\n作り笑いの声は厚い水槽のように、彼女を永遠に閉じ込める。"
  },
