    Text = "長い夜は冷たく、血の匂いがする。暗闇の怪物たちは腹を空かせている。\nこれは肥えすぎ、あれは痩せすぎ——次の獲物は、誰だ？"
  },
  Stage_55575_Name = {
    Text = "寒夜・第二幕"
  },
  Stage_55576_Desc = {
    Text = "昏く淀み、枯れ果てた雪山の凍土は、あらゆる生命を絶やす。\nしかし、生命の意志は強靭だ。\n雪解けの雫が落ちるとき、不屈の種子が山頂に芽吹く。"
  },
  Stage_55576_Name = {
    Text = "破土・第六幕"
  },
  Stage_55577_Desc = {
    Text = "鏡の中の二頭の獣が出会い、互いに牙を剥く。\n額と額ををぶつけ合い、互いに負けを認めない。\n傲慢なあなた、惨めな私。\n手が重なったその刹那、鏡が砕け散る。\n獣は低く唸り、深紅の双眸を剥き出しにする。"
  },
