  Stage_55585_Desc = {
    Text = "昏く淀み、枯れ果てた雪山の凍土は、あらゆる生命を絶やす。\nしかし、生命の意志は強靭だ。\n雪解けの雫が落ちるとき、不屈の種子が山頂に芽吹く。"
  },
  Stage_55585_Name = {
    Text = "破土・第四幕"
  },
  Stage_56404_Desc = {
    Text = "マーフィーは自分が一人目の聖女ではないと聞いた。\n数千年の時の中、同じ運命の無数の少女の身体の中で鼓動が騒ぎ立ててきたのだ。\n幾千もの時空で、幾千もの心臓が重なり合って鼓動する。"
  },
  Stage_56404_Name = {
    Text = "時空の裂け目・超難度"
  },
  Stage_56404_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_56405_Desc = {
    Text = "そこは、すべての命にとって最後の威厳ある安息の地だ。\n深海を棺とし、天地を敷物として、偉大な神は海流に葬られた。"
  },
  Stage_56405_Name = {
    Text = "聖骸布・超難度"
  },
  Stage_56405_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_56407_Desc = {
    Text = "神は無言で、そして無心に降臨した。\n神の心臓は彼女の血脈の中で、何も渇望することなく、生存の鼓動を続けていた。"
  },
  Stage_56407_Name = {
    Text = "神の降臨・超難度"
  },
  Stage_56407_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_56408_Desc = {
    Text = "彼女は空高くにある星々を数えながら、望んでいない「その時」を待っていた。\n「星辰正しき刻」、星々が海面に昇る時、彼女は星々の中の一つとなるだろう。"
  },
  Stage_56408_Name = {
    Text = "黄色い星・超難度"
  },
  Stage_56408_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_56409_Desc = {
    Text = "彼女には、自身の胸郭に植え付けられた胚胎の運命を決める権利がなかった。\n逃げる場所を決める権利も、誰の手を握るかを決める権利も、誰と共に流浪するかを決める権利もなかった。海上の幻影の運命の前では、誰もがただ生贄の子羊にすぎない。"
  },
  Stage_56409_Name = {
    Text = "生贄の子羊・超難度"
  },
  Stage_56409_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_56410_Desc = {
    Text = "彼女の処刑は、断頭台である必要はない。\n彼女を自らの手で殺したのは、彼女の母親だ。"
  },
  Stage_56410_Name = {
    Text = "処刑人・超難度"
  },
  Stage_56410_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_56411_Desc = {
    Text = "静けさ。静けさ。静けさ。氷の下では、すべてが永遠だ。呼吸さえも凍りつく。\nここでは生と死は同義である……休眠と復活に何の違いもないように。\nアイズルワースでは、彼女の春は永遠に訪れない。"
  },
  Stage_56411_Name = {
    Text = "休眠・超難度"
  },
  Stage_56411_StageInitStateText = {
    Text = "海の悪夢"
  },
