    Text = "常識に反して、現実の世界ではアリバイがないほうがかえって安全な場合もある。\n確固たる証拠さえなければ、警察は犯人を逮捕できないのだから。\nだからこそ犯人諸君よ、その無意味な小細工はもうやめたまえ！"
  },
  Stage_57395_Name = {
    Text = "アリバイの証明・超難度"
  },
  Stage_57396_Desc = {
    Text = "「語り手である私が犯人だ」——\nなんとも陳腐な手口だ。美しさも技術もないじゃないか。\n不運なことに今回もまた、私がそれに出くわしてしまった。"
  },
  Stage_57396_Name = {
    Text = "叙述トリック・超難度"
  },
  Stage_57397_Desc = {
    Text = "探偵の掟 第一条：見た目が平凡で気弱な依頼人ほど、背後の事件は大きい。\n見た目で判断するなかれ。"
  },
  Stage_57397_Name = {
    Text = "招かれざる客・超難度"
  },
  Stage_57398_Desc = {
    Text = "事件現場で首なし死体や顔のない死体を見つけたなら、疑う余地はない——\nその身元は、間違いなくすり替えられている。"
  },
  Stage_57398_Name = {
    Text = "首なし死体・超難度"
  },
  Stage_57399_Desc = {
    Text = "平凡な容貌、平凡な経歴、平凡な名前……\nそれらすべてが一人に集中するなら、安心してその人を犯人候補から除外していい。\n理由は聞くな。"
  },
  Stage_57399_Name = {
    Text = "幸運な凡人・超難度"
  },
  Stage_57400_Desc = {
    Text = "1，2，3……\n5人目が殺されても、賢いこの私でさえ事件を解けなかった。\nなぜかって？この動揺には10番まであるからね。"
  },
  Stage_57400_Name = {
    Text = "見立て殺人・超難度"
  },
  Stage_57401_Desc = {
    Text = "機械の仕掛け、室内に潜む犯人、他殺に見せかけた自殺……\n正直、密室にそれほど手間をかけるなら、殺し屋を雇った方が早いのでは？"
  },
  Stage_57401_Name = {
    Text = "密室の謎・超難度"
  },
  Stage_57402_Desc = {
    Text = "警察官の友人を疎んではならない。\n推理の世界では、彼らはたいてい犯人に振り回される役回りだ。\nその最大の役割は……真犯人ではない容疑者を、真っ先に除外してくれることだ。"
  },
  Stage_57402_Name = {
    Text = "探偵の友・超難度"
  },
  Stage_57403_Desc = {
    Text = "これまでの推理の心得を読み、それでも探偵への情熱が冷めないのなら……\n幸運を祈るよ。救いようのない、愛すべきバカめ。"
  },
  Stage_57403_Name = {
    Text = "後記・超難度"
  },
  Stage_57673_Desc = {
    Text = "親友の裏切り、兄弟の争い、愛憎の果て……彼は歪んだ感情を啜り、自然主義者を自称する。\n「これは最も純粋な真実の感情です。無添加の天然もの、味は素朴で爽やかなのです」"
  },
  Stage_57673_Name = {
    Text = "THE 悲劇 SHOW"
  },
  Stage_57674_Desc = {
    Text = "すべての不可能なことを消去すれは、残るのは真実だけだ。\nもちろん、量子物理学者は意義を唱えるだろうが。"
  },
  Stage_57674_Name = {
    Text = "真実はいつもひとつ"
  },
  Stage_57675_Desc = {
    Text = "「もし……だったら……」は探偵が最も嫌うフレーズだ。\nそれは失敗や後悔、そして苦い酒を連想させる。だから彼はすでに酒を断っている。"
  },
  Stage_57675_Name = {
    Text = "現実の下で"
  },
  Stage_57676_Desc = {
    Text = "すべての人に好かれるのは大したものだ。すべての人に嫌われるのも同じように大したものだ。\n彼は、その両方をたやすくやってのける。さすがだ、来週の月曜日の男！"
  },
  Stage_57676_Name = {
    Text = "来週の月曜日の男"
  },
  Stage_57677_Desc = {
    Text = "彼は昨日であり、同時に今日をも知っている。\n彼は神々と共に在り、その命に終わりはない。"
  },
  Stage_57677_Name = {
    Text = "棺の中の壁"
  },
  Stage_57678_Desc = {
    Text = "人間は鈍い生き物だ。\n彼らの間に一枚の板を立てるだけで、もう互いの気配すら感じ取れない。"
  },
  Stage_57678_Name = {
    Text = "最初の会合"
  },
  Stage_57679_Desc = {
    Text = "8人の小さな兵士が、蝋燭を灯して、夜遅くまで起きていた。\n首を吊って、ひとりが減り、8人が7人になった。"
  },
  Stage_57679_Name = {
    Text = "そして誰もいなくなった"
  },
  Stage_57681_Desc = {
    Text = "彼らは皆死地にあり、共に往生を望んでいる。"
  },
  Stage_57681_Name = {
    Text = "最後の挨拶"
  },
  Stage_57682_Desc = {
    Text = "古い屋敷と幽霊の関係は、チーズとベーコンのようなものだ。\nどちらが先かは知らないが、気づいたときには、もう切り離せない。"
  },
  Stage_57682_Name = {
    Text = "幽霊の館"
  },
  Stage_57683_Desc = {
    Text = "それは単に、結果や立場からいわゆる「原因」を逆算しているにすぎない。\n人類の歴史では、こうした滑稽な茶番が至るところで繰り返されてきた。"
  },
  Stage_57683_Name = {
    Text = "逆向の推理"
  },
  Stage_57684_Desc = {
    Text = "彼らは皆、死地にありながら、同時に死後の安らぎを望んでいる。"
  },
  Stage_57684_Name = {
    Text = "最後の挨拶"
  },
  Stage_57685_Desc = {
    Text = "幸運を祈ってますよ、探偵さん。\nまたお会いしましょう。"
  },
  Stage_57685_Name = {
    Text = "幸運を！"
  },
  Stage_57686_Desc = {
    Text = "試験の度に、私は災厄を期待している。\n洪水、台風、隕石の衝突……何でもいい、現実を少し変えてくれるのなら。ほんの少しだけ。"
  },
  Stage_57686_Name = {
    Text = "招かれざる客"
  },
  Stage_57687_Desc = {
    Text = "彼らは皆、死地にありながら、同時に死後の安らぎを望んでいる。"
  },
  Stage_57687_Name = {
    Text = "最後の挨拶"
  },
  Stage_58064_Desc = {
    Text = "愚かな者たちよ——あなたたちは自ら炎をつけ、希望と救済を灰にした。\nあなたたちが暗闇の死の中で苦しむ時、その「正義」とやらの味は如何なものか？"
  },
  Stage_58064_Name = {
    Text = "懺悔・超難度"
  },
  Stage_58064_StageInitStateText = {Text = "繁殖"},
  Stage_58065_Desc = {
    Text = "愚かな者たちよ——あなたたちは自ら炎をつけ、希望と救済を灰にした。\nあなたたちが暗闇の死の中で苦しむ時、その「正義」とやらの味は如何なものか？"
  },
  Stage_58065_Name = {
    Text = "懺悔・第六幕"
  },
  Stage_58066_Desc = {
    Text = "彼らは理解を拒み、寛容を拒む——彼らの世界には白と黒しかなく、その定義すら己で制御できないにもかかわらず。\n「焼き殺せ、焼き殺せ！」「この異端の司教を焼き殺せ！邪悪を滅ぼせ！」"
  },
