  Stage_58365_Desc = {
    Text = "「僕は何も持ってないから」片目の浮浪児は言った。「この花だけが、偉大な女王様に捧げられるものです」彼女は白いフリージアを受け取ったが、困惑を覚えた。\nその光景は、彼女の記憶の奥底で何度も繰り返されていたように思えた。\nまるで、ミノタウロスを閉じ込めた迷宮のように、繰り返し、循環していた。"
  },
