    Text = "イサラウはこうして消えた。まるで最初から存在しなかったかのように。\n街も、民も、すべては幻だった。それらは彼女の夢から生まれ、日々の描写で具現化し、そして——「バン——」夢が醒めた。\nイサラウを見たことなどないのだ……自分自身を見たことがないのと同じように。"
  },
