  },
  Stage_58443_Name = {
    Text = "爬虫類脳・超難度"
  },
  Stage_58444_Desc = {
    Text = "それは、彼女の魂の中にある忌まわしい領域の象徴となっていた。\n彼女はそれと共に苦しみ、共に死に、ある意味ではそれと共に消えていった。\nだからこそ、彼女の心は石のように冷たく、容赦がなかった。"
  },
  Stage_58444_Name = {
    Text = "爬虫類脳・第六幕"
  },
  Stage_58445_Desc = {
    Text = "それは、彼女の魂の中にある忌まわしい領域の象徴となっていた。\n彼女はそれと共に苦しみ、共に死に、ある意味ではそれと共に消えていった。\nだからこそ、彼女の心は石のように冷たく、容赦がなかった。"
  },
  Stage_58445_Name = {
    Text = "爬虫類脳・第五幕"
  },
  Stage_58446_Desc = {
    Text = "それは、彼女の魂の中にある忌まわしい領域の象徴となっていた。\n彼女はそれと共に苦しみ、共に死に、ある意味ではそれと共に消えていった。\nだからこそ、彼女の心は石のように冷たく、容赦がなかった。"
  },
  Stage_58446_Name = {
    Text = "爬虫類脳・第四幕"
  },
  Stage_58449_Desc = {
    Text = "余韻が天地に満ちる。\n命を代償に、彼の楽章は天上の宮殿に延々と響き渡る。"
  },
  Stage_58449_Name = {
    Text = "余韻・超難度"
  },
  Stage_58450_Desc = {
    Text = "幕が下りる。\n凛として、彼は紅いビロードの幕の向こうに消えていった。"
  },
  Stage_58450_Name = {
    Text = "幕切れ・超難度"
  },
  Stage_58451_Desc = {
    Text = "これが「第四門」\n第四門に入る者は「彼」の真の姿を見る。\n宇宙の壮大さを見て、自分の小ささを理解する。蟻が大木を揺るがすのではない。"
  },
  Stage_58451_Name = {
    Text = "知と行の門・超難度"
  },
  Stage_58452_Desc = {
    Text = "人形の家へようこそ、ここには千の同じ笑顔があります。\nふふ、どれがあなたのかつての友達ですか？"
  },
  Stage_58452_Name = {
    Text = "人形の家・超難度"
  },
  Stage_58453_Desc = {
    Text = "この世には最初から扉など無いのです。\n扉を求める人が増えれば、さまざまな扉が生まれる。\n誰もが自分の扉の背後こそが天国だと言います。\nしかし、古い予言はすでに言っています、この世に扉など存在しないことを。\n人間の中に天国を築こうとする者は、最終的には地獄の扉を開いてしまうでしょう。"
  },
  Stage_58453_Name = {
    Text = "混沌の予言・超難度"
  },
  Stage_58454_Desc = {
    Text = "人形の手には糸が垂れ下がり、世界のパーツを繋いでいる。\nカチッ、ザー、指を動かすと、世界が崩壊する。\n一体何が人形の頭上に垂れているのか、それが常に虚無に舞いを捧げ続ける。"
  },
  Stage_58454_Name = {
    Text = "傀儡線・超難度"
  },
  Stage_58455_Desc = {
    Text = "軽快楽章。\n彼らは大地で躍動し、抗う姿は、かくも美しい。"
  },
  Stage_58455_Name = {
    Text = "メヌエット・超難度"
  },
  Stage_58456_Desc = {
    Text = "これが「第三門」\n第三門に入る者は浅薄な理性に拘らず、境界の外の知識を知ることができる。"
  },
  Stage_58456_Name = {
    Text = "理智の門・超難度"
  },
  Stage_58457_Desc = {
    Text = "跳べ、跳べ、止まらないで。\nスカートをひらひらさせ、円を描いて、なぜならこの世界はもう渦の中で回転し続けているから。\nすべての心配を手放し、最後の狂歓に加わろう。\n全力で踊れば、永遠の夕陽が見えるであろう。"
  },
  Stage_58457_Name = {
    Text = "狂乱舞踏会・超難度"
  },
  Stage_58458_Desc = {
    Text = "ソナタ形式。\n一つが三つへと分裂し、三角の中から見開かれた眼が大地を見下ろす。"
  },
  Stage_58458_Name = {
    Text = "アレグロ・超難度"
  },
  Stage_58459_Desc = {
    Text = "彼女は王が予言したすべてを手にした——強大な力と、揺るぎない信仰を。\nかつて王を疑った罪を背負い、神国を迎える旅路へと踏み出した。"
  },
  Stage_58459_Name = {
    Text = "信仰・超難度"
  },
  Stage_58459_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_58460_Desc = {
    Text = "これが「第五門」\n第五門に入る者は宇宙と最高の秘密を共有する。\n万物は「彼」の一息一吐であり、それによって消滅する。"
  },
  Stage_58460_Name = {
    Text = "帰一の門・超難度"
  },
  Stage_58461_Desc = {
    Text = "彼女は手を差し伸べ、あなたを舞の伴に誘う。\n前へ——後へ——この絶妙な呼吸は、あなた達二人だけのもの。\nその手をそっと握り、彼女のステップに合わせる。\n紳士的に、決して頭を垂れてはならない。\n——たとえ、足元がすでに崖の縁であったとしても。"
  },
  Stage_58461_Name = {
    Text = "招待・超難度"
  },
  Stage_58462_Desc = {
    Text = "これが「第六門」\n第六門に入る者は諸世界を貫き、無数の次元で永遠の存続を求める。"
  },
  Stage_58462_Name = {
    Text = "諸世の門・超難度"
  },
  Stage_58463_Desc = {
    Text = "叙情的な楽章。\n育み、繁栄し、命は絶えることなく続く。"
  },
  Stage_58463_Name = {
    Text = "アダージョ・超難度"
  },
  Stage_58464_Desc = {
    Text = "旅立とう。\nこれが「智慧」への道か「愚かさ」への道か、旅をしてみなければ分からない。"
  },
  Stage_58464_Name = {
    Text = "旅立ち・超難度"
  },
  Stage_58465_Desc = {
    Text = "交響曲は、一人では成り立たない。\n弦楽器、木管楽器、金管楽器、打楽器。\n整然とした楽器群が頭を垂れ、彼の導きを待っていた。"
  },
  Stage_58465_Name = {
    Text = "管弦楽団・超難度"
  },
  Stage_58466_Desc = {
    Text = "音を辿り、指揮台へ上がった。足取りは揺るがず、胸には確信があった。\n夢ゆえに来たと知る者はなく、夢の主はすでに迷いの淵に沈んでいる。"
  },
  Stage_58466_Name = {
    Text = "迷夢の導き・超難度"
  },
  Stage_58467_Desc = {
    Text = "これが「第一門」\n第一門に入る者は枷を断ち、本性を捨て、自身を忘れねばならない。\n個体の視野には荒唐な真実を支える力がない。"
  },
  Stage_58467_Name = {
    Text = "本性の門・超難度"
  },
  Stage_58468_Desc = {
    Text = "これが「第二門」\n第二門に入る者は軽々しく是非を断定するな。\n是非は規則制定者の臆断に過ぎず、真理はすべての知識を超える。"
  },
  Stage_58468_Name = {
    Text = "是非の扉・超難度"
  },
  Stage_58469_Desc = {
    Text = "輪舞曲の形式。\n彼は滅びの果てへと導き、破滅を見据える。"
  },
  Stage_58469_Name = {
    Text = "終曲・超難度"
  },
  Stage_58470_Desc = {
    Text = "神国の輪郭が彼女の目の前に現れる。神国の鐘の音が彼女の耳に響き渡る。\n彼女は王の予言を実行し、決して止まらない。\n彼女はこの言葉によって、この人生の茫漠たる暗夜を乗り越える。"
  },
  Stage_58470_Name = {
    Text = "降臨・超難度"
  },
  Stage_58470_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_58471_Desc = {
    Text = "終末が到来し、世界は膿で満ち、衰亡の渦がすべての生き物を巻き込む。\n祈りましょう、探しましょう、存在しない生存の扉を。"
  },
  Stage_58471_Name = {
    Text = "狂災・超難度"
  },
  Stage_58472_Desc = {
    Text = "すべてを失ったその日彼女はついに悟った。王だけがリモリアの民を救えるのだと。\n彼女は待ち続けている。あの遥かなる神国で、失われたすべてと再会するその時を。"
  },
  Stage_58472_Name = {
    Text = "証明・超難度"
  },
  Stage_58472_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_58473_Desc = {
    Text = "リモリアは滅亡した。神は一度たりとも、この地を気にかけてなどいなかった。\n神の国など、最初から存在しなかったのだ。"
  },
  Stage_58473_Name = {
    Text = "動揺・超難度"
  },
  Stage_58473_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_58474_Desc = {
    Text = "なぜ捨てない？なぜ最初から愚か？\n……彼らを守るためか。\nそれがお前の答えなら、お前は骨も血も、知恵も、すべてを捧げるだろう。"
  },
  Stage_58474_Name = {
    Text = "扉の中・超難度"
  },
  Stage_58475_Desc = {
    Text = "粘っこい暗闇に星が一つ、ぶら下がっています。\nその星は膨張し、光り、大きな綿菓子になります。\nこれは誰かが一生をかけて凝縮した愛と憎しみです、一口どうですか？"
  },
  Stage_58475_Name = {
    Text = "星星・超難度"
  },
  Stage_58476_Desc = {
    Text = "祈りはリモリア人が最初に学ぶことだ。\nしかし、彼女の前に現れて、彼女を守るのは決して彼女の王ではなかった。"
  },
  Stage_58476_Name = {
    Text = "疑惑・超難度"
  },
  Stage_58476_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_58477_Desc = {
    Text = "無数の人が真実を渇望し、堕ちていく。\n無数の人が真実のかけらを手にし、盲目の目が光を得たと思い込み、天国の美しさを語る。\nただ彼女だけが真実の酒を見つけ、その極上の美酒を一口飲み下した。\nごくり。\n彼女は朦朧と酔いしれ、毒がその身の奥深く入り込む。\nそう、無数の愚か者たちがすでに証明していた。真実は毒の杯に過ぎない。\n少し飲めば毒が回り、多く飲めば死に至る。\n今や彼女に残された日は少なく、ただあなたと共に味わう事を望む。"
  },
  Stage_58477_Name = {
    Text = "真実の毒・超難度"
  },
  Stage_58478_Desc = {
    Text = "花火のように咲き誇れ、たとえ燃料が生命であっても。\n終点が似ているのなら、長い苦痛を省いて、輝かしい光を代えよう。"
  },
  Stage_58478_Name = {
    Text = "光輝く消滅・超難度"
  },
  Stage_58479_Desc = {
    Text = "これが「第七門」\n時間の流れがここで止まり、永遠の知恵がさまよう探求者を深い迷いから導き出す。"
  },
  Stage_58479_Name = {
    Text = "窮地の門・超難度"
  },
  Stage_58480_Desc = {
    Text = "幕が上がる——この曲の魂を見極めよう。\n彼は語るだろう、始まりと終焉を。すべての息吹を。"
  },
  Stage_58480_Name = {
    Text = "序曲・超難度"
  },
  Stage_58691_Desc = {
    Text = "風は凪ぎ、雪は解け、万物が芽吹く。"
  },
  Stage_58691_Name = {
    Text = "そして春"
  },
  Stage_58692_Desc = {
    Text = "慟哭か、戦慄か。これは戦士が山々に叩きつけた宣戦布告だ。"
  },
  Stage_58692_Name = {Text = "棘の山"},
  Stage_58693_Desc = {
    Text = "服を風にはためかせ、迷いの中で彼女は静かに現れた。"
  },
  Stage_58693_Name = {Text = "再会"},
  Stage_58694_Desc = {
    Text = "敵の姿はない。だが、敵はあなたたちの姿を捉えた。"
  },
  Stage_58694_Name = {Text = "黒い影"},
  Stage_58695_Desc = {
    Text = "持っておいで、我が子よ。山が呼んでいる。\n母の優しき呼びかけに応え、運命の懐へ帰れ。"
  },
  Stage_58695_Name = {
    Text = "山々の呼び声"
  },
  Stage_58696_Desc = {
    Text = "彼らの物語を知る者はなく、その名を悼む者もいない。"
  },
  Stage_58696_Name = {Text = "生贄"},
  Stage_58697_Desc = {
    Text = "礼儀正しい訪問にもかかわらず、アイズルワースはあなたたちを歓迎していないようだ。"
  },
  Stage_58697_Name = {
    Text = "雪原の来訪者"
  },
  Stage_58698_Desc = {
    Text = "月光と雪の狭間に、血が第三の色を刻む。"
  },
  Stage_58698_Name = {
    Text = "果てなき寒夜"
  },
  Stage_58699_Desc = {
    Text = "どちらがより危険か、判断するのは難しい。"
  },
  Stage_58699_Name = {
    Text = "敵か味方か"
  },
  Stage_58700_Desc = {
    Text = "哀悼、または驚嘆。これは戦士が山々に向けた宣戦布告だ。"
  },
  Stage_58701_Desc = {
    Text = "慟哭か、戦慄か。これは戦士が山々に叩きつけた宣戦布告だ。"
  },
  Stage_58701_Name = {Text = "棘の山"},
  Stage_58976_Desc = {
    Text = "「君を見守ろう——迷いなくこの絶望の道を歩む、その後ろ姿を。……君の葬儀で、君を悼もう。」"
  },
  Stage_58976_Name = {
    Text = "存続の道"
  },
  Stage_58977_Desc = {
    Text = "「劇場の数多くの演出が好きだ。だが一番好きなのは、最も美しい陶器を屋根裏から投げ落とす瞬間だ」"
  },
  Stage_58977_Name = {Text = "父と娘"},
  Stage_58978_Desc = {
    Text = "険しく、長く、虚ろな道。誰もが自らの道と向き合わねばならない。\nついに起点に立ったとき、君はその先を見据える勇気を持てるか？"
  },
  Stage_58978_Name = {Text = "旅路"},
  Stage_58979_Desc = {
    Text = "拍子。旋律。弦楽器の柔らかな倍音があなたたちの脳裏に満ちる。\n観客の静かな視線の中、指揮者は舞台に立つ。"
  },
  Stage_58979_Name = {Text = "指揮者"},
  Stage_58980_Desc = {
    Text = "彼の衰えた身体は、沸き立つ地底深くに沈んだ。\n幻の次元で、彼は一人、昏き海と対峙した。"
  },
  Stage_58980_Name = {Text = "残骸"},
  Stage_58981_Desc = {
    Text = "音の乱れ、役割の欠落……たった一つのミスで、すべてが瓦解する。\n練習。無数の練習を重ね、君への喝采を待て。"
  },
  Stage_58981_Name = {
    Text = "リハーサル"
  },
  Stage_58982_Desc = {
    Text = "忘却はこの世界の最後の浄化だろうか？ミサゴ大学は断じて認めない。\nこの学び舎に生きる者たちは、記憶のために戦う。"
  },
  Stage_58982_Name = {
    Text = "忘却の理"
  },
  Stage_58982_StageInitStateText = {Text = "終末"},
  Stage_58983_Desc = {
    Text = "軽快な舞曲、愉悦に満ちた冗談、変化に乏しい凡庸な一曲。\nそう、第三楽章でひと息つけ。ここは安全で、静かで、何一つ驚きはない。"
  },
  Stage_58983_Name = {
    Text = "第三楽章"
  },
  Stage_58984_Desc = {
    Text = "哀願も逃避もできない。これがこの世界の運命だ。\nこれを打ち破れ。これを滅ぼせ。そして——これを救え。"
  },
  Stage_58985_Desc = {
    Text = "あらかじめ知らされたどんでん返しは勢いを失うが、彼は気にしない。\n彼が期待する悦びは、ここにはないのだから。"
  },
  Stage_58985_Name = {
    Text = "デクスター式の転換"
  },
  Stage_58986_Desc = {
    Text = "シーッ。\n最後の観客が着席した。本物の演奏が、今始まる。"
  },
  Stage_58986_Name = {Text = "入場"},
  Stage_58987_Desc = {
    Text = "情報が不均衡なとき、完璧であるほど、それは誤りに近づく。"
  },
  Stage_58987_Name = {
    Text = "優等生、問題児"
  },
  Stage_58988_Desc = {
    Text = "「ミサゴ大学はレオ王国政府およびミスティア協定審査会の管轄外である。無許可での侵入はすべて違法侵入とみなし、ミサゴ大学は自衛権を完全に行使する権利を有する」"
  },
  Stage_58988_Name = {Text = "校則"},
