  },
  Stage_59502_Desc = {
    Text = "あなたたちの最初の絶望に直面せよ。あなたたちの最初の恐怖に直面せよ。\n見えない互いのそばに立ち、それから彼に打ち勝て。"
  },
  Stage_59502_Name = {
    Text = "決戦：原初の影"
  },
  Stage_59503_Desc = {
    Text = "記憶は誓い、忘却は儀式。"
  },
  Stage_59503_Name = {Text = "儀式"},
  Stage_59504_Desc = {
    Text = "夢の神殿に立ち、崩れた遺跡を支える。\nあなたの心がけと愛情を乗せた塵を守る。"
  },
  Stage_59504_Name = {
    Text = "夢の崩壊"
  },
  Stage_59505_Desc = {
    Text = "「生存か、破壊か？」"
  },
