  },
  Stage_59511_Name = {Text = "儀式"},
  Stage_62348_Desc = {
    Text = "これは星々の頂点。これは宇宙の終幕。\n耳を澄ませ——真の音が、あなたには聴こえるか？"
  },
  Stage_62348_Name = {Text = "終曲"},
  Stage_66016_Desc = {
    Text = "彼は至高の意志、宇宙の創造主、万物の終焉者である。\n彼の前で泣きなさい。あなたたちの弱き勇気のために、彼の無限の権力のために。"
  },
  Stage_66016_Name = {
    Text = "ワークハウス・悲泣の視線"
  },
  Stage_66017_Desc = {
    Text = "彼は至高の意志、宇宙の創造主、万物の終焉者である。\n彼の前で泣きなさい。あなたたちの弱き勇気のために、彼の無限の権力のために。"
  },
  Stage_66017_Name = {
    Text = "ワークハウス・悲泣の視線"
  },
  Stage_66018_Desc = {
    Text = "彼は至高の意志、宇宙の創造主、万物の終焉者である。\n彼の前で泣きなさい。あなたたちの弱き勇気のために、彼の無限の権力のために。"
  },
  Stage_66018_Name = {
    Text = "ワークハウス・悲泣の視線"
  },
  Stage_66381_Desc = {
    Text = "心配する必要はない、恐れは生物の最も原始的な本能である。\n神は決して一匹の蟻を苦しめない。彼はあなたたちに目覚めを祝福する。"
  },
  Stage_66381_Name = {
    Text = "蝋人形館・恐怖の視線"
  },
  Stage_66382_Desc = {
    Text = "歌いましょう、偉大なる創造主よ！\n彼が夢に入るとき、民は繁栄する。\n彼が目を覚ますと、すべてが塵に変わる。"
  },
  Stage_66382_Name = {
    Text = "ブリルポート・邪信の視線"
  },
  Stage_66383_Desc = {
    Text = "痛みを感じよ、至高の意志の最も純粋な贈り物を感じよ。\n痛みの中で、創造主の威厳を覗き見る。"
  },
  Stage_66383_Name = {
    Text = "ライ・刺骨の視線"
  },
  Stage_66384_Desc = {
    Text = "苦しむ必要はない。抗う必要はない。理解できないものを理解しようとする必要はない。\n至高の意志の視線の中で、夢の終わりを迎えよ。"
  },
  Stage_66384_Name = {
    Text = "療養所・奇怪の視線"
  },
  Stage_66385_Desc = {
    Text = "彼は至高の意志、宇宙の創造主、万物の終焉者である。\n彼の前で泣きなさい。あなたたちの弱き勇気のために、彼の無限の権力のために。"
  },
  Stage_66385_Name = {
    Text = "ワークハウス・悲泣の視線"
  },
  Stage_67123_Desc = {
    Text = "その壮大な文明、その人間の悲喜、あなたを遠ざける無数の人々は、かつて存在しなかった。夢の解消が、最終的に生まれる。\n忘れよ、守秘者たち。忘却は最も隆盛な苦痛である。\n忘却は至福の解毒剤。"
  },
  Stage_67123_Name = {
    Text = "ヴォルムワヒ・顕現の視線"
  },
  Stage_67124_Desc = {
    Text = "盲目的で愚かな洪流の上で、秩序の楼閣は轟然と崩れ落ちる。\n理性は存在せず、ただ狂気があなたたちの帰宿である。"
  },
