    Text = "療養所・奇怪の視線"
  },
  Stage_67909_Desc = {
    Text = "苦しむ必要はない。抗う必要はない。理解できないものを理解しようとする必要はない。\n至高の意志の視線の中で、夢の終わりを迎えよ。"
  },
  Stage_67909_Name = {
    Text = "療養所・奇怪の視線"
  },
  Stage_67910_Desc = {
    Text = "心配する必要はない、恐れは生物の最も原始的な本能である。\n神は決して一匹の蟻を苦しめない。彼はあなたたちに目覚めを祝福する。"
  },
  Stage_67910_Name = {
    Text = "蝋人形館・恐怖の視線"
  },
  Stage_67911_Desc = {
    Text = "盲目的で愚かな洪流の上で、秩序の楼閣は轟然と崩れ落ちる。\n理性は存在せず、ただ狂気があなたたちの帰宿である。"
  },
  Stage_67911_Name = {
    Text = "ソナニール号・狂気の視線"
  },
  Stage_67912_Desc = {
    Text = "その壮大な文明、その人間の悲喜、あなたを遠ざける無数の人々は、かつて存在しなかった。夢の解消が、最終的に生まれる。\n忘れよ、守秘者たち。忘却は最も隆盛な苦痛である。\n忘却は至福の解毒剤。"
  },
  Stage_67912_Name = {
    Text = "ヴォルムワヒ・顕現の視線"
  },
  Stage_67913_Desc = {
    Text = "蟻にとって生存と破壊は問題ではありません。\n彼らは巨大な木々に立ち向かうために生まれてきたのです。"
  },
  Stage_67913_Name = {Text = "蟻"},
  Stage_67914_Desc = {
    Text = "%hisorher%の名前と功績は誰にも知られない。{Male=彼,Female=彼女}は忘却から来て、忘却に戻る。墓石の墓碑銘だけが永遠に残る。\nシルバーキーは%hisorher%の進む道を指し示す。未来の道も。銀の鍵の導きがあらんことを。"
  },
