  Stage_70108_Desc = {
    Text = "再生花、それは永遠の循環。\n命の最盛期にこそ、忘れてはならない——昼と夜の秘密も、季節のささやきも、花が散るとともに衰え果てる。死を終わりとすることは、すなわち誕生を始まりとすること。"
