  Stage_70432_Desc = {
    Text = "黒猫は背中を丸め、四肢を動かし始めた。\nどうやらこの黒猫は自分の体をしっかりと制御できるようになったばかりのようだ。\n奇妙な形の黒猫が手を差し出し、あなたを共舞に誘う。"
  },
  Stage_70432_Name = {
    Text = "猫の舞踏・第三幕"
  },
  Stage_70433_Desc = {
    Text = "黒猫は背中を丸め、四肢を動かし始めた。\nどうやらこの黒猫は自分の体をしっかりと制御できるようになったばかりのようだ。\n奇妙な形の黒猫が手を差し出し、あなたを共舞に誘う。"
  },
  Stage_70433_Name = {
    Text = "猫の舞踏・第二幕"
  },
  Stage_70434_Desc = {
    Text = "黒猫はあなたに最後の祝福を送り、この騒動が終わろうとしていることを感じる。\n猫には何の罪もない。彼はただお祭りの中であなたに少しの賑やかさをもたらしたいだけだ。"
  },
  Stage_70434_Name = {
    Text = "猫の祝福・第一幕"
  },
  Stage_70435_Desc = {
    Text = "この黒猫は不思議な力を持っているようだ。\n猫が指を鳴らすと、空に花火が咲いた。\n賑やかなパチパチ音の中、あなたは頭上から髪の毛が焦げる匂いを感じた。"
  },
  Stage_70435_Name = {
    Text = "猫の魔法・第二幕"
  },
  Stage_70436_Desc = {
    Text = "この黒猫は不思議な力を持っているようだ。\n猫が指を鳴らすと、空に花火が咲いた。\n賑やかなパチパチ音の中、あなたは頭上から髪の毛が焦げる匂いを感じた。"
  },
  Stage_70436_Name = {
    Text = "猫の魔法・第三幕"
  },
  Stage_70437_Desc = {
    Text = "この黒猫は不思議な力を持っているようだ。\n猫が指を鳴らすと、空に花火が咲いた。\n賑やかなパチパチ音の中、あなたは頭上から髪の毛が焦げる匂いを感じた。"
  },
  Stage_70437_Name = {
    Text = "猫の魔法・第一幕"
  },
  Stage_70924_Desc = {
    Text = "さあ、終末を見に行きましょう。\n絶望の中で朽ち果てるくらいなら、運命が訪れる前に、この手で終わりの偉業を成し遂げるわ。"
  },
  Stage_70924_Name = {
    Text = "選ばれなかった道"
  },
  Stage_70925_Desc = {
    Text = "数字は決して名前ではなく、単なる記号に過ぎない。\n凡庸な生命は、幻想的な独自性を手放せず、ゆえに数字で呼ばれることを拒む。\nだが、彼女がそれを気にしたことは一度もなかった。"
  },
  Stage_70926_Desc = {
    Text = "可能性は、良き結末と同義ではない。\nだが、蜃気楼であっても、前に進む者にとっては糧となるのだ。"
  },
  Stage_70926_Name = {
    Text = "可能性の答え"
  },
  Stage_70927_Desc = {
    Text = "グルル、グルル、グルル。臓腑が渇きに耐えかね、悲鳴を上げる。\n腹が空いているのではない。その空虚な飢えは、脳から生じているのだ。"
  },
  Stage_70927_Name = {
    Text = "人間の糧"
  },
  Stage_70928_Desc = {
    Text = "雨。降りやまぬ雨。"
  },
  Stage_70928_Name = {
    Text = "雨の中で"
  },
  Stage_70929_Desc = {
    Text = "一段、また一段と。神の触肢は深き夢の底へと伸びていく。"
  },
  Stage_70929_Name = {Text = "深き夢"},
  Stage_70930_Desc = {
    Text = "その瞳、夢に見るも恐ろしや。\n死の夢の王国にて。"
  },
  Stage_70930_Name = {
    Text = "うつろな人々"
  },
  Stage_70931_Desc = {
    Text = "人類は「唯一」を真理と定義する。\nだが、あなたの目に映るものこそが、世界の真の姿なのだ。"
  },
  Stage_70932_Desc = {
    Text = "ごらん、あの丸く艶やかな林檎の、なんと魅惑的なことか。\nひとくち齧れば、あらゆる悩みから解放されるだろう。"
  },
  Stage_70932_Name = {
    Text = "毒の林檎"
  },
  Stage_70933_Desc = {
    Text = "何もかも、記憶の中と同じだ。"
  },
  Stage_70933_Name = {
    Text = "親切で勇敢な"
  },
  Stage_70934_Desc = {
    Text = "過ぎ去ったものは、二度と戻らない。\n——別の世界にでも存在しない限り。"
  },
  Stage_70934_Name = {
    Text = "失ったもの"
  },
  Stage_70935_Desc = {
    Text = "裏拍、また裏拍。音符は、想定された旋律を外れてさまよう。"
  },
  Stage_70935_Name = {
    Text = "迷いの音符"
  },
  Stage_70936_Desc = {
    Text = "罠を逃れ、さらに巨大な檻の中へ。"
  },
  Stage_70936_Name = {Text = "脱出"},
  Stage_70937_Desc = {
    Text = "水槽の脳は機械義体の夢を見るか？"
  },
  Stage_70937_Name = {
    Text = "水槽の中の夢"
  },
  Stage_71748_Desc = {
    Text = "「しーっ……ねえ、君の目を通して、私には何が見えてるかわかる？」\nオレッタが守秘者に泣かされた結果、守秘者の部屋の第四の壁は、ロータンによって壊されそうになった。オレッタの泣き声があまりに心をかき乱すものだったからだ。"
  },
  Stage_71748_Name = {
    Text = "演劇の第四の壁・第七幕"
  },
  Stage_71749_Desc = {
    Text = "『絶え間なく、観客の脳を内容で攻撃してはならない。彼らに、考える余地を与えよ。できれば完全に静止した状態が望ましい』\nドールが授業にこの技術を使ってくれたならなぁ……と守秘者が呟き、皆が賛同した。"
  },
  Stage_71749_Name = {
    Text = "静寂の瞬間・第七幕"
  },
  Stage_71750_Desc = {
    Text = "『物語の登場人物は、結末までの成長や変化を弧のように描く必要がある』\nしかし、現実の生活では、その変化はしばしば弧ではなく、円を描く。"
  },
  Stage_71750_Name = {
    Text = "劇中人物論・第七幕"
  },
  Stage_71751_Desc = {
    Text = "あらかじめ設定されたシーン、お互いをよく知った数人の役者。\n残りは、インスピレーションとぶつかり合いに任せる。"
  },
  Stage_71751_Name = {
    Text = "仮面喜劇・第七幕"
  },
  Stage_71752_Desc = {
    Text = "これは、ラモンナさえ聞いたことのない言葉だったが、何人かの年長の覚醒体の助けを借りて、ようやく誰もが理解した。\n『時には、大泣きすることが悪い感情を処理する唯一の方法である』"
  },
  Stage_71752_Name = {
    Text = "カタルシス・第七幕"
  },
  Stage_71753_Desc = {
    Text = "『観客をストーリーに完全に没頭させてはならない。舞台で起きていることを分析し、批判させよ』この理論に対し、オレッタはこうコメントした。\n「オレッタは誰にも怒られたくない！オレッタはみんなと仲良くなりたいだけなの！」"
  },
  Stage_71753_Name = {
    Text = "異化効果・第七幕"
  },
  Stage_71754_Desc = {
    Text = "急転直下、突発的な展開、物語の急変——\n守秘者は、これが自分自身のことを描写しているように時々感じた。"
  },
  Stage_71754_Name = {
    Text = "プロットの転換・第七幕"
  },
  Stage_71755_Desc = {
    Text = "カーシアが見つけた理論書によれば『物語の時間は一日を超えてはならず、舞台も一箇所に限る……』とあり、守秘者はここで読むのをやめた。結局、一日という時間では、守秘者が「融蝕と災厄処理」の課題論文を終えるには足りないこともあるのだ。"
  },
  Stage_71755_Name = {
    Text = "三位一体・第七幕"
  },
  Stage_71756_Desc = {
    Text = "カーシアが見つけた理論書によれば『ピラミッドモデルは、一つの危機の解決に焦点を当てることが多い』とあった。しかし、現実世界ではすべての危機を解決はできない。それらは偽りの平和に覆い隠され、増殖し、新たな「ピラミッド」として爆発する。"
  },
  Stage_71756_Name = {
    Text = "劇作ピラミッド・第七幕"
  },
  Stage_71810_Desc = {
    Text = "彼女には多くの肩書があった。名士、実業家、仲介者、コレクター……\nただ、彼女自身という肩書だけはない——残念ながら、薔薇夫人はそれを気にしない。\n彼女にとって、未加工のものに価値などなく、複雑さと混沌こそが最高の美意識だ。"
  },
  Stage_71810_Name = {
    Text = "顔・第七幕"
  },
  Stage_71810_StageInitStateText = {Text = "繁殖"},
  Stage_71811_Desc = {
    Text = "彼女の『あしながおじさん』は他の誰とも違う。彼は霧でできていた。\n人間への信頼はすでに失い、霧や金や記号でできた人でも、彼女にとっては同じだった。\nもちろん、その判断の代償を、彼女はいずれ払うのだ——ただ、それはまだ先の話。"
  },
  Stage_71811_Name = {
    Text = "あしながおじさん・第七幕"
  },
  Stage_71811_StageInitStateText = {Text = "繁殖"},
  Stage_71812_Desc = {
    Text = "伝記作家は立ち去る前に、薔薇が咲き誇る美しい邸宅を振り返った。\nそれは主人の輝きの一万分の一にも及ばない。\nソレール夫人の伝説は今も、この瞬間も続いている。私たちがその証人となるだろう。"
  },
  Stage_71812_Name = {
    Text = "終曲・第七幕"
  },
  Stage_71812_StageInitStateText = {Text = "繁殖"},
  Stage_71813_Desc = {
    Text = "生け花、刺繍、茶道……彼女の生活は無意味な記号で構成されている。\n「おはよう、ソレールさん」「すごいですね、ソレールさん」……\n作り笑いの声は厚い水槽のように、彼女を永遠に閉じ込める。"
  },
  Stage_71813_Name = {
    Text = "釜中の魚・第七幕"
  },
  Stage_71813_StageInitStateText = {Text = "繁殖"},
  Stage_71814_Desc = {
    Text = "美貌とは見えない糸であり、それは人々の心をたやすく縛りつける。\n彼女はその糸を気まぐれに操った——まるで凡人に無関心な天才のように。\nだが、すぐこのゲームにも飽きた。彼らの醜い顔を通して、自らを垣間見たのだ。"
  },
  Stage_71814_Name = {
    Text = "傀儡遊戯・第七幕"
  },
  Stage_71814_StageInitStateText = {Text = "繁殖"},
  Stage_71815_Desc = {
    Text = "彼女は誕生日に白いローブを贈られた。\nそして彼女はその贈り物を着て、両親が他人に贈る贈り物になるのだと告げられた。"
  },
  Stage_71815_Name = {
    Text = "贈り物・第七幕"
  },
  Stage_71815_StageInitStateText = {Text = "繁殖"},
  Stage_71816_Desc = {
    Text = "彼女は磁石のように周囲の視線を惹きつけた。\n羨望、驚愕、嫉妬、貪欲……\nそのどれにも平穏はなく、それは彼女の今後の運命そのもののようだった。"
  },
  Stage_71816_Name = {
    Text = "視線・第七幕"
  },
  Stage_71816_StageInitStateText = {Text = "繁殖"},
  Stage_71817_Desc = {
    Text = "その夜、彼女は黒い霧の夢を見た。夢の中で、霧は生気を帯び、震えていた。\nそれは虎でも馬でもない、形容しがたい混血であり、両方の性質を持っていた。\n同時にそれは、一匹の黒猫であり、一輪の薔薇であり、そして一陣の嵐でもあった。"
  },
  Stage_71817_Name = {
    Text = "薔薇の棘・第七幕"
  },
  Stage_71817_StageInitStateText = {Text = "繁殖"},
  Stage_71818_Desc = {
    Text = "彼女は脚本の指示に従い、次々と劇を演じ、限りない混乱を巻き起こすだろう。\nそして、彼女こそが嵐の目で優雅に舞い上がる踊り手なのだ。\n彼女は常に最も献身的な女優だった。"
  },
  Stage_71818_Name = {
    Text = "未完の脚本・第七幕"
  },
  Stage_71818_StageInitStateText = {Text = "繁殖"},
  Stage_71852_Desc = {
    Text = "彼は高い青石の玉座に坐り、永遠の崇高と孤独を独り占めしていた。"
  },
  Stage_71852_Name = {Text = "玉座"},
  Stage_71853_Desc = {
    Text = "私は自ら手に取って、無限の力と栄光をかぶるつもりだ。"
  },
  Stage_71853_Name = {Text = "戴冠式"},
  Stage_71854_Desc = {
    Text = "神への祈りで奇跡をもたらすこと以外、小さな者には選択肢がない。"
  },
  Stage_71854_Name = {Text = "天災"},
  Stage_71855_Desc = {
    Text = "その王冠の重さは、早くもその子供たちの肩にのしかかっていた。"
  },
  Stage_71855_Name = {
    Text = "少年時代"
  },
  Stage_71923_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_71923_Name = {
    Text = "融災禁区・第2波・V級警報"
  },
  Stage_71924_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_71924_Name = {
    Text = "融災禁区・第3波・V級警報"
  },
