  },
  Stage_71928_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_71928_Name = {
    Text = "融災禁区・第5波・V級警報"
  },
  Stage_71929_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_71929_Name = {
