  },
  Stage_71930_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_71930_Name = {
    Text = "融災禁区・第1波・V級警報"
  },
  Stage_71931_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_71931_Name = {
    Text = "融災禁区・第3波・V級警報"
  },
  Stage_71932_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_71932_Name = {
    Text = "融災禁区・第2波・V級警報"
  },
  Stage_72063_Desc = {
    Text = "目を開けてください。\n死の夢の国土では"
  },
  Stage_72064_Desc = {
    Text = "人類は真実を唯一の定義としています。\n貴方が見るものこそが世界の真実の姿です。"
  },
  Stage_72064_Name = {Text = "真実"},
  Stage_72065_Desc = {
    Text = "君を見て、あの丸い光沢のあるリンゴはなんと魅力的なのだろう。\nそっと一口かじり、すべての悩みを取り去ろう。"
  },
  Stage_72065_Name = {
    Text = "毒のリンゴ"
  },
  Stage_72066_Desc = {
    Text = "すべては記憶の中と同じ。"
  },
  Stage_72066_Name = {
    Text = "親切で勇敢な"
  },
  Stage_72067_Desc = {
    Text = "失われたものは二度と帰ってくることはありません。\n別の世界にいる場合を除いては。"
  },
  Stage_72067_Name = {
    Text = "私たちはすでに失われた"
  },
  Stage_72068_Desc = {
    Text = "反拍、反拍、音符は期待されるメロディリズムから外れている。"
  },
  Stage_72068_Name = {
    Text = "迷奏の音符"
  },
  Stage_72069_Desc = {
    Text = "一つの罠から逃れて、さらに大きな檻に入る。"
  },
  Stage_72069_Name = {Text = "脱出"},
  Stage_72070_Desc = {
    Text = "親愛なる者よ、一緒に終末を見に行こう。\n絶望の中で衰え続けるよりも、運命が到来する前に手を尽くして終末の偉業を築こう。"
  },
  Stage_72070_Name = {
    Text = "選ばれていない道"
  },
  Stage_72071_Desc = {
    Text = "数字は決して名称ではなく、ただの記号である。\n平凡な人生は自分自身の虚構の独自性を手放したくないので、数字を自分自身の代名詞として受け入れることを拒否する。\n彼女はそれを気にしたことはなかった。"
  },
  Stage_72072_Desc = {
    Text = "ゴロゴロ、ゴロゴロ、ゴロゴロ。器官が迫る欲求の悲鳴を上げる。\n腹の空腹ではなく、その空虚は脳から来ている。"
  },
  Stage_72072_Name = {
    Text = "人間の食糧"
  },
  Stage_74229_Desc = {
    Text = "あなたは翻るスカートの裾と不意に出会った。あの回転するドレスは白鳥が羽ばたく翼のようでもあり、燃え上がる炎のようでもあった。"
  },
  Stage_74229_Name = {
    Text = "思いがけない炎"
  },
  Stage_74230_Desc = {
    Text = "ここは芸術の殿堂ではないのか？でなければ、なぜあれほど目を眩ませる優雅な舞があるのだろう。\nしかし、ここは本当に芸術の殿堂なのか？でなければ、なぜあれほど冷たく脂ぎった視線に満ちているのだろう。"
  },
  Stage_74230_Name = {
    Text = "燃え盛る氷"
  },
  Stage_74231_Desc = {
    Text = "夢の中の白鳥は高く舞い上がり、そして猟師の網の中で地面に叩きつけられた。"
  },
  Stage_74231_Name = {
    Text = "真夏の夜の夢"
  },
  Stage_74232_Desc = {
