  Stage_75758_StageInitStateText = {Text = "終末"},
  Stage_75759_Desc = {
    Text = "黒い粘液のようなそれは冷酷な幽霊。\nある者はその黒き沼にて存在を失い、ある者は沼から這い出て新たな命を得る。\nだが無情な沼はただ気前よく与えはしない。その再生の代償に彼らは何を失うのか？"
  },
