  Stage_75762_Name = {
    Text = "沼の悪鬼・第二幕"
  },
  Stage_75763_Desc = {
    Text = "「それ」は己の名さえも忘れ、彼女と初めて出会った日の記憶も既に薄れていた。\nただ「それ」を優しく握る彼女の手だけが、野蛮で孤独な魂をずっと温めてくれた。\nだからそれは彼女の手からその美しい首を受け取り、自ら永遠の仮面と枷をかぶった。"
  },
  Stage_75763_Name = {
    Text = "それと彼女・第六幕"
  },
  Stage_75764_Desc = {
