  Stage_7635_Desc = {
    Text = "それは捉えどころのない魔術師のように、時空の狭間を漂い続ける。\n憎しみも、恐怖も、慈悲も——何ひとつ持たずに。"
  },
  Stage_7635_Name = {
    Text = "次元の残像Ⅱ"
  },
  Stage_7636_Desc = {
    Text = "彼女はその身に聖骸を受け入れ、教義をもって信徒を導き、毒牙をもって信仰を広める。"
  },
  Stage_7636_Name = {
    Text = "信仰の手Ⅲ"
  },
  Stage_7637_Desc = {
    Text = "星々が生まれる遥か前から、それらはここに存在した。\n混沌とは「無」であり、同時に「全」でもある。"
  },
  Stage_7637_Name = {
    Text = "混濁の残像Ⅴ"
  },
  Stage_7638_Desc = {
    Text = "それらは海の秘密を無言で守る。その魂は宇宙のように深い。"
  },
  Stage_7638_Name = {
    Text = "海底の残像Ⅴ"
  },
  Stage_76399_Desc = {
    Text = "深淵より暗黒が奔流し、侵入者は心臓を握り締める恐怖の中で足掻く。  \n闇に飲み込まれるその瞬間まで——"
  },
  Stage_76399_Name = {
    Text = "融災禁区・第4波・V級警報"
  },
  Stage_7639_Desc = {
    Text = "それらは闇の中で捻じれ、溶け合い、そして慎重に像の中へと封じられる。\nそれは、長い時を経て仕組まれた再会だった。"
  },
  Stage_7639_Name = {
