  Stage_7647_Name = {
    Text = "幻夢の深奥Ⅰ"
  },
  Stage_7648_Desc = {
    Text = "猟犬は規則を破る者を追い続ける。規則とは破るとは？\nそれは考えない——思考はただ疾走の妨げとなるのみ。"
  },
  Stage_7648_Name = {
    Text = "異界の影Ⅲ"
  },
  Stage_7649_Desc = {
    Text = "ロンディニウムは輝かしい工業文明と、市街を覆う鉛灰色の濃霧で有名。\n霧はどこにでもあり、通行人にとっては偶然の、不便なものに過ぎない。"
  },
  Stage_7649_Name = {
    Text = "怪霧の都Ⅱ"
  },
  Stage_7650_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_7650_Name = {
    Text = "血肉の沼・隙間Ⅶ"
  },
  Stage_7651_Desc = {
    Text = "粗雑で未消化の物質の山。人々はそれを排泄物、または混沌と呼ぶ。\n世界は排泄物の中から生まれたのだ。"
  },
  Stage_7651_Name = {
    Text = "混沌地帯Ⅴ"
  },
  Stage_7652_Desc = {
    Text = "蠕動し、流れ……原生質の膿は、枷の隙間から逃れゆく。それは、彼女が「自由」に捧げた代償だった。"
  },
  Stage_7652_Name = {
    Text = "漆黒の鎖Ⅲ"
  },
  Stage_7653_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7653_Name = {
    Text = "超次元の旅・輪転の隙間Ⅰ"
  },
  Stage_7654_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7654_Name = {
    Text = "超次元の旅・輪転の隙間Ⅰ"
  },
  Stage_7655_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7655_Name = {
    Text = "超次元の旅・輪転の隙間Ⅰ"
  },
  Stage_7656_Desc = {
    Text = "それはベッドの縁に座りボタンの瞳は虚空を見つめる。小さな身体は涙を受け止めても慰める言葉を持たない。"
  },
  Stage_7656_Name = {
    Text = "人形の涙Ⅴ"
  },
  Stage_7657_Desc = {
    Text = "それは悲しみ、歪み、戸惑いから成る無意識の集合体だったが、幸せな子供、大人、ペットとして装われた。\n幸福を知らぬ彼らは、最も拙劣な役者となった。"
  },
  Stage_7657_Name = {
    Text = "蝋人形の秘密Ⅴ"
  },
  Stage_7658_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_7658_Name = {
    Text = "混沌の領域・隙間Ⅳ"
  },
  Stage_7659_Desc = {
    Text = "嵐はまだ続いている、すべてはまだ終わっていない。"
  },
  Stage_7659_Name = {
    Text = "現実の再起動"
  },
  Stage_7660_Desc = {
    Text = "華麗な舞台装置も、魅力的なヒロインもない。\n——これは三人の男が演じる退屈な劇だ。"
  },
  Stage_7660_Name = {
    Text = "案内役と魔術師と奴隷"
  },
  Stage_7661_Desc = {
    Text = "風と砂に向かって、戦士は迷わず太陽に向かって走る。"
  },
  Stage_7661_Name = {
    Text = "太陽遠征"
  },
  Stage_7662_Desc = {
    Text = "友人たちよ、争いをやめよう。\n祭りの炎が上がった。死の前の最後の静けさを楽しもう"
  },
  Stage_7662_Name = {
    Text = "赤い儀式"
  },
  Stage_7663_Desc = {
    Text = "厳密に言えば、これは悲劇ではない。\n戦士の辞書に「悲劇」はない。"
  },
  Stage_7663_Name = {
    Text = "悲劇の幕引き"
  },
  Stage_7664_Desc = {
    Text = "陸地へ向かい、一縷の望みにすがる。"
  },
  Stage_7664_Name = {
    Text = "悲劇の出航"
  },
  Stage_7665_Desc = {
    Text = "宇宙の深淵に潜む、歪んだ視界。\nそれは暗闇から、別の暗闇へとあなたを導く。"
  },
  Stage_7665_Name = {
    Text = "時空のくびれⅢ"
  },
  Stage_7666_Desc = {
