  },
  Stage_7674_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7674_Name = {
    Text = "幻夢の深奥Ⅲ"
  },
  Stage_7675_Desc = {
    Text = "北ヨークシャーの海辺の町、スカボロー。ここには高い崖と金色の湾があり、優雅で魅力的なリゾート地だ。"
  },
  Stage_7675_Name = {
    Text = "スカボローの夏"
  },
