  },
  Stage_7676_Name = {
    Text = "幻夢の深奥Ⅰ"
  },
  Stage_7677_Desc = {
    Text = "一匹の鼠よ、小さな鼠よ。\n走れ、走れ、彼女は肉切り包丁でその尾を切り落とす。"
  },
  Stage_7677_Name = {
