  Stage_7681_Name = {Text = "人形館"},
  Stage_7682_Desc = {
    Text = "OKベイビー。思いっきり泣いて、君の苦しみを最高の芸術作品として飾り付けましょう。"
  },
  Stage_7682_Name = {
    Text = "少女と涙"
  },
  Stage_7683_Desc = {
