  Stage_77102_Desc = {
    Text = "旧日の災厄が今ここに蘇り、現世の境界を越え、堕落の大海を燃え上がらせる。"
  },
  Stage_77102_Name = {
    Text = "融災禁区・第4波・Ⅲ級警報"
  },
  Stage_77103_Desc = {
    Text = "旧日の災厄が今ここに蘇り、現世の境界を越え、堕落の大海を燃え上がらせる。"
  },
  Stage_77103_Name = {
    Text = "融災禁区・第5波・Ⅲ級警報"
  },
  Stage_7710_Desc = {
    Text = "日記は記憶の破片だ。\n調査中に必ず日記が出てくる。"
  },
  Stage_7710_Name = {
    Text = "記憶の破片"
  },
  Stage_7711_Desc = {
    Text = "これは彼女のために作られた世界であり、偉大な愛と恐ろしい檻だ。"
  },
  Stage_7712_Desc = {
    Text = "貴族が権力を失い、富豪が破産した時、彼らは君のように一歩も動けなくなる。"
  },
  Stage_7712_Name = {
    Text = "カッコウの巣"
  },
  Stage_7713_Desc = {
    Text = "世界の戦いは武器ではなく、狂人の口にもある。"
  },
  Stage_7713_Name = {
    Text = "狂人の口"
  },
  Stage_7714_Desc = {
    Text = "霧に包まれた軌跡の上を、幾多の足跡がさまよう。\nその一歩一歩は、運命への問いかけ。"
  },
  Stage_7714_Name = {
    Text = "惑う運命"
  },
  Stage_7715_Desc = {
    Text = "静かに燃える炎が旅人に偽りの約束をする。"
  },
  Stage_7715_Name = {
    Text = "誘蛾の炎"
  },
  Stage_7716_Desc = {
    Text = "血と肉で築かれた現実を捧げよ。それは飽くなき深淵となる。"
  },
  Stage_7716_Name = {
    Text = "血肉の残像Ⅴ"
  },
  Stage_7717_Desc = {
    Text = "嵐はまだ続いている、すべてはまだ終わっていない。"
  },
  Stage_7717_Name = {
    Text = "現実の再起動"
  },
  Stage_7718_Desc = {
    Text = "陸地へ向かい、一縷の望みにすがる。"
  },
  Stage_7718_Name = {
    Text = "悲劇の出航"
  },
  Stage_7719_Desc = {
    Text = "望まれて生まれた生命ではなかった。\nそれはただの穢れた寄生虫に過ぎない。"
  },
  Stage_7719_Name = {Text = "寄生体"},
  Stage_7720_Desc = {
    Text = "果てしなき夜の闇の中で、その魅惑の光を追い求める。\nまるで火を追う蛾のように。すべてを顧みず、運命という名の炎へと飛び込む。"
  },
  Stage_7720_Name = {
    Text = "火を追う蛾"
  },
  Stage_7721_Desc = {
    Text = "夜闇が隠れた海流に侵され、星々が声を失う。\n転変と嵐の予兆を秘めた危機の月が、未知の未来を静かに映し出していた。"
  },
  Stage_7721_Name = {
    Text = "危機の月"
  },
  Stage_7722_Desc = {
    Text = "運命という狂風の中で震え、もがきながらも、決して散ることはない。"
  },
  Stage_7722_Name = {
    Text = "危うい均衡"
  },
  Stage_7723_Desc = {
    Text = "過ぎ去りし歳月に揺らめいた友情が、新たな希望を結んだ。"
  },
  Stage_7723_Name = {
    Text = "新旧の友誼"
  },
  Stage_7724_Desc = {
    Text = "彼の王国は宇宙の骸、彼の欲望は果てしなく広がる。"
  },
  Stage_7724_Name = {
    Text = "蠕虫の棲家Ⅲ"
  },
  Stage_7725_Desc = {
    Text = "血と肉で築かれた現実を捧げよ。それは飽くなき深淵となる。"
  },
  Stage_7725_Name = {
    Text = "血肉の残像Ⅱ"
  },
  Stage_7726_Desc = {
    Text = "それは悲しみ、歪み、戸惑いから成る無意識の集合体だったが、幸せな子供、大人、ペットとして装われた。\n幸福を知らぬ彼らは、最も拙劣な役者となった。"
  },
  Stage_7726_Name = {
    Text = "蝋人形の秘密Ⅰ"
  },
  Stage_7727_Desc = {
    Text = "それはベッドの縁に座りボタンの瞳は虚空を見つめる。小さな身体は涙を受け止めても慰める言葉を持たない。"
  },
  Stage_7727_Name = {
    Text = "人形の涙Ⅰ"
  },
  Stage_7728_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_7728_Name = {
    Text = "幻夢の深奥Ⅰ"
  },
  Stage_7729_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
