  },
  Stage_7740_Name = {
    Text = "幻夢の深奥Ⅳ"
  },
  Stage_7741_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_7741_Name = {
    Text = "幻夢の深奥Ⅴ"
  },
  Stage_7742_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7742_Name = {
    Text = "幻夢の深奥Ⅰ"
  },
  Stage_7743_Desc = {
    Text = "星々が生まれる遥か前から、それらはここに存在した。\n混沌とは「無」であり、同時に「全」でもある。"
  },
  Stage_7743_Name = {
    Text = "混濁の残像Ⅰ"
  },
  Stage_7744_Desc = {
    Text = "それらは闇の中で捻じれ、溶け合い、そして慎重に像の中へと封じられる。\nそれは、長い時を経て仕組まれた再会だった。"
  },
  Stage_7744_Name = {
    Text = "深海の遺産・隙間Ⅰ"
  },
  Stage_7745_Desc = {
    Text = "彼女はその身に聖骸を受け入れ、教義をもって信徒を導き、毒牙をもって信仰を広める。"
  },
  Stage_7745_Name = {
    Text = "信仰の手Ⅰ"
  },
  Stage_7746_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_7746_Name = {
    Text = "深海の遺産・隙間Ⅳ"
  },
  Stage_7747_Desc = {
    Text = "ライの町はロンディニウムの北東に位置し、連なる山々に隠れている。\n沈黙する村人、至る所にある視線……気をつけて、ここは何もかもが普通ではない。"
  },
  Stage_7747_Name = {
    Text = "錯乱の異郷Ⅰ"
  },
  Stage_7748_Desc = {
    Text = "ああ、地下水道！君こそ街の良心、街の避難所だ！"
  },
  Stage_7749_Desc = {
    Text = "そうです、その通りです。目は心の牢獄で、魂は肉体を縛る鎖なのです。"
  },
  Stage_7749_Name = {
    Text = "解剖の憂鬱"
  },
  Stage_7750_Desc = {
    Text = "虚無は我々の源であり、帰る場所でもある。"
  },
  Stage_7750_Name = {
    Text = "不朽の囁き"
  },
  Stage_7751_Desc = {
    Text = "OKベイビー。思いっきり泣いて、君の苦しみを最高の芸術作品として飾り付けましょう。"
  },
  Stage_7751_Name = {
    Text = "少女と涙"
  },
  Stage_7752_Desc = {
    Text = "猟犬は規則を破る者を追い続ける。規則とは破るとは？\nそれは考えない——思考はただ疾走の妨げとなるのみ。"
  },
  Stage_7752_Name = {
    Text = "異界の影Ⅱ"
  },
  Stage_7753_Desc = {
    Text = "現実、この残酷な現実。"
  },
  Stage_7753_Name = {
    Text = "ヴェールの下"
  },
  Stage_7754_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7754_Name = {
    Text = "血肉の沼・輪転の隙間Ⅱ"
  },
  Stage_7755_Desc = {
    Text = "その後、勇者は故郷に戻り、姫と結婚し、幸せで平穏な生活を送った。\n本当に？嘘に決まってる。"
  },
  Stage_7755_Name = {Text = "後記"},
  Stage_7756_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7756_Name = {
    Text = "血肉の沼・輪転の隙間Ⅰ"
  },
  Stage_7757_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7757_Name = {
    Text = "血肉の沼・輪転の隙間Ⅰ"
  },
  Stage_7758_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7758_Name = {
    Text = "血肉の沼・輪転の隙間Ⅰ"
  },
  Stage_7759_Desc = {
    Text = "雨が降り、血が流れる時、再会の時が来る。\nお久しぶりですね、守秘者さん。"
  },
  Stage_7759_Name = {
    Text = "偶然の出会い"
  },
  Stage_7760_Desc = {
    Text = "荒れ果てた鉄道橋の下、巨大で肥満した怪物が奇妙な低いうなり声を上げている。ライ精神病院に到達するには、ここを越えなければならない。"
  },
  Stage_7760_Name = {
    Text = "窮すれば通ず"
  },
  Stage_7761_Desc = {
    Text = "天才薬師へ至る道の第一歩。"
  },
  Stage_7761_Name = {
    Text = "薬剤収集Ⅳ"
  },
  Stage_7762_Desc = {
    Text = "天才薬師へ至る道の第一歩。"
  },
