  },
  Stage_7814_Desc = {
    Text = "それは海を切り裂こうとする者の巨大な刃。すべての海を征服せんとする者の野心。"
  },
  Stage_7814_Name = {
    Text = "狂徒と巨刃"
  },
  Stage_7815_Desc = {
    Text = "現実は災いの種をまいたが、運命が出会いを導いた。"
  },
  Stage_7815_Name = {
    Text = "運命の種子"
  },
  Stage_7816_Desc = {
    Text = "海を越える使徒。"
  },
  Stage_7817_Desc = {
    Text = "船の上で、船長以外に誰を信じるって言うんだ？"
  },
  Stage_7817_Name = {Text = "船員"},
  Stage_7818_Desc = {
    Text = "逃げられないとき、訓練された仲間が突破の鍵となる——\nラモンナが改めてそれを教えてくれた。"
  },
  Stage_7818_Name = {
    Text = "逃げ場なし"
  },
  Stage_7819_Desc = {
    Text = "海を越えた先には、敵だけでなく、希望の光もあるのかもしれない。"
  },
  Stage_7819_Name = {
    Text = "沈みゆく者"
  },
  Stage_7820_Desc = {
    Text = "夜の港。磯の香りの素朴な住民たち。なんと温かいおもてなし。\n……感動して涙が出ちゃうね。"
  },
  Stage_7820_Name = {
    Text = "四方八方敵だらけ"
  },
  Stage_7821_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7821_Name = {
    Text = "深海の遺産・輪転の隙間Ⅱ"
  },
  Stage_7822_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
