  },
  Stage_7834_Desc = {
    Text = "ここで猛威を振るっているのは普通の病気ではない。"
  },
  Stage_7834_Name = {Text = "奇病"},
  Stage_7835_Desc = {
    Text = "厚い霧に包まれたワークハウスで、切られ、失い、死に触れる。"
  },
  Stage_7835_Name = {
    Text = "誰が駒鳥を殺したか"
  },
  Stage_7836_Desc = {
    Text = "彼の王国は宇宙の骸、彼の欲望は果てしなく広がる。"
  },
  Stage_7836_Name = {
    Text = "蠕虫の棲家Ⅴ"
  },
  Stage_7837_Desc = {
    Text = "あなたとラモンナはロンディニウム東区のリリアンワークハウスに向かい、新米の守秘者として初の調査を行った。すべてが順調に進むはず……だよね？"
  },
  Stage_7837_Name = {
    Text = "人は見かけによらぬ"
  },
  Stage_7838_Desc = {
    Text = "甘く芳醇な、子供たちの愛。\n優雅で超然とした、大人たちの憧れ。"
  },
  Stage_7838_Name = {
    Text = "甘い芸術"
  },
  Stage_7839_Desc = {
    Text = "良心の重さは誓いと同等だ。"
  },
  Stage_7839_Name = {
    Text = "良心の呵責"
  },
  Stage_7840_Desc = {
    Text = "危険は内部から来る。"
  },
  Stage_7840_Name = {
    Text = "内在する危険"
  },
  Stage_7841_Desc = {
    Text = "私はずっと子供でいたい、毎日こうして君と星を見ていたいから。\n私は早く大人になりたい、そうすれば、みんなを守れるから。"
  },
  Stage_7841_Name = {
    Text = "私たちの秘密"
  },
  Stage_7842_Desc = {
    Text = "人形の糸を切れば、彼女はもう踊らない。"
  },
  Stage_7842_Name = {
    Text = "鳥が消えた夜"
  },
  Stage_7843_Desc = {
    Text = "知りたいことはすべて目の前にあったのだ。ただ気づかなかっただけで。"
  },
  Stage_7843_Name = {
    Text = "帽子の下に隠れて"
  },
  Stage_7844_Desc = {
    Text = "ラモンナが隊に戻り、ミサゴ調査員の旅が続く。"
  },
  Stage_7844_Name = {
    Text = "昨日の再現"
  },
  Stage_7845_Desc = {
    Text = "人類の脚力は四足の野生動物には及ばないが、頭脳は違う。しかし、“地獄の番犬”を捕まえた後、君たちを待つのは果たして？"
  },
  Stage_7845_Name = {
    Text = "袖の中の切り札"
  },
  Stage_7846_Desc = {
    Text = "あなたの旅路に幸多からんことを。"
  },
  Stage_7846_Name = {
    Text = "良い旅を"
  },
  Stage_7847_Desc = {
    Text = "地下鉄内で、謎の刺客に襲われた……"
  },
  Stage_7847_Name = {
    Text = "天涯孤独"
  },
  Stage_7848_Desc = {
    Text = "ダフォダイル夫人とのやり取りは常に取引によって成り立っている。ダフォダイル夫人が現れて取引を持ちかけたが、謎の襲撃者がその取引を認めるかどうかはわからない。"
  },
  Stage_7848_Name = {
    Text = "公平な取引"
  },
  Stage_7849_Desc = {
    Text = "地獄の番犬「ケルベロス」の噂を追い、ミサゴの調査員たちはロンディニウム郊外の町ライに向かい、失踪事件の真相を探る"
  },
  Stage_7849_Name = {
    Text = "熟慮の行動"
  },
  Stage_7850_Desc = {
    Text = "良い報告と悪い報告。消えた手がかりは戻らないが、新しい事件がどこかで進行しているようだ。信じて、調査員はもう手ぶらではない。"
  },
  Stage_7850_Name = {
    Text = "良い報告、悪い報告"
  },
  Stage_7851_Desc = {
    Text = "狂気の口調、強い血の臭い、これがライの歓迎の仕方。"
  },
  Stage_7851_Name = {
    Text = "ライへようこそ"
  },
  Stage_7852_Desc = {
    Text = "それはベッドの縁に座りボタンの瞳は虚空を見つめる。小さな身体は涙を受け止めても慰める言葉を持たない。"
  },
  Stage_7852_Name = {
    Text = "人形の涙Ⅲ"
  },
  Stage_7855_Desc = {
    Text = "彼は「あの方」ではない、「あの方」が彼であるはずがない。\nそうだ……そうであるはず。私の神だけが本当の「彼」のはずだ。"
  },
  Stage_7855_Name = {
    Text = "失われた光"
  },
  Stage_7856_Desc = {
    Text = "星々が生まれる遥か前から、それらはここに存在した。\n混沌とは「無」であり、同時に「全」でもある。"
  },
  Stage_7856_Name = {
    Text = "混濁の残像Ⅳ"
  },
  Stage_7857_Desc = {
    Text = "それらは海の秘密を無言で守る。その魂は宇宙のように深い。"
  },
  Stage_7857_Name = {
    Text = "海底の残像Ⅱ"
  },
  Stage_7858_Desc = {
    Text = "どうして永遠に沈まない夕日があるのか？"
  },
  Stage_7858_Name = {Text = "日没"},
  Stage_7859_Desc = {
    Text = "雨が降り、血が流れる時、再会の時が来る。\nお久しぶりですね、守秘者さん。"
  },
  Stage_7859_Name = {
    Text = "偶然の出会い"
  },
  Stage_7860_Desc = {
    Text = "それは捉えどころのない魔術師のように、時空の狭間を漂い続ける。\n憎しみも、恐怖も、慈悲も——何ひとつ持たずに。"
  },
  Stage_7860_Name = {
    Text = "次元の残像Ⅰ"
  },
  Stage_7861_Desc = {
    Text = "猟犬は規則を破る者を追い続ける。規則とは破るとは？\nそれは考えない——思考はただ疾走の妨げとなるのみ。"
  },
  Stage_7861_Name = {
    Text = "異界の影Ⅳ"
  },
  Stage_7862_Desc = {
    Text = "それらは海の秘密を無言で守る。その魂は宇宙のように深い。"
  },
  Stage_7862_Name = {
    Text = "海底の残像Ⅲ"
  },
  Stage_7863_Desc = {
    Text = "それらは海の秘密を無言で守る。その魂は宇宙のように深い。"
  },
  Stage_7863_Name = {
    Text = "海底の残像Ⅰ"
  },
  Stage_7864_Desc = {
    Text = "ロンディニウムは輝かしい工業文明と、市街を覆う鉛灰色の濃霧で有名。\n霧はどこにでもあり、通行人にとっては偶然の、不便なものに過ぎない。"
  },
  Stage_7864_Name = {
    Text = "怪霧の都Ⅰ"
  },
  Stage_7865_Desc = {
    Text = "何が彼女の目を曇らせたのか？\n愛、憐れみ、正義、そして過剰な感謝か？"
  },
  Stage_7865_Name = {Text = "解脱"},
  Stage_7866_Desc = {
    Text = "子供は母親に手を伸ばして、痛みを伴う抱擁を求めた。\n注射針が繊細な肌を突き破り、手術刀が白い肌を切り裂き、束縛帯が柔らかい関節を縛る。\nしかし、その無限の痛みでも彼女たちが抱き合うことを止めることはできない。\nそれが最も温かい抱擁だからだ。胚胎から母体を離れ、生まれてから互いに傷つけ、最終的に親密になり、一つになるために。"
  },
  Stage_7866_Name = {Text = "彼女"},
  Stage_7867_Desc = {
    Text = "夜の無音の中で眠り、\n疑問や争いは残らず、\n永遠の抱擁を得たかのように、\n静かな安らぎの中で横たわる。"
  },
  Stage_7867_Name = {Text = "部屋"},
  Stage_7868_Desc = {
    Text = "雪原に咲く百合。"
  },
  Stage_7868_Name = {
    Text = "神秘の川"
  },
  Stage_7869_Desc = {
    Text = "夜明けは必ず来る、太陽は変わらず昇る。"
  },
  Stage_7869_Name = {
    Text = "エピローグ"
  },
  Stage_7870_Desc = {
    Text = "彼女はその身に聖骸を受け入れ、教義をもって信徒を導き、毒牙をもって信仰を広める。"
  },
  Stage_7870_Name = {
    Text = "信仰の手Ⅱ"
  },
  Stage_7871_Desc = {
    Text = "鋭い棘が絶対的な円弧を破り、「ケルベロス」のものではない裂け目から生じた。"
  },
  Stage_7871_Name = {
    Text = "殻を破って"
  },
  Stage_7872_Desc = {
    Text = "現実は災いの種をまいたが、運命が出会いを導いた。"
  },
  Stage_7872_Name = {
    Text = "運命の種子"
  },
  Stage_78738_Name = {
    Text = "真貌・眠れる主試遊ステージ"
  },
  Stage_7873_Desc = {
    Text = "それらは闇の中で捻じれ、溶け合い、そして慎重に像の中へと封じられる。\nそれは、長い時を経て仕組まれた再会だった。"
  },
  Stage_7873_Name = {
    Text = "深海の遺産・隙間Ⅴ"
  },
  Stage_7874_Desc = {
    Text = "船の上で、船長以外に誰を信じるって言うんだ？"
  },
  Stage_7874_Name = {Text = "船員"},
  Stage_7875_Desc = {
    Text = "海を越える使徒。"
  },
  Stage_7876_Desc = {
    Text = "海を越えた先には、敵だけでなく、希望の光もあるのかもしれない。"
  },
  Stage_7876_Name = {
    Text = "沈みゆく者"
  },
  Stage_78773_Name = {
    Text = "真貌・深海の淑女試遊ステージ"
  },
  Stage_7877_Desc = {
    Text = "それは悲しみ、歪み、戸惑いから成る無意識の集合体だったが、幸せな子供、大人、ペットとして装われた。\n幸福を知らぬ彼らは、最も拙劣な役者となった。"
  },
  Stage_7877_Name = {
    Text = "蝋人形の秘密Ⅱ"
  },
  Stage_7878_Desc = {
    Text = "夜の港。磯の香りの素朴な住民たち。なんと温かいおもてなし。\n……感動して涙が出ちゃうね。"
  },
  Stage_7878_Name = {
    Text = "四方八方敵だらけ"
  },
  Stage_7879_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_7879_Name = {
    Text = "血肉の沼・隙間Ⅷ"
  },
  Stage_7880_Desc = {
    Text = "包囲を突破するのは容易ではない。だが幸いにも守秘者はすでに強く輝く一等星を見つけている。"
  },
  Stage_7880_Name = {
    Text = "星を追う"
  },
  Stage_7881_Desc = {
    Text = "第二の心臓がマーフィーの体内で脈打つ。「降生の儀式」をすぐに阻止しなければ。"
  },
  Stage_7881_Name = {
    Text = "もう一つの奇跡"
  },
  Stage_7882_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_7882_Name = {
    Text = "混沌の領域・隙間Ⅶ"
  },
  Stage_7883_Desc = {
    Text = "現実、この残酷な現実。"
  },
  Stage_7883_Name = {
    Text = "ヴェールの下"
  },
  Stage_7884_Desc = {
    Text = "静かに燃える炎が旅人に偽りの約束をする。"
  },
  Stage_7884_Name = {
    Text = "誘蛾の炎"
  },
  Stage_7885_Desc = {
    Text = "運命という狂風の中で震え、もがきながらも、決して散ることはない。"
  },
  Stage_7885_Name = {
    Text = "危うい均衡"
  },
  Stage_7886_Desc = {
    Text = "霧に包まれた軌跡の上を、幾多の足跡がさまよう。\nその一歩一歩は、運命への問いかけ。"
  },
  Stage_7886_Name = {
    Text = "惑う運命"
  },
  Stage_7887_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7887_Name = {
    Text = "幻夢の深奥Ⅳ"
  },
  Stage_7888_Desc = {
    Text = "粗雑で未消化の物質の山。人々はそれを排泄物、または混沌と呼ぶ。\n世界は排泄物の中から生まれたのだ。"
  },
  Stage_7888_Name = {
    Text = "混沌地帯Ⅰ"
  },
  Stage_7889_Desc = {
    Text = "立ち去った者が忘れられれば、すべては元に戻る。\nしかし、消え去った記憶も、きっと誰かが覚えている。"
  },
  Stage_7889_Name = {
    Text = "戻った日常"
  },
  Stage_7890_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_7890_Name = {
    Text = "幻夢の深奥Ⅴ"
  },
  Stage_7891_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7891_Name = {
    Text = "幻夢の深奥Ⅰ"
  },
  Stage_7892_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7892_Name = {
    Text = "幻夢の深奥Ⅱ"
  },
  Stage_7893_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7893_Name = {
    Text = "幻夢の深奥Ⅲ"
  },
  Stage_7894_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7894_Name = {
    Text = "幻夢の深奥Ⅳ"
  },
  Stage_7895_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7895_Name = {
    Text = "幻夢の深奥Ⅴ"
  },
  Stage_7896_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7896_Name = {
    Text = "幻夢の深奥Ⅵ"
  },
  Stage_7897_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7897_Name = {
    Text = "幻夢の深奥Ⅶ"
  },
  Stage_7898_Desc = {
    Text = "厚い霧に包まれたワークハウスで、切られ、失い、死に触れる。"
  },
  Stage_7898_Name = {
    Text = "誰が駒鳥を殺したか"
  },
  Stage_7899_Desc = {
    Text = "ここで猛威を振るっているのは普通の病気ではない。"
  },
  Stage_7899_Name = {Text = "奇病"},
  Stage_7900_Desc = {
    Text = "あなたとラモンナはロンディニウム東区のリリアンワークハウスに向かい、新米の守秘者として初の調査を行った。すべてが順調に進むはず……だよね？"
  },
  Stage_7900_Name = {
    Text = "人は見かけによらぬ"
  },
  Stage_7901_Desc = {
    Text = "良心の重さは誓いと同等だ。"
  },
  Stage_7901_Name = {
    Text = "良心の呵責"
  },
  Stage_7902_Desc = {
    Text = "甘く芳醇な、子供たちの愛。\n優雅で超然とした、大人たちの憧れ。"
  },
  Stage_7902_Name = {
    Text = "甘い芸術"
  },
  Stage_7903_Desc = {
    Text = "私はずっと子供でいたい、毎日こうして君と星を見ていたいから。\n私は早く大人になりたい、そうすれば、みんなを守れるから。"
  },
  Stage_7903_Name = {
    Text = "私たちの秘密"
  },
  Stage_7904_Desc = {
    Text = "危険は内部から来る。"
  },
  Stage_7904_Name = {
    Text = "内在する危険"
  },
  Stage_7905_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_7905_Name = {
    Text = "血肉の沼・輪転の隙間Ⅳ"
  },
  Stage_7906_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_7906_Name = {
    Text = "血肉の沼・輪転の隙間Ⅳ"
  },
  Stage_7907_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_7907_Name = {
    Text = "血肉の沼・輪転の隙間Ⅳ"
  },
  Stage_7908_Desc = {
    Text = "人形の糸を切れば、彼女はもう踊らない。"
  },
  Stage_7908_Name = {
    Text = "鳥が消えた夜"
  },
  Stage_7909_Desc = {
    Text = "ラモンナが隊に戻り、ミサゴ調査員の旅が続く。"
  },
  Stage_7909_Name = {
    Text = "昨日の再現"
  },
  Stage_7910_Desc = {
    Text = "知りたいことはすべて目の前にあったのだ。ただ気づかなかっただけで。"
  },
  Stage_7910_Name = {
    Text = "帽子の下に隠れて"
  },
  Stage_7911_Desc = {
    Text = "あなたの旅路に幸多からんことを。"
  },
  Stage_7911_Name = {
    Text = "良い旅を"
  },
  Stage_7912_Desc = {
    Text = "人類の脚力は四足の野生動物には及ばないが、頭脳は違う。しかし、“地獄の番犬”を捕まえた後、君たちを待つのは果たして？"
  },
  Stage_7912_Name = {
    Text = "袖の中の切り札"
  },
  Stage_7913_Desc = {
    Text = "ダフォダイル夫人とのやり取りは常に取引によって成り立っている。ダフォダイル夫人が現れて取引を持ちかけたが、謎の襲撃者がその取引を認めるかどうかはわからない。"
  },
  Stage_7913_Name = {
    Text = "公平な取引"
  },
  Stage_7914_Desc = {
    Text = "地下鉄内で、謎の刺客に襲われた……"
  },
  Stage_7914_Name = {
    Text = "天涯孤独"
  },
  Stage_7915_Desc = {
    Text = "地獄の番犬「ケルベロス」の噂を追い、ミサゴの調査員たちはロンディニウム郊外の町ライに向かい、失踪事件の真相を探る"
  },
  Stage_7915_Name = {
    Text = "熟慮の行動"
  },
  Stage_7916_Desc = {
    Text = "狂気の口調、強い血の臭い、これがライの歓迎の仕方。"
  },
  Stage_7916_Name = {
    Text = "ライへようこそ"
  },
  Stage_7917_Desc = {
    Text = "良い報告と悪い報告。消えた手がかりは戻らないが、新しい事件がどこかで進行しているようだ。信じて、調査員はもう手ぶらではない。"
  },
  Stage_7917_Name = {
    Text = "良い報告、悪い報告"
  },
  Stage_7918_Desc = {
    Text = "ここには、古代の都市の廃墟が眠っている。\nそれは、その主と同様に深い眠りに包まれている。"
  },
  Stage_7918_Name = {
    Text = "ポナペの廃墟Ⅳ"
  },
  Stage_7919_Desc = {
    Text = "アイズルワースはカダスの極点にあり、一年中溶けない氷雪で覆われている。\n厚くて硬い氷の下に、生命の脈動がかすかに潜んでいる。"
  },
  Stage_7919_Name = {
    Text = "失序山脈Ⅲ"
  },
  Stage_7920_Desc = {
    Text = "ここには大学が埋葬されている——傷だらけで、疲れ果てた。かつて、人類のために希望と勇気を捧げた。しかし、結果は今見ての通りだ。"
  },
  Stage_7920_Name = {
    Text = "幻夢の深奥Ⅶ"
  },
  Stage_7921_Desc = {
    Text = "それらは闇の中で捻じれ、溶け合い、そして慎重に像の中へと封じられる。\nそれは、長い時を経て仕組まれた再会だった。"
  },
  Stage_7921_Name = {
    Text = "血肉の沼・隙間Ⅰ"
  },
  Stage_7922_Desc = {
    Text = "血と肉で築かれた現実を捧げよ。それは飽くなき深淵となる。"
  },
  Stage_7922_Name = {
    Text = "血肉の残像Ⅳ"
  },
  Stage_7923_Desc = {
    Text = "ロジャーズ蝋人形館はサザーク・ストリートの最深部に位置し、テムズ川の支流に近い。\n目立たないが、多くの前衛芸術の愛好家がその名を慕って訪れる。"
  },
  Stage_7923_Name = {
    Text = "狂躁蝋人形館Ⅳ"
  },
  Stage_7924_Desc = {
