  },
  Stage_7931_Name = {
    Text = "蠕虫の棲家Ⅱ"
  },
  Stage_7932_Desc = {
    Text = "ここには、古代の都市の廃墟が眠っている。\nそれは、その主と同様に深い眠りに包まれている。"
  },
  Stage_7932_Name = {
    Text = "ポナペの廃墟Ⅱ"
  },
  Stage_7933_Desc = {
    Text = "現実、この残酷な現実。"
  },
  Stage_7933_Name = {
    Text = "ヴェールの下"
  },
  Stage_7934_Desc = {
    Text = "虚無は我々の源であり、帰る場所でもある。"
  },
  Stage_7934_Name = {
    Text = "不朽の囁き"
  },
  Stage_7935_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_7935_Name = {
    Text = "深海の遺産・隙間Ⅷ"
  },
  Stage_7936_Desc = {
    Text = "ライの町はロンディニウムの北東に位置し、連なる山々に隠れている。\n沈黙する村人、至る所にある視線……気をつけて、ここは何もかもが普通ではない。"
  },
  Stage_7936_Name = {
    Text = "錯乱の異郷Ⅱ"
  },
  Stage_7937_Desc = {
    Text = "「すべての鍵は唯一の番号を持ち、それぞれ唯一の調査員に対応する」\n「つまり、各鍵の崩壊は調査員の死を意味する。死さえも唯一無二だ」"
  },
