  Stage_7945_Desc = {
    Text = "彼女は夢と現実の境界、夜空を見上げる魂の深層の反映。"
  },
  Stage_7945_Name = {
    Text = "倒錯した星々"
  },
  Stage_7945_StageInitStateText = {
    Text = "海の悪夢"
  },
  Stage_7946_Desc = {
    Text = "宇宙の深淵に潜む、歪んだ視界。\nそれは暗闇から、別の暗闇へとあなたを導く。"
  },
  Stage_7946_Name = {
    Text = "時空のくびれⅠ"
  },
  Stage_7947_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_7947_Name = {
    Text = "混沌の領域・隙間Ⅲ"
  },
  Stage_7948_Desc = {
    Text = "ここには、古代の都市の廃墟が眠っている。\nそれは、その主と同様に深い眠りに包まれている。"
  },
  Stage_7948_Name = {
    Text = "ポナペの廃墟Ⅴ"
  },
  Stage_7949_Desc = {
    Text = "それはベッドの縁に座りボタンの瞳は虚空を見つめる。小さな身体は涙を受け止めても慰める言葉を持たない。"
  },
  Stage_7949_Name = {
    Text = "人形の涙Ⅱ"
  },
  Stage_7950_Desc = {
    Text = "健康のために、ニコチンを遠ざけましょう。"
  },
  Stage_7950_Name = {
    Text = "煙とアラセイトウ"
  },
  Stage_7951_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_7951_Name = {
    Text = "血肉の沼・隙間Ⅱ"
  },
  Stage_7952_Desc = {
    Text = "血と肉で築かれた現実を捧げよ。それは飽くなき深淵となる。"
  },
  Stage_7952_Name = {
    Text = "血肉の残像Ⅲ"
  },
  Stage_7953_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_7953_Name = {
    Text = "幻夢の深奥Ⅱ"
  },
  Stage_7954_Desc = {
    Text = "そして彼女は消え、闇に戻った。\n人々は高みを見上げ、彼女が飛び去る空を見つめた。"
  },
  Stage_7954_Name = {
    Text = "ヒマラヤスギ"
  },
  Stage_7955_Desc = {
    Text = "美しい祭壇に、涙、ため息、そして真心を供えよう。"
  },
  Stage_7955_Name = {
    Text = "ガラテア"
  },
  Stage_7956_Desc = {
