    Text = "無形の火は数多の生命を燃料とし、世の中のすべてを焼き尽くす。\n悲鳴も許さず、立ち止まることも許さず、わずかな痕跡も残さない。\nその怒りは限りなく、静かに咆哮し続け、決して止まらない。\nなぜなら、運命に逆らう者たちが常に存在し、灰になる運命の燃料を贖おうとするからだ。"
  },
  Stage_79599_Name = {
    Text = "燃える世界・その三"
  },
  Stage_7959_Desc = {
    Text = "振り返らないで！オルフェウスのようにならないための大切な忠告だ。"
  },
  Stage_7959_Name = {
    Text = "振り返るな"
  },
