  Stage_79608_Name = {
    Text = "侵夢の時・其二"
  },
  Stage_7960_Desc = {
    Text = "なんて幸せな眠りだ、私の天使が戻ってきた。"
  },
  Stage_7960_Name = {
    Text = "秘密の窓"
  },
  Stage_7961_Desc = {
    Text = "日記は記憶の破片だ。\n調査中に必ず日記が出てくる。"
  },
  Stage_7961_Name = {
    Text = "記憶の破片"
  },
  Stage_7962_Desc = {
    Text = "雪原に咲く百合。"
  },
  Stage_7962_Name = {Text = "28日間"},
  Stage_7963_Desc = {
    Text = "貴族が権力を失い、富豪が破産した時、彼らは君のように一歩も動けなくなる。"
  },
  Stage_7963_Name = {
    Text = "カッコウの巣"
  },
  Stage_7964_Desc = {
    Text = "これは彼女のために作られた世界であり、偉大な愛と恐ろしい檻だ。"
  },
  Stage_7965_Desc = {
    Text = "世界の戦いは武器ではなく、狂人の口にもある。"
  },
  Stage_7965_Name = {
    Text = "狂人の口"
  },
  Stage_7966_Desc = {
    Text = "静かに燃える炎が旅人に偽りの約束をする。"
  },
  Stage_7966_Name = {
    Text = "誘蛾の炎"
  },
  Stage_7967_Desc = {
    Text = "霧に包まれた軌跡の上を、幾多の足跡がさまよう。\nその一歩一歩は、運命への問いかけ。"
  },
  Stage_7967_Name = {
    Text = "惑う運命"
  },
  Stage_7968_Desc = {
    Text = "猟犬は規則を破る者を追い続ける。規則とは破るとは？\nそれは考えない——思考はただ疾走の妨げとなるのみ。"
  },
  Stage_7968_Name = {
    Text = "異界の影Ⅰ"
  },
  Stage_7969_Desc = {
    Text = "彼女はその身に聖骸を受け入れ、教義をもって信徒を導き、毒牙をもって信仰を広める。"
  },
  Stage_7969_Name = {
    Text = "信仰の手Ⅰ"
  },
  Stage_7970_Desc = {
    Text = "嵐はまだ続いている、すべてはまだ終わっていない。"
  },
  Stage_7970_Name = {
    Text = "現実の再起動"
  },
  Stage_7971_Desc = {
    Text = "望まれて生まれた生命ではなかった。\nそれはただの穢れた寄生虫に過ぎない。"
  },
  Stage_7971_Name = {Text = "寄生体"},
  Stage_7972_Desc = {
    Text = "陸地へ向かい、一縷の望みにすがる。"
  },
  Stage_7972_Name = {
    Text = "悲劇の出航"
  },
  Stage_7973_Desc = {
    Text = "夜闇が隠れた海流に侵され、星々が声を失う。\n転変と嵐の予兆を秘めた危機の月が、未知の未来を静かに映し出していた。"
  },
  Stage_7973_Name = {
    Text = "危機の月"
  },
  Stage_7974_Desc = {
    Text = "果てしなき夜の闇の中で、その魅惑の光を追い求める。\nまるで火を追う蛾のように。すべてを顧みず、運命という名の炎へと飛び込む。"
  },
  Stage_7974_Name = {
    Text = "火を追う蛾"
  },
  Stage_7975_Desc = {
    Text = "過ぎ去りし歳月に揺らめいた友情が、新たな希望を結んだ。"
  },
  Stage_7975_Name = {
    Text = "新旧の友誼"
  },
  Stage_7976_Desc = {
    Text = "運命という狂風の中で震え、もがきながらも、決して散ることはない。"
  },
  Stage_7976_Name = {
    Text = "危うい均衡"
  },
  Stage_7977_Desc = {
    Text = "風と砂に向かって、戦士は迷わず太陽に向かって走る。"
  },
  Stage_7977_Name = {
    Text = "太陽遠征"
  },
  Stage_7978_Desc = {
    Text = "蠕動し、流れ……原生質の膿は、枷の隙間から逃れゆく。それは、彼女が「自由」に捧げた代償だった。"
  },
  Stage_7978_Name = {
    Text = "漆黒の鎖Ⅴ"
  },
  Stage_7979_Desc = {
    Text = "粗雑で未消化の物質の山。人々はそれを排泄物、または混沌と呼ぶ。\n世界は排泄物の中から生まれたのだ。"
  },
  Stage_7979_Name = {
    Text = "混沌地帯Ⅲ"
  },
  Stage_7980_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_7980_Name = {
    Text = "超次元の旅・隙間Ⅷ"
  },
  Stage_7981_Desc = {
    Text = "それらは闇の中で捻じれ、溶け合い、そして慎重に像の中へと封じられる。\nそれは、長い時を経て仕組まれた再会だった。"
  },
  Stage_7981_Name = {
    Text = "血肉の沼・隙間Ⅴ"
  },
  Stage_7982_Desc = {
    Text = "そして彼女は消え、闇に戻った。\n人々は高みを見上げ、彼女が飛び去る空を見つめた。"
  },
  Stage_7982_Name = {
    Text = "ヒマラヤスギ"
  },
  Stage_7983_Desc = {
    Text = "一匹の鼠よ、小さな鼠よ。\n走れ、走れ、彼女は肉切り包丁でその尾を切り落とす。"
  },
  Stage_7983_Name = {
    Text = "ブラウン出撃"
  },
  Stage_7984_Desc = {
    Text = "夜の無音の中で眠り、\n疑問や争いは残らず、\n永遠の抱擁を得たかのように、\n静かな安らぎの中で横たわる。"
  },
  Stage_7984_Name = {Text = "部屋"},
  Stage_7985_Desc = {
    Text = "ロンディニウムは輝かしい工業文明と、市街を覆う鉛灰色の濃霧で有名。\n霧はどこにでもあり、通行人にとっては偶然の、不便なものに過ぎない。"
  },
  Stage_7985_Name = {
    Text = "怪霧の都Ⅲ"
  },
  Stage_7986_Desc = {
    Text = "美しい祭壇に、涙、ため息、そして真心を供えよう。"
  },
  Stage_7986_Name = {
    Text = "ガラテア"
  },
  Stage_7987_Desc = {
    Text = "バキバキ、裂けた。\nバキバキ、折れた。"
  },
  Stage_7987_Name = {Text = "人形館"},
  Stage_7988_Desc = {
    Text = "規則は破るためにあるんじゃない？"
  },
  Stage_7988_Name = {
    Text = "三つの規則"
  },
  Stage_7989_Desc = {
    Text = "北ヨークシャーの海辺の町、スカボロー。ここには高い崖と金色の湾があり、優雅で魅力的なリゾート地だ。"
  },
  Stage_7989_Name = {
    Text = "スカボローの夏"
  },
  Stage_7990_Desc = {
    Text = "あぁ、腕よ、厄介な腕よ！いつも私の髪を引っ張って離さない。"
  },
  Stage_7990_Name = {Text = "24"},
  Stage_7991_Desc = {
