    Text = "幻夢の深奥Ⅵ"
  },
  Stage_8009_Desc = {
    Text = "ここには、古代の都市の廃墟が眠っている。\nそれは、その主と同様に深い眠りに包まれている。"
  },
  Stage_8009_Name = {
    Text = "ポナペの廃墟Ⅰ"
  },
  Stage_8010_Desc = {
    Text = "私たちは時間と空間の異なる次元で何度も出会うでしょう"
  },
  Stage_8010_Name = {
    Text = "また会おう"
  },
  Stage_8011_Desc = {
    Text = "宇宙の深淵に潜む、歪んだ視界。\nそれは暗闇から、別の暗闇へとあなたを導く。"
  },
  Stage_8011_Name = {
    Text = "時空のくびれⅡ"
  },
  Stage_8012_Desc = {
    Text = "宇宙の深淵に潜む、歪んだ視界。\nそれは暗闇から、別の暗闇へとあなたを導く。"
  },
  Stage_8012_Name = {
    Text = "時空のくびれⅤ"
  },
  Stage_8013_Desc = {
    Text = "誰も神王の冠を外せない……誰も。"
  },
  Stage_8013_Name = {
    Text = "リモリアの「栄光」"
  },
  Stage_8014_Desc = {
    Text = "過ぎ去りし歳月に揺らめいた友情が、新たな希望を結んだ。"
  },
  Stage_8014_Name = {
    Text = "新旧の友誼"
  },
  Stage_8015_Desc = {
    Text = "夜闇が隠れた海流に侵され、星々が声を失う。\n転変と嵐の予兆を秘めた危機の月が、未知の未来を静かに映し出していた。"
  },
  Stage_8015_Name = {
    Text = "危機の月"
  },
  Stage_8016_Desc = {
    Text = "貪欲こそが彼の原罪。そのために彼は懺悔する。"
  },
  Stage_8016_Name = {Text = "消滅"},
  Stage_8017_Desc = {
    Text = "沈黙の守護者が、新たな声を上げた。"
  },
  Stage_8017_Name = {
    Text = "防衛の限界"
  },
  Stage_8018_Desc = {
    Text = "果てしなき夜の闇の中で、その魅惑の光を追い求める。\nまるで火を追う蛾のように。すべてを顧みず、運命という名の炎へと飛び込む。"
  },
  Stage_8018_Name = {
    Text = "火を追う蛾"
  },
  Stage_8019_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_8019_Name = {
    Text = "混沌の領域・輪転の隙間Ⅲ"
  },
  Stage_8020_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_8020_Name = {
    Text = "混沌の領域・輪転の隙間Ⅲ"
  },
  Stage_8021_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_8021_Name = {
    Text = "混沌の領域・輪転の隙間Ⅲ"
  },
  Stage_8022_Desc = {
    Text = "望まれて生まれた生命ではなかった。\nそれはただの穢れた寄生虫に過ぎない。"
  },
  Stage_8022_Name = {Text = "寄生体"},
  Stage_8023_Desc = {
    Text = "なんて幸せな眠りだ、私の天使が戻ってきた。"
  },
  Stage_8023_Name = {
    Text = "秘密の窓"
  },
  Stage_80242_Desc = {
    Text = "物語の終わりを迎えてもなお、世界は燃え続けている。\n私はもう、別れを告げる覚悟を決めた。だが、私たちはきっとまた巡り合える。"
  },
  Stage_80242_Name = {
    Text = "さよなら、燃える世界"
  },
  Stage_80243_Desc = {
    Text = "人間は社会的な生き物です。\n社会から影響を受け、同時に社会へ影響を与えながら生きています。\nでは、教えてください。\nあなたはこれまで人生と環境によって、どのような自分を作り上げてきたのでしょうか？"
  },
  Stage_80243_Name = {
    Text = "認知再構築実験"
  },
  Stage_80244_Desc = {
    Text = "あなたへの贈り物が何もなくて、ごめんなさい。\nこの小さな蛹は、私からあなたへの心からの祝福です。\n絶望に囚われたときは、どうか殻を破って、再び生まれ変わってください。"
  },
  Stage_80244_Name = {
    Text = "友情の蛹"
  },
  Stage_80245_Desc = {
    Text = "炎は光をもたらすと同時に、痛みと傷ももたらす。\n世界のすべてが燃え尽きるとき、私はこの命を一滴の涙へと変え、苦しみの海へと注ぎ込もう。"
  },
  Stage_80245_Name = {
    Text = "こんにちは、燃える世界"
  },
  Stage_80246_Desc = {
    Text = "勇者とは孤独な存在だ。\n人は彼の心に踏み込むことができず、竜もまた彼を真に理解することはできない。\n竜を討つのか、それとも自らが竜となるのか——それが問題だ。"
  },
  Stage_80246_Name = {
    Text = "孤独な勇者"
  },
  Stage_80247_Desc = {
    Text = "私は世界に夢を抱いていた。\n花がいつまでも咲き続け、笑顔がいつまでも続くことを願っていた。\nしかし、人生は私にたった一つの夢しか与えてくれなかった。"
  },
  Stage_80247_Name = {
    Text = "たくさんの夢"
  },
  Stage_80248_Desc = {
    Text = "その群れは、流動する琥珀のようだ。\n一つひとつの魂は、互いの光を映し合いながら、透明な檻の中に自らの姿を映し出している。"
  },
  Stage_80248_Name = {
    Text = "社会性動物"
  },
  Stage_80249_Desc = {
    Text = "私は私の友であり、同時に私の敵でもある。\nこの協力と殺し合いは、ただ一人が残るまで終わらない。"
  },
  Stage_80249_Name = {
    Text = "ドッペルゲンガー"
  },
  Stage_8024_Desc = {
    Text = "金属の体がどんなに重くても、魂は21グラムしかない。"
  },
  Stage_8024_Name = {
    Text = "魂の重さ"
  },
  Stage_80250_Desc = {
    Text = "小さな蝶が夢を超え、現実へと飛んでいく。\nたとえ愚かな選択だったとしても、蝶は人と異なる道を選んだのだ。"
  },
  Stage_80250_Name = {
    Text = "蝶が舞う"
  },
  Stage_80251_Desc = {
    Text = "さあ、見せてください。\n「あなた」と「私」を構成している成分と構造が、一体どのようなものなのかを。"
  },
  Stage_80251_Name = {Text = "目"},
  Stage_80252_Desc = {
    Text = "ああ、友よ。私たちは皆、夢をみるものだ。\nただ、夢を現実にする者もいれば、現実がまるで夢のように荒唐無稽な者もいる。"
  },
  Stage_80252_Name = {
    Text = "制御できぬ夢"
  },
  Stage_80253_Desc = {
    Text = "失われた記憶の中で踊る。\n私を愛した人も、私が愛した人も忘れ、ただ自分自身と永遠に、時の果てに至るまで踊り続ける。"
  },
  Stage_80253_Name = {
    Text = "失われた記憶"
  },
  Stage_80254_Desc = {
    Text = "逃げろ、逃げろ。狼狽え、苦しみ、無力な姿を晒しながら、滑稽な見世物を演じてみせろ。"
  },
  Stage_80254_Name = {Text = "追補"},
  Stage_80255_Desc = {
    Text = "あなたを見ている。ずっとあなたを見ている。\nいつだって、どんなときも、ただ、あなたを見ている。"
  },
  Stage_80255_Name = {
    Text = "他者の視線"
  },
  Stage_80256_Desc = {
    Text = "記憶は当てにならない。思い返すたびに薄れ、色褪せていくからだ。\nどうすれば、あなたの姿を永遠に留めておけるのだろう。\n記憶が頼りにならないのなら、いっそ命に刻み込めばいい。"
  },
  Stage_80256_Name = {
    Text = "よく似た姿"
  },
  Stage_80257_Desc = {
    Text = "最初の三発は、まだ序章にすぎなかった。\n最後の二発のうち、一発は彼の命を奪い、もう一発は彼の魂を奪った。"
  },
  Stage_80257_Name = {
    Text = "五発の銃声"
  },
  Stage_80258_Desc = {
    Text = "「好奇心」があなたに問いを投げかける。\nその答えが茨に覆われていて、知れば自らを焼き尽くすことになるとわかっていても、\nあなたは抗えない。あなたは結局、「好奇心」を拒めない猫なのだから。"
  },
  Stage_80258_Name = {
    Text = "好奇心は猫を殺す"
  },
  Stage_80259_Desc = {
    Text = "世界は巨大な療養所のようなものです。\n誰もが何かしらの狂気を抱えているか、あるいはそれを隠して生きています。\nそれでは、あなたもカウンセリングを受けてみませんか？"
  },
  Stage_80259_Name = {
    Text = "カウンセリングのご案内"
  },
  Stage_8025_Desc = {
    Text = "これは彼女のために作られた世界であり、偉大な愛と恐ろしい檻だ。"
  },
