    Text = "貴族が権力を失い、富豪が破産した時、彼らは君のように一歩も動けなくなる。"
  },
  Stage_8026_Name = {
    Text = "カッコウの巣"
  },
  Stage_80270_Desc = {
    Text = "あなたへの贈り物が何もなくて、ごめんなさい。\nこの小さな蛹は、私からあなたへの心からの祝福です。\n絶望に囚われたときは、どうか殻を破って、再び生まれ変わってください。"
  },
  Stage_80270_Name = {
    Text = "友情の蛹"
  },
  Stage_80271_Desc = {
    Text = "私は私の友であり、同時に私の敵でもある。\nこの協力と殺し合いは、ただ一人が残るまで終わらない。"
  },
  Stage_80271_Name = {
    Text = "ドッペルゲンガー"
  },
  Stage_8027_Desc = {
    Text = "世界の戦いは武器ではなく、狂人の口にもある。"
  },
  Stage_8027_Name = {
    Text = "狂人の口"
  },
  Stage_8028_Desc = {
    Text = "人形の糸を切れば、彼女はもう踊らない。"
  },
  Stage_8028_Name = {
    Text = "鳥が消えた夜"
  },
  Stage_8029_Desc = {
    Text = "振り返らないで！オルフェウスのようにならないための大切な忠告だ。"
  },
  Stage_8029_Name = {
    Text = "振り返るな"
  },
  Stage_8030_Desc = {
    Text = "「春」の意味を解釈できる者は誰か？\n静寂な虚空に潜伏する死と忘却が、朦朧とした春の蜃気楼へと溶け込んでいく。"
  },
  Stage_8030_Name = {
    Text = "ボッティチェリの春"
  },
  Stage_8031_Desc = {
    Text = "日記は記憶の破片だ。\n調査中に必ず日記が出てくる。"
  },
  Stage_8031_Name = {
    Text = "記憶の破片"
  },
  Stage_8032_Desc = {
    Text = "初対面、私の主人。"
  },
  Stage_8033_Desc = {
    Text = "それらは闇の中で捻じれ、溶け合い、そして慎重に像の中へと封じられる。\nそれは、長い時を経て仕組まれた再会だった。"
  },
  Stage_8033_Name = {
    Text = "血肉の沼・隙間Ⅵ"
  },
  Stage_8034_Desc = {
    Text = "星々が生まれる遥か前から、それらはここに存在した。\n混沌とは「無」であり、同時に「全」でもある。"
  },
  Stage_8034_Name = {
    Text = "混濁の残像Ⅲ"
  },
  Stage_8035_Desc = {
    Text = "ランダム4"
  },
  Stage_8035_Name = {
    Text = "月沼の鏡Ⅳ"
  },
  Stage_8036_Desc = {
    Text = "ランダム5"
  },
  Stage_8036_Name = {
    Text = "月沼の鏡Ⅴ"
  },
  Stage_8037_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_8037_Name = {
    Text = "混沌の領域・輪転の隙間Ⅰ"
  },
  Stage_8038_Desc = {
    Text = "ランダム1"
  },
  Stage_8038_Name = {
    Text = "月沼の鏡Ⅰ"
  },
  Stage_8039_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_8039_Name = {
    Text = "混沌の領域・輪転の隙間Ⅰ"
  },
  Stage_8040_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_8040_Name = {
    Text = "混沌の領域・輪転の隙間Ⅰ"
  },
  Stage_8041_Desc = {
    Text = "ラモンナが隊に戻り、ミサゴ調査員の旅が続く。"
  },
  Stage_8041_Name = {
    Text = "昨日の再現"
  },
  Stage_8042_Desc = {
    Text = "荒れ果てた鉄道橋の下、巨大で肥満した怪物が奇妙な低いうなり声を上げている。ライ精神病院に到達するには、ここを越えなければならない。"
  },
  Stage_8042_Name = {
    Text = "窮すれば通ず"
  },
  Stage_8043_Desc = {
    Text = "知りたいことはすべて目の前にあったのだ。ただ気づかなかっただけで。"
  },
  Stage_8043_Name = {
    Text = "帽子の下に隠れて"
  },
  Stage_8044_Desc = {
    Text = "人生は螺旋のようだ。一度逃れた悪夢が夜半に再び襲ってくることもある。"
  },
  Stage_8044_Name = {
    Text = "振り出しに戻る"
  },
  Stage_8045_Desc = {
    Text = "ラモンナとロータンのつぶやきの中、守秘者は牢獄の夢に陥った。"
  },
  Stage_8045_Name = {
    Text = "触らぬ神に祟りなし"
  },
  Stage_8046_Desc = {
    Text = "神は言った、彼らは生まれながらにして苦難を経験し、血を流す運命にある。\n太陽が昇るように、雨が降るように。\nすべては最善の計らいだ。"
  },
  Stage_8046_Name = {
    Text = "悲雨の地"
  },
  Stage_8047_Desc = {
    Text = "ロジャーズ蝋人形館はサザーク・ストリートの最深部に位置し、テムズ川の支流に近い。\n目立たないが、多くの前衛芸術の愛好家がその名を慕って訪れる。"
  },
  Stage_8047_Name = {
    Text = "狂躁蝋人形館Ⅱ"
  },
  Stage_8048_Desc = {
    Text = "それはここで唯一の生物で、見たすべてを支配する。\n——それは至高の王だ。"
  },
  Stage_8048_Name = {
    Text = "獣の王国"
  },
  Stage_8049_Desc = {
    Text = "彼の王国は宇宙の骸、彼の欲望は果てしなく広がる。"
  },
  Stage_8049_Name = {
    Text = "蠕虫の棲家Ⅰ"
  },
  Stage_8050_Desc = {
    Text = "その「手」は夜の幕をそっと押し開き、静かにこの世界へと忍び寄る。"
  },
  Stage_8050_Name = {
    Text = "幻夢の深奥Ⅴ"
  },
  Stage_8051_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_8051_Name = {
    Text = "幻夢の深奥Ⅱ"
  },
  Stage_8052_Desc = {
    Text = "崩れた偶像はその民を静かに見つめる。彼らの生存、繁栄、争い——そして偶像を完全に忘れる様を。それでもなお偶像は己の民を懐かしむ。"
  },
  Stage_8052_Name = {
    Text = "幻夢の深奥Ⅲ"
  },
