  },
  Stage_8104_Desc = {
    Text = "ロジャーズ蝋人形館はサザーク・ストリートの最深部に位置し、テムズ川の支流に近い。\n目立たないが、多くの前衛芸術の愛好家がその名を慕って訪れる。"
  },
  Stage_8104_Name = {
    Text = "狂躁蝋人形館Ⅲ"
  },
  Stage_8105_Desc = {
    Text = "どうして永遠に沈まない夕日があるのか？"
  },
  Stage_8105_Name = {Text = "日没"},
  Stage_8106_Desc = {
    Text = "鋭い棘が絶対的な円弧を破り、「ケルベロス」のものではない裂け目から生じた。"
  },
  Stage_8106_Name = {
    Text = "殻を破って"
  },
  Stage_8107_Desc = {
    Text = "何が彼女の目を曇らせたのか？\n愛、憐れみ、正義、そして過剰な感謝か？"
  },
  Stage_8107_Name = {Text = "解脱"},
  Stage_8108_Desc = {
    Text = "それは捉えどころのない魔術師のように、時空の狭間を漂い続ける。\n憎しみも、恐怖も、慈悲も——何ひとつ持たずに。"
  },
  Stage_8108_Name = {
    Text = "次元の残像Ⅳ"
  },
  Stage_8109_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_8109_Name = {
    Text = "深海の遺産・輪転の隙間Ⅰ"
  },
  Stage_8110_Desc = {
    Text = "地獄の番犬「ケルベロス」の噂を追い、ミサゴの調査員たちはロンディニウム郊外の町ライに向かい、失踪事件の真相を探る"
  },
  Stage_8110_Name = {
    Text = "熟慮の行動"
  },
  Stage_8111_Desc = {
    Text = "良い報告と悪い報告。消えた手がかりは戻らないが、新しい事件がどこかで進行しているようだ。信じて、調査員はもう手ぶらではない。"
  },
  Stage_8111_Name = {
    Text = "良い報告、悪い報告"
  },
  Stage_8112_Desc = {
    Text = "謎多き水仙夫人。"
  },
  Stage_8112_Name = {
    Text = "ごきげんよう、夫人"
  },
  Stage_8113_Desc = {
    Text = "狂気の口調、強い血の臭い、これがライの歓迎の仕方。"
  },
  Stage_8113_Name = {
    Text = "ライへようこそ"
  },
  Stage_8114_Desc = {
    Text = "人類の脚力は四足の野生動物には及ばないが、頭脳は違う。しかし、“地獄の番犬”を捕まえた後、君たちを待つのは果たして？"
  },
  Stage_8114_Name = {
    Text = "袖の中の切り札"
  },
  Stage_8115_Desc = {
