  },
  Stage_8141_Desc = {
    Text = "ここには、古代の都市の廃墟が眠っている。\nそれは、その主と同様に深い眠りに包まれている。"
  },
  Stage_8141_Name = {
    Text = "ポナペの廃墟Ⅲ"
  },
  Stage_8142_Desc = {
    Text = "何が彼女の目を曇らせたのか？\n愛、憐れみ、正義、そして過剰な感謝か？"
  },
  Stage_8142_Name = {Text = "解脱"},
  Stage_8143_Desc = {
    Text = "鋭い棘が絶対的な円弧を破り、「ケルベロス」のものではない裂け目から生じた。"
  },
  Stage_8143_Name = {
    Text = "殻を破って"
  },
  Stage_8144_Desc = {
    Text = "どうして永遠に沈まない夕日があるのか？"
  },
  Stage_8144_Name = {Text = "日没"},
  Stage_8145_Desc = {
    Text = "その「手」は夜の幕をそっと押し開き、静かにこの世界へと忍び寄る。"
  },
  Stage_8145_Name = {
    Text = "幻夢の深奥Ⅰ"
  },
  Stage_8146_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_8146_Name = {
    Text = "深海の遺産・隙間Ⅱ"
  },
  Stage_8147_Desc = {
    Text = "バキバキ、裂けた。\nバキバキ、折れた。"
  },
  Stage_8147_Name = {Text = "人形館"},
  Stage_8148_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_8148_Name = {
    Text = "混沌の領域・輪転の隙間Ⅳ"
  },
  Stage_8149_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_8149_Name = {
    Text = "混沌の領域・輪転の隙間Ⅳ"
  },
  Stage_8150_Desc = {
    Text = "「門」はすでに開かれ、幻夢はまもなく覚める。\n静かに——見つめてはならない。耳を傾けてはならない。"
  },
  Stage_8150_Name = {
    Text = "混沌の領域・輪転の隙間Ⅳ"
  },
  Stage_8151_Desc = {
    Text = "既視感と現実が守秘者を引き裂く。半分は記憶に、半分は目の前に。"
  },
  Stage_8151_Name = {Text = "短剣"},
  Stage_8152_Desc = {
    Text = "夜の港。磯の香りの素朴な住民たち。なんと温かいおもてなし。\n……感動して涙が出ちゃうね。"
  },
  Stage_8152_Name = {
    Text = "四方八方敵だらけ"
  },
  Stage_8153_Desc = {
    Text = "守秘者は孤独で記憶喪失。なんてありきたりな始まりだろう。\nいつもと違うのは、今回はなぜか海の上で目覚めたということだ。"
  },
  Stage_8153_Name = {
    Text = "台風の目"
  },
  Stage_8154_Desc = {
    Text = "海を越える使徒。"
  },
  Stage_8155_Desc = {
    Text = "船の上で、船長以外に誰を信じるって言うんだ？"
  },
  Stage_8155_Name = {Text = "船員"},
  Stage_8156_Desc = {
    Text = "逃げられないとき、訓練された仲間が突破の鍵となる——\nラモンナが改めてそれを教えてくれた。"
  },
  Stage_8156_Name = {
    Text = "逃げ場なし"
  },
  Stage_8157_Desc = {
    Text = "海を越えた先には、敵だけでなく、希望の光もあるのかもしれない。"
  },
  Stage_8157_Name = {
    Text = "沈みゆく者"
  },
  Stage_8158_Desc = {
    Text = "それは海を切り裂こうとする者の巨大な刃。すべての海を征服せんとする者の野心。"
  },
  Stage_8158_Name = {
    Text = "狂徒と巨刃"
  },
  Stage_8159_Desc = {
    Text = "それは彼女の消えない悪夢。一生を狂わせる歪んだ現実。"
  },
  Stage_8159_Name = {
    Text = "歪んだ現実"
  },
  Stage_8160_Desc = {
    Text = "それらは闇の中で捻じれ、溶け合い、そして慎重に像の中へと封じられる。\nそれは、長い時を経て仕組まれた再会だった。"
  },
  Stage_8160_Name = {
    Text = "超次元の旅・隙間Ⅴ"
  },
  Stage_8161_Desc = {
    Text = "ロンディニウムは輝かしい工業文明と、市街を覆う鉛灰色の濃霧で有名。\n霧はどこにでもあり、通行人にとっては偶然の、不便なものに過ぎない。"
  },
  Stage_8161_Name = {
    Text = "怪霧の都Ⅳ"
  },
  Stage_8162_Desc = {
    Text = "宇宙の深淵に潜む、歪んだ視界。\nそれは暗闇から、別の暗闇へとあなたを導く。"
  },
  Stage_8162_Name = {
    Text = "時空のくびれⅣ"
  },
  Stage_8163_Desc = {
    Text = "虚無は我々の源であり、帰る場所でもある。"
  },
  Stage_8163_Name = {
    Text = "不朽の囁き"
  },
  Stage_8164_Desc = {
    Text = "荒れ果てた鉄道橋の下、巨大で肥満した怪物が奇妙な低いうなり声を上げている。ライ精神病院に到達するには、ここを越えなければならない。"
  },
  Stage_8164_Name = {
    Text = "窮すれば通ず"
  },
  Stage_8165_Desc = {
    Text = "アイズルワースはカダスの極点にあり、一年中溶けない氷雪で覆われている。\n厚くて硬い氷の下に、生命の脈動がかすかに潜んでいる。"
  },
  Stage_8165_Name = {
    Text = "失序山脈Ⅰ"
  },
  Stage_8166_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_8166_Name = {
    Text = "混沌の領域・隙間Ⅷ"
  },
  Stage_8167_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_8167_Name = {
    Text = "幻夢の深奥Ⅳ"
  },
  Stage_8168_Desc = {
    Text = "「門」がまもなく開かれ、君はその隙間から一片の真理を垣間見る。\nそれは黒でも白でもない——真理とは、色鮮やかで、混沌としている。"
  },
  Stage_8168_Name = {
    Text = "血肉の沼・隙間Ⅲ"
  },
  Stage_8169_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_8169_Name = {
    Text = "幻夢の深奥Ⅵ"
  },
  Stage_8170_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_8170_Name = {
    Text = "幻夢の深奥Ⅶ"
  },
  Stage_8171_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_8171_Name = {
    Text = "幻夢の深奥Ⅰ"
  },
  Stage_8172_Desc = {
    Text = "「それは唯一、それは全、それは真実の扉を開く希望」無数の鍵が円環をなし空から降る。それは多量の希望と同時に多量の墓標をもたらす。"
  },
  Stage_8172_Name = {
    Text = "幻夢の深奥Ⅱ"
  },
  Stage_8173_Desc = {
    Text = "出自不明の像は、闇を彷徨い、震えている。\n彼らは古の拍子に足を揃え、遥かなる笛の音に導かれ舞い始める。"
  },
  Stage_8173_Name = {
    Text = "超次元の旅・隙間Ⅱ"
  },
  Stage_8174_Desc = {
    Text = "彼は「あの方」ではない、「あの方」が彼であるはずがない。\nそうだ……そうであるはず。私の神だけが本当の「彼」のはずだ。"
  },
  Stage_8174_Name = {
    Text = "失われた光"
  },
  Stage_81757_Desc = {
    Text = "輝く神国が、あなたのひび割れた瞳の中に徐々に現れる。\nそこで、あなたは約束を得て、すべてを手に入れる。"
  },
  Stage_81757_Name = {
    Text = "神国の囁き"
  },
  Stage_81758_Desc = {
    Text = "その象牙の彫刻を通して、彼の視線が人の世に降り立つ。\nそれ以来、あなたも私も彼の意志の中に沈んでいる。"
  },
  Stage_81758_Name = {
    Text = "聖像の視線"
  },
  Stage_81759_Desc = {
    Text = "無限の宇宙があなたの中に凝縮し、星々の群れが正位置の瞬間に向かう。\nこの虚空からの召喚に応じよう！彼の子たち。彼の傀儡。"
  },
  Stage_81759_Name = {
    Text = "虚空の召喚"
  },
  Stage_8175_Desc = {
    Text = "現実は災いの種をまいたが、運命が出会いを導いた。"
  },
  Stage_8175_Name = {
    Text = "運命の種子"
  },
  Stage_81760_Desc = {
    Text = "幻想と現実の隙間、祭礼が始まった。\n叫びなさい、叫びなさい、あなたの喜びと苦しみは次元を超えて、神国の到来の賛歌となる。"
  },
  Stage_81760_Name = {
    Text = "祭礼の応答"
  },
  Stage_81761_Desc = {
    Text = "すべての狂喜は過ぎ去った。\nあなたは分裂した身体を引きずり、触手を伸ばし、世界に覚醒後の最初の恐怖で冒涜的な叫びを発する。\n\n「神国は必ずや到来する。」"
  },
  Stage_81761_Name = {
    Text = "無妄の帰依"
  },
  Stage_81762_Desc = {
    Text = "ああ、この混沌の声を聞け、この果てしない幻楽を聞け。\n神は聖なる言葉を降ろし、君は彼の子として、そして傀儡として、忠実に実行することになる。"
  },
  Stage_81762_Name = {
    Text = "神王の聖諭"
  },
  Stage_81763_Desc = {
    Text = "加速する心拍は血肉の高まりの前触れ。\nパニックになる必要はない、それはあなたの血脈が覚醒する音だ。"
  },
  Stage_81763_Name = {
    Text = "躯壳の震動"
  },
  Stage_8176_Desc = {
    Text = "第二の心臓がマーフィーの体内で脈打つ。「降生の儀式」をすぐに阻止しなければ。"
  },
  Stage_8176_Name = {
    Text = "もう一つの奇跡"
  },
  Stage_8177_Desc = {
    Text = "包囲を突破するのは容易ではない。だが幸いにも守秘者はすでに強く輝く一等星を見つけている。"
  },
  Stage_8177_Name = {
    Text = "星を追う"
  },
  Stage_81781_Desc = {
    Text = "見えざる災厄が蘇り、物理世界の歴史と存在は、深淵へと沈みゆく。"
  },
  Stage_81781_Name = {
    Text = "融災禁域·第3波·狂気"
  },
  Stage_81782_Desc = {
    Text = "見えざる災厄が蘇り、物理世界の歴史と存在は、深淵へと沈みゆく。"
  },
  Stage_81782_Name = {
    Text = "融災禁域·第2波·超難度"
  },
