  },
  Stage_83250_Name = {
    Text = "融災禁域·第4波·普通"
  },
  Stage_88880_Desc = {
    Text = "私はあなたが灯した火を持っています。\nあなたが私を導いてくれた、私はあなたの目となり、光を再び見せます。\nあなたが歩んだ道を、私はあなたのために進みます、全ての錆びた柵がこの火の前で崩れ去ります。"
  },
  Stage_88880_Name = {
    Text = "火を伝える者・その三"
  },
  Stage_88881_Desc = {
    Text = "時を止めた都市は、ひとつの文明の姿をまるで標本のように留めている。"
  },
  Stage_88881_Name = {Text = "標本"},
  Stage_88882_Desc = {
    Text = "彼は生来愚かで鈍感で、単純な生活の中に閉じ込められて、盲目的かつ執拗だった。\nしかし誰が愚者は全く新しい道を歩けないと言ったのか？すべての束縛は未孵化の嵐に過ぎず、たとえ彼が何も知らなくとも、無畏に翼を広げて未知の空へと飛び立つだろう。"
  },
  Stage_88882_Name = {
    Text = "愚者・癲狂"
  },
  Stage_88883_Desc = {
    Text = "私は遥か昔の旧日を夢見ました。\nその時、あなたは書物に描かれた深い星々を、青いベルベットの布の上に広げたように指さし、晴れた夜に月の近くで一緒に飛びながら、空にはどんな景色が広がっているのかを見ようと話していました。"
  },
  Stage_88883_Name = {
    Text = "昨日の夢・第六"
  },
  Stage_88884_Desc = {
    Text = "彼は常に二つの影を持っていたが、今彼はもう一つを失った。\n彼は静かな夜空の下を孤独に歩き、自らの子供時代に編纂した歌を歌う。\n鳥よ、鳥よ、君はどこに…………\n影よ、影よ、早く帰れ…………"
  },
  Stage_88884_Name = {
    Text = "孤独の旅・その五"
  },
  Stage_88885_Desc = {
    Text = "私はあなたが灯した火を持っています。\nあなたが私を導いてくれた、私はあなたの目となり、光を再び見せます。\nあなたが歩んだ道を、私はあなたのために進みます、全ての錆びた柵がこの火の前で崩れ去ります。"
  },
  Stage_88885_Name = {
    Text = "火を伝える者・その四"
  },
  Stage_88886_Desc = {
    Text = "私はあなたが灯した火を持っています。\nあなたが私を導いてくれた、私はあなたの目となり、光を再び見せます。\nあなたが歩んだ道を、私はあなたのために進みます、全ての錆びた柵がこの火の前で崩れ去ります。"
  },
  Stage_88886_Name = {
    Text = "火を伝える者・その二"
  },
  Stage_88887_Desc = {
    Text = "籠の中に生まれたら、束縛されるべき運命なのか？\n深い土の中に埋まっても、どうして地面を突き破って生まれ変わるのか。"
  },
  Stage_88887_Name = {
    Text = "囚われの檻・第五部"
  },
  Stage_88888_Desc = {
    Text = "籠の中に生まれたら、束縛されるべき運命なのか？\n深い土の中に埋まっても、どうして地面を突き破って生まれ変わるのか。"
  },
  Stage_88888_Name = {
    Text = "囚われの檻・第六部"
  },
  Stage_88889_Desc = {
    Text = "私は遥か昔の旧日を夢見ました。\nその時、あなたは書物に描かれた深い星々を、青いベルベットの布の上に広げたように指さし、晴れた夜に月の近くで一緒に飛びながら、空にはどんな景色が広がっているのかを見ようと話していました。"
  },
