  },
  Stage_88896_Desc = {
    Text = "彼は常に二つの影を持っていたが、今彼はもう一つを失った。\n彼は静かな夜空の下を孤独に歩き、自らの子供時代に編纂した歌を歌う。\n鳥よ、鳥よ、君はどこに…………\n影よ、影よ、早く帰れ…………"
  },
  Stage_88896_Name = {
    Text = "孤独の旅・その二"
  },
  Stage_88897_Desc = {
    Text = "その砂は海のようで、風が止まると波が静まり、風が激しく吹くと生き物がすべて消え去ります。\n彼は無限の砂海の中で、海燕のように屈せずに飛び続けます。"
  },
  Stage_88897_Name = {
    Text = "無限の砂・癲狂"
  },
  Stage_88898_Desc = {
    Text = "私は遥か昔の旧日を夢見ました。\nその時、あなたは書物に描かれた深い星々を、青いベルベットの布の上に広げたように指さし、晴れた夜に月の近くで一緒に飛びながら、空にはどんな景色が広がっているのかを見ようと話していました。"
  },
  Stage_88898_Name = {
    Text = "昨日の夢・癲狂"
  },
  Stage_88899_Desc = {
    Text = "彼は生来愚かで鈍感で、単純な生活の中に閉じ込められて、盲目的かつ執拗だった。\nしかし誰が愚者は全く新しい道を歩けないと言ったのか？すべての束縛は未孵化の嵐に過ぎず、たとえ彼が何も知らなくとも、無畏に翼を広げて未知の空へと飛び立つだろう。"
  },
  Stage_88899_Name = {
    Text = "愚者・之一"
  },
  Stage_88900_Desc = {
    Text = "私はあなたが灯した火を持っています。\nあなたが私を導いてくれた、私はあなたの目となり、光を再び見せます。\nあなたが歩んだ道を、私はあなたのために進みます、全ての錆びた柵がこの火の前で崩れ去ります。"
  },
  Stage_88900_Name = {
    Text = "火を伝える者・その五"
  },
  Stage_88901_Desc = {
    Text = "彼は手慣れた様子で鎖を解き、檻の外へひたすら走り続けた。すべての曲がり角も、すべての見張りの位置も覚えている。この日のために、彼はあまりにも長い時間を準備に費やしてきたのだ。\n何しろ、これが初めての脱走ではないのだから。"
  },
  Stage_88901_Name = {Text = "奔走"},
  Stage_88902_Desc = {
    Text = "彼が目を開けた時、その目はもう閉じることができなくなった。\n彼が空を見た時、その空は心の中に永遠に留まった。\nもしその自由が死と引き換えに得られるなら、彼は躊躇うことなく自らの命を捧げるだろう。"
  },
  Stage_88902_Name = {
    Text = "自由と死・第四"
  },
  Stage_88903_Desc = {
    Text = "鳥を閉じ込めることはできても、自由な心を閉じ込めることはできない。"
  },
  Stage_88903_Name = {Text = "鳥の心"},
  Stage_88904_Desc = {
    Text = "彼が目を開けた時、その目はもう閉じることができなくなった。\n彼が空を見た時、その空は心の中に永遠に留まった。\nもしその自由が死と引き換えに得られるなら、彼は躊躇うことなく自らの命を捧げるだろう。"
  },
  Stage_88904_Name = {
    Text = "自由と死・癲狂"
  },
