  Stage_88932_Name = {
    Text = "愚者・之五"
  },
  Stage_89731_Desc = {
    Text = "ゆっくりと落ちるその涙は、透き通った氷の結晶のように輝いていた。"
  },
  Stage_89731_Name = {
    Text = "一粒の涙"
  },
  Stage_89732_Desc = {
    Text = "逃走、潜伏、捕捉、抵抗——だが、狩人はすでにその黒い銃口を突きつけていた。"
  },
  Stage_89732_Name = {Text = "狩り"},
  Stage_90490_Desc = {
    Text = "混沌より生まれた覚醒体があなたと共に立ち、あなたのシルバーキーは高ぶるような共鳴を発している。\n彼らと共に戦い、シルバーキーの能力を解き放つ方法を習得しよう。"
  },
  Stage_90490_Name = {
    Text = "混沌の念"
  },
  Stage_90662_Desc = {
    Text = "墓地の鐘が鳴り響く時、広がる黒い霧は夢の中で消え去る。\n重い棺を押し開けよ、それは荘厳な王城があなたの目の前に降臨している。"
  },
  Stage_90662_Name = {
    Text = "夢境の下"
  },
  Stage_90663_Desc = {
    Text = "聞け、この海の嘆き。\n信者たちは誠心誠意に願い求める。主が彼らの祈りに応え、主が彼らの血を恵んでくださるように。"
  },
  Stage_90664_Desc = {
    Text = "「この地に眠る骨、夜空を彷徨う魂に――\n食屍鬼の王、葬骸城の主の名において、あなたたちを再び愛しい土地へ招待する。\n敵が贈った饗宴を共に楽しむために、あなたたちを招待する！」"
  },
  Stage_90664_Name = {
    Text = "万霊の舞"
  },
  Stage_90665_Desc = {
    Text = "長く交わした誓いは、誠心誠意を尽くす前からのものです。"
  },
  Stage_90665_Name = {Text = "誓い"},
  Stage_90666_Desc = {
    Text = "罪孽？陰謀？死？\n画家はこれらを気にかける余裕もなく、彼の目には死体が作り出す壮大な光景しかない。"
  },
  Stage_90667_Desc = {
    Text = "長く交わした誓いは、誠心誠意を尽くす前からのものです。"
  },
  Stage_90667_Name = {Text = "誓い"},
  Stage_90670_Desc = {
    Text = "葬骸の城の君主のすべての特質の中で、美食に対する嗅覚が極めて重要である。"
  },
  Stage_90670_Name = {
    Text = "王と屍体料理の芸術"
  },
  Stage_90671_Desc = {
    Text = "血縁者の記憶。城邦の王室の物語。重く壮大な歴史。\n民間人の記憶。平凡な家族の物語。無用な脚注。\n葬骸城の王にとって、それらは何も、そして決して何も違いはないはず。"
  },
  Stage_90671_Name = {
    Text = "卑小なる脚注"
  },
  Stage_90672_Desc = {
    Text = "「弦楽は天に昇り、全ての煩わしい儀式は霧の中に消え去った。\n私の愛する臣民たちよ、歓呼せよ。包帯の下の偽善を引き裂き、原始的な飢渇をさらけ出せ。\n今夜、詩人の喉が私たちのために詠唱する。\n今夜、母の腕が私たちを抱きしめる。」"
  },
  Stage_90672_Name = {
    Text = "月光、骸骨と舞"
  },
  Stage_90674_Desc = {
    Text = "彼は埋葬城の王である。彼はこの饗宴の主人だ。\n彼はすべての客に両腕を広げ、舞踏室から離れるように誘った。\n墓地に散らばる死骸の上で、彼は深淵と共に踊る。"
  },
  Stage_90674_Name = {
    Text = "葬骸の主"
  },
  Stage_90676_Desc = {
    Text = "墓地の鐘が鳴り響く時、広がる黒い霧は夢の中で消え去る。\n重い棺を押し開けよ、それは荘厳な王城があなたの目の前に降臨している。"
  },
  Stage_90676_Name = {
    Text = "夢境の下"
  },
  Stage_90679_Desc = {
    Text = "葬骸の城の君主のすべての特質の中で、美食に対する嗅覚が極めて重要である。"
  },
  Stage_90679_Name = {
    Text = "王と屍体料理の芸術"
  },
  Stage_90680_Desc = {
    Text = "夢の中の声、消えかけた文明、旧友の痕跡………… \n知りたい全てが、遠い海の上であなたを待っている。"
  },
  Stage_90680_Name = {
    Text = "遠き海の上"
  },
  Stage_90681_Desc = {
    Text = "聞け、この海の嘆き。\n信者たちは誠心誠意に願い求める。主が彼らの祈りに応え、主が彼らの血を恵んでくださるように。"
  },
  Stage_90684_Desc = {
    Text = "目の前にいるこの老いた食屍鬼は誰なのか？彼はなぜボロボロの服を着ているのか？彼はなぜ涙を流しているのか？\n彼はなぜ痛哭し、最も優しく、最もかすれた声で「イレーナ」と呼んでいるのか？\n彼女は何も思い出せない。\n月明かりが彼女の遺体に降り注ぎ、婚礼の日のように美しく、風に揺れる薄布のように見える。"
  },
  Stage_90684_Name = {
    Text = "ウェディングドレスと葬儀"
  },
  Stage_90685_Desc = {
    Text = "目の前にいるこの老いた食屍鬼は誰なのか？彼はなぜボロボロの服を着ているのか？彼はなぜ涙を流しているのか？\n彼はなぜ痛哭し、最も優しく、最もかすれた声で「イレーナ」と呼んでいるのか？\n彼女は何も思い出せない。\n月明かりが彼女の遺体に降り注ぎ、婚礼の日のように美しく、風に揺れる薄布のように見える。"
  },
  Stage_90685_Name = {
    Text = "ウェディングドレスと葬儀"
  },
  Stage_90686_Desc = {
    Text = "血縁者の記憶。城邦の王室の物語。重く壮大な歴史。\n民間人の記憶。平凡な家族の物語。無用な脚注。\n葬骸城の王にとって、それらは何も、そして決して何も違いはないはず。"
  },
  Stage_90686_Name = {
    Text = "卑小なる脚注"
  },
  Stage_90687_Desc = {
    Text = "彼は埋葬城の王である。彼はこの饗宴の主人だ。\n彼はすべての客に両腕を広げ、舞踏室から離れるように誘った。\n墓地に散らばる死骸の上で、彼は深淵と共に踊る。"
  },
  Stage_90687_Name = {
    Text = "葬骸の主"
  },
  Stage_90689_Desc = {
    Text = "罪孽？陰謀？死？\n画家はこれらを気にかける余裕もなく、彼の目には死体が作り出す壮大な光景しかない。"
  },
  Stage_90690_Desc = {
    Text = "「この地に眠る骨、夜空を彷徨う魂に――\n食屍鬼の王、葬骸城の主の名において、あなたたちを再び愛しい土地へ招待する。\n敵が贈った饗宴を共に楽しむために、あなたたちを招待する！」"
  },
  Stage_90690_Name = {
    Text = "万霊の舞"
  },
  Stage_90691_Desc = {
    Text = "「弦楽は天に昇り、全ての煩わしい儀式は霧の中に消え去った。\n私の愛する臣民たちよ、歓呼せよ。包帯の下の偽善を引き裂き、原始的な飢渇をさらけ出せ。\n今夜、詩人の喉が私たちのために詠唱する。\n今夜、母の腕が私たちを抱きしめる。」"
  },
  Stage_90691_Name = {
    Text = "月光、骸骨と舞"
  },
  Stage_90985_Desc = {
    Text = "すべての阻止者は恐怖にひれ伏し、すべての輝きはローマに降り注ぐ。\nあの白い花冠と月桂樹の葉は、最も勇敢な戦士の頭に戴かれる。"
  },
  Stage_90985_Name = {
    Text = "勇士の冠・その5"
  },
  Stage_90986_Desc = {
    Text = "歓声と花々、酒と饗宴、黄金と宝物。\n楽しんで、大声で笑ってください。これが勇者にふさわしい栄光です！"
  },
  Stage_90986_Name = {
    Text = "栄光の凱旋・その5"
  },
  Stage_90987_Desc = {
    Text = "すべての阻止者は恐怖にひれ伏し、すべての輝きはローマに降り注ぐ。\nあの白い花冠と月桂樹の葉は、最も勇敢な戦士の頭に戴かれる。"
  },
  Stage_90987_Name = {
    Text = "勇士の冠・その2"
  },
  Stage_90988_Desc = {
    Text = "獲物がどこに隠れていようとも、プロの狩人はその甘美な香りを嗅ぎ取るだろう。"
  },
  Stage_90988_Name = {
    Text = "凶猛な獲物・癲狂"
  },
  Stage_90989_Desc = {
    Text = "征服の号角が鳴り響き、戦士たちは旅立ちました。\n私たちは前進し、止められず、必ずや勝利する。"
  },
  Stage_90989_Name = {
    Text = "遠征号角·第二"
  },
  Stage_90990_Desc = {
    Text = "征服の号角が鳴り響き、戦士たちは旅立ちました。\n私たちは前進し、止められず、必ずや勝利する。"
  },
  Stage_90990_Name = {
    Text = "遠征号角·第四"
  },
  Stage_90991_Desc = {
    Text = "過去に私たちがいくつかの確執を抱えていたことは認めるが、それは私たちが共にこの嫌な、憎い、卑劣な現代技術に矛先を向けることを妨げるものではない。"
  },
  Stage_90991_Name = {
