  },
  Stage_91019_Desc = {
    Text = "歓声と花々、酒と饗宴、黄金と宝物。\n楽しんで、大声で笑ってください。これが勇者にふさわしい栄光です！"
  },
  Stage_91019_Name = {
    Text = "栄光の凱旋・その6"
  },
  Stage_91088_Desc = {
    Text = "彼らは主人と奴隷、殺人者と死者、同じ廃墟の遺物です。\n血脈の渇望に従い、同じ扉の前で偶然出会います。"
  },
  Stage_91088_Name = {
    Text = "奴隷と奴隷主"
  },
  Stage_91091_Desc = {
    Text = "誰が古の栄光は戻ってこないと言った？\n見ていろ、くそったれな現代技術、ローマの力はすべてを超越する！"
  },
  Stage_91091_Name = {
    Text = "ローマの力"
  },
  Stage_94464_Desc = {
    Text = "深海からの覚醒体が、海底に潜む力を携えてあなたの前に現れる。\n彼らと共に戦い、触手の力を使う方法を習得しよう。"
  },
  Stage_94464_Name = {
    Text = "深海の触"
  },
  Stage_94465_Desc = {
    Text = "血と肉は生命の始まりであり、また終わりでもある。死とは生であり、純粋な血肉で構成された血肉の覚醒体たちはそれを最も理解している。\n彼らと共に戦い、血肉の力を操る方法を習得しよう。"
  },
  Stage_94465_Name = {
    Text = "血肉の殖"
  },
  Stage_94466_Desc = {
    Text = "超次元を行き交う覚醒体たちは、この空間を完全には理解していないがあなたがそれを解き明かした時には驚異的な力を垣間見ることになる。\n彼らと共に戦い、超次元空間を利用して戦う方法を習得しよう。"
  },
  Stage_94466_Name = {
    Text = "超次元の域"
  },
  Stage_94806_Desc = {
    Text = "素晴らしい休日が粗暴と暴力で壊されるなんて、戦うのならバレーボールコートで勝負しましょう！"
  },
  Stage_94806_Name = {
    Text = "文明決闘"
  },
  Stage_94808_Desc = {
    Text = "チャンピオンとしては、いくつかの小さな特権があるべきです。"
  },
  Stage_94808_Name = {
    Text = "チャンピオンと大乱闘"
  },
  Stage_94811_Desc = {
    Text = "一位を狙う者が、同じ場所で二度も転ぶはずがあるものか！"
  },
  Stage_94811_Name = {
    Text = "決勝の一球"
  },
  Stage_94817_Desc = {
    Text = "人々は避けられないエントロピーの増加を規則で制御することに慣れている。実際、誰もが自分の原則を持ち、数十の原則が衝突すると、最終的には——原則など存在しなくなる"
  },
  Stage_94817_Name = {
    Text = "ペアリングの原則"
  },
  Stage_94824_Desc = {
    Text = "静かな夜、柔らかな海風、星々の優しい光の下で、秘密の心事を打ち明けるのにいつも最適です。"
  },
  Stage_94824_Name = {
    Text = "夜風だけが知っている"
  },
  Stage_94832_Desc = {
    Text = "彼女の心の中には明確に理解している：一腔の孤独な勇気は無敵の勝利をもたらさない、過去も今も変わらない。"
  },
  Stage_94832_Name = {Text = "辛勝"},
  Stage_94837_Desc = {
    Text = "もしこの瞬間の楽しみが固定できるのなら、私はその記憶の期限が永遠であることを願っています。"
  },
  Stage_94837_Name = {
    Text = "一枚の写真"
  },
  Stage_94841_Desc = {
    Text = "海辺は休日の標準的な答え、酷暑の下で、誰が清涼な波を踏みながら日差しを避けることを拒むのでしょうか？ちょっと待って…………なぜ太陽が落ちてくるのですか？！"
  },
  Stage_94841_Name = {
    Text = "高温警報"
  },
  Stage_94843_Desc = {
    Text = "激しい競技場で、各選手が自らの魅力を発揮します…………ディレクター、その放送できない魅力をすべてカットしてください。"
  },
  Stage_94843_Name = {
    Text = "始めましょう！準決勝！"
  },
  Stage_95332_Desc = {
    Text = "あなたが彼らに加わるその瞬間、あなたは死神と契約を交わした。彼らがあなたにもたらす全てを楽しみなさい、なぜなら、契約がいつ実行されるかは分からないから。"
  },
  Stage_95332_Name = {
    Text = "契約目標・その六"
  },
  Stage_95333_Desc = {
    Text = "あなたが彼らに加わるその瞬間、あなたは死神と契約を交わした。彼らがあなたにもたらす全てを楽しみなさい、なぜなら、契約がいつ実行されるかは分からないから。"
  },
  Stage_95333_Name = {
    Text = "契約目標・その五"
  },
  Stage_95334_Desc = {
    Text = "あなたが彼らに加わるその瞬間、あなたは死神と契約を交わした。彼らがあなたにもたらす全てを楽しみなさい、なぜなら、契約がいつ実行されるかは分からないから。"
  },
  Stage_95334_Name = {
    Text = "契約目標・癲狂"
  },
  Stage_95335_Desc = {
    Text = "全身の細胞が繰り返し、ただ同じ言葉を繰り返す――光が、来た。"
  },
  Stage_95335_Name = {
    Text = "覆世の光・その三"
  },
  Stage_95336_Desc = {
    Text = "太陽が大地に降臨し、深淵から昇るように。\nすべての物が溶け合い、偉大な者に捧げるべき供物を贈ります。"
  },
  Stage_95336_Name = {
    Text = "地表の太陽·その3"
  },
  Stage_95337_Desc = {
    Text = "太陽が深淵に帰るその刻に、全世界は静寂に包まれるだろう。\nこの世界には灰しかなく、すでに何も残されていないから。"
  },
  Stage_95337_Name = {
    Text = "無声の世界・その一"
  },
  Stage_95338_Desc = {
    Text = "太陽が深淵に帰るその刻に、全世界は静寂に包まれるだろう。\nこの世界には灰しかなく、すでに何も残されていないから。"
  },
  Stage_95338_Name = {
    Text = "無声の世界・その三"
  },
  Stage_95339_Desc = {
    Text = "太陽が深淵に帰るその刻に、全世界は静寂に包まれるだろう。\nこの世界には灰しかなく、すでに何も残されていないから。"
  },
  Stage_95339_Name = {
    Text = "無声の世界・癲狂"
  },
  Stage_95340_Desc = {
    Text = "彼は声を奪わなかった、なぜなら彼は罪深き者の地獄でのうめきを聞こうとしているからだ。\n数億の光点が極昼の中で踊り、共鳴し、それらの音はそのうめきと共に交差し、地獄の中で完璧な歌を織り成す。"
  },
  Stage_95340_Name = {
    Text = "煉獄の歌·その一"
  },
  Stage_95341_Desc = {
    Text = "太陽が深淵に帰るその刻に、全世界は静寂に包まれるだろう。\nこの世界には灰しかなく、すでに何も残されていないから。"
  },
  Stage_95341_Name = {
    Text = "無声の世界・その四"
  },
  Stage_95342_Desc = {
    Text = "彼は熱い炎を持って現れ、あなた達の罪を宣告する。あなたはできるだけ反抗する必要がある。彼の気を紛らわせることが、あなたの最後の贖罪だから。"
  },
  Stage_95342_Name = {
    Text = "炎の宣判·之一"
  },
  Stage_95343_Desc = {
    Text = "あなたが彼らに加わるその瞬間、あなたは死神と契約を交わした。彼らがあなたにもたらす全てを楽しみなさい、なぜなら、契約がいつ実行されるかは分からないから。"
  },
  Stage_95343_Name = {
    Text = "契約目標・その三"
