  },
  Stage_95380_Desc = {
    Text = "彼は声を奪わなかった、なぜなら彼は罪深き者の地獄でのうめきを聞こうとしているからだ。\n数億の光点が極昼の中で踊り、共鳴し、それらの音はそのうめきと共に交差し、地獄の中で完璧な歌を織り成す。"
  },
  Stage_95380_Name = {
    Text = "煉獄の歌·その五"
  },
  Stage_95706_Desc = {
    Text = "あの惨めで、美しく、あまりにも多くの記憶を持つ魂こそが、各素材の独自の理由です。\nそれは、各層があなたの舌先と戦い、交錯し、そして一体となる。\n——すべての亡者が一生待ち望んでいるのは、この瞬間に食べられることなのです。"
  },
  Stage_95706_Name = {
    Text = "魂の祭り·その六"
  },
  Stage_95707_Desc = {
    Text = "0.5インチの深さで、経絡の方向に垂直です。\n首の脊髄と扇骨に沿って、骨と肉を分けます。\n身躯は、料理人のチェス盤です。"
  },
  Stage_95707_Name = {
    Text = "骨血剥離・第6"
  },
  Stage_95708_Desc = {
    Text = "香りがする？オーク、スギ、そしてパチュリの香り。\n彼の主人はこの美しい棺の中で三百年眠っている。\nこれにより、彼はこの宴会の主菜となる名誉を得た。"
  },
  Stage_95708_Name = {
    Text = "棺が開く・第6"
  },
  Stage_95709_Desc = {
    Text = "香りがする？オーク、スギ、そしてパチュリの香り。\n彼の主人はこの美しい棺の中で三百年眠っている。\nこれにより、彼はこの宴会の主菜となる名誉を得た。"
  },
  Stage_95709_Name = {
    Text = "棺が開く・第2"
  },
  Stage_95710_Desc = {
    Text = "塩の粒。パセリ。レモングラス。オリーブ。ローズマリー。\n一つの忠告：どんなに良い食材でも香辛料を軽視しないように。\nこのチェスボード上では、香辛料こそが料理人の駒だ。"
  },
  Stage_95710_Name = {
    Text = "腐植の調香・その三"
  },
  Stage_95711_Desc = {
    Text = "私たちは味と永遠を称え、火はその反対のものです。\nしかし、この世で最も洗練された、最も素晴らしい風味は、火から来ています。\nある意味、絶妙な皮肉ではありませんか？"
  },
