    Text = "腐植の調香・癲狂"
  },
  Stage_95732_Desc = {
    Text = "0.5インチの深さで、経絡の方向に垂直です。\n首の脊髄と扇骨に沿って、骨と肉を分けます。\n身躯は、料理人のチェス盤です。"
  },
  Stage_95732_Name = {
    Text = "骨血剥離・癲狂"
  },
  Stage_95733_Desc = {
    Text = "あの惨めで、美しく、あまりにも多くの記憶を持つ魂こそが、各素材の独自の理由です。\nそれは、各層があなたの舌先と戦い、交錯し、そして一体となる。\n——すべての亡者が一生待ち望んでいるのは、この瞬間に食べられることなのです。"
  },
  Stage_95733_Name = {
    Text = "魂の祭り·その四"
  },
  Stage_95734_Desc = {
    Text = "私たちは味と永遠を称え、火はその反対のものです。\nしかし、この世で最も洗練された、最も素晴らしい風味は、火から来ています。\nある意味、絶妙な皮肉ではありませんか？"
  },
  Stage_95734_Name = {
    Text = "亡焰炙魂·その四"
  },
  Stage_95735_Desc = {
    Text = "香りがする？オーク、スギ、そしてパチュリの香り。\n彼の主人はこの美しい棺の中で三百年眠っている。\nこれにより、彼はこの宴会の主菜となる名誉を得た。"
  },
