    Text = "こんな狂気のラインを見たことがあるか？\nすべての軌跡が透視法則の鎖から解放され、暴動を起こした囚人のように紙上を駆け巡る。\nそれらは交差し、戦い、互いに飲み込み、歪んだダンスでピックマンの目に映る真実を描き出す。"
  },
  Stage_97085_Name = {
    Text = "ラインの魂が暴れ回る・その4"
  },
  Stage_97086_Desc = {
    Text = "不明な苦痛が色彩の深淵で咆哮する。残酷な光景が浮かび上がり、彼岸の炎やねじれた影が互いに絡み合って押し寄せる。\nこの時のキャンバスは罪と罰の囚牢となり、あらゆる寸法が熾烈な懲罰と苦痛で閃いている。\n世界はすでに逆転し、すべての善が覆い隠され、燃え盛る苦悩の地獄で魂の真実が明らかになる。\n見えましたか？これが芸術の美です。"
  },
  Stage_97086_Name = {
    Text = "地獄の変化・その二"
  },
  Stage_97087_Desc = {
    Text = "不明な苦痛が色彩の深淵で咆哮する。残酷な光景が浮かび上がり、彼岸の炎やねじれた影が互いに絡み合って押し寄せる。\nこの時のキャンバスは罪と罰の囚牢となり、あらゆる寸法が熾烈な懲罰と苦痛で閃いている。\n世界はすでに逆転し、すべての善が覆い隠され、燃え盛る苦悩の地獄で魂の真実が明らかになる。\n見えましたか？これが芸術の美です。"
  },
  Stage_97087_Name = {
    Text = "地獄の変化・その六"
  },
  Stage_97088_Desc = {
    Text = "熱狂的なダンサーが虚無の偶像の周りを回り、信仰の残骸には誰も関心を示さず、ただ喜びの渦が失控の中でますますきつく巻きついていく。\nこの瞬間、あらゆる恥じらいや気遣いは狂熱の回転の中で無に帰し、すべての生き物は幻影のために狂ったように踊ります。\nピクマンは大笑いして、君をこの狂熱のダンスに招待します。"
  },
  Stage_97088_Name = {
    Text = "金牛の狂舞・第三"
  },
  Stage_97089_Desc = {
    Text = "狂熱の踊り手たちが虚妄の偶像を中心に旋回し、信仰の残骸を顧みる者はなく、歓楽の渦だけが制御を失いながらますます強く巻き締まる。\nこの瞬間、すべての羞恥と躊躇いは狂熱の旋回の中で消え去り、衆生はただ幻影のために狂い踊る。\nピックマンは大笑いしながら、この狂熱の踊りに加わるよう君を誘う。"
  },
  Stage_97089_Name = {
    Text = "金牛の狂舞・第一"
  },
  Stage_97090_Desc = {
    Text = "平凡な画家？いいえ、いえ。\n鮮紅の筆触が飛び出し、奇妙な渦が瞬時に白と明瞭を飲み込む。\n明るいものと陰鬱なものが交錯する赤色が広がり、作品全体に躁動と生命の息吹を染み込ませている。\nこの血のような色だけが、世の中で最も鮮やかで真実の存在なのだ！"
  },
  Stage_97090_Name = {
    Text = "血色の蔓延・之四"
  },
  Stage_97091_Desc = {
    Text = "平凡な画家？いいえ、いえ。\n鮮紅の筆触が飛び出し、奇妙な渦が瞬時に白と明瞭を飲み込む。\n明るいものと陰鬱なものが交錯する赤色が広がり、作品全体に躁動と生命の息吹を染み込ませている。\nこの血のような色だけが、世の中で最も鮮やかで真実の存在なのだ！"
  },
  Stage_97091_Name = {
    Text = "血色が広がる・その5"
  },
  Stage_97092_Desc = {
    Text = "インスピレーションは、平凡に甘んじる者の禁断の果実です。\nそして、この絵巻の上で、誇張された構図が芸術の真髄を示しています。\nインスピレーションは、疾風のように降臨し、招待なしに心の中に侵入します。\nその瞬間、潜んでいた不安と渇望がすべて覚醒し、夜を貫く火の光のように、心を透き通らせ、熱く照らします。"
  },
  Stage_97092_Name = {
    Text = "インスピレーション感染·狂気"
  },
  Stage_97093_Desc = {
    Text = "魂はキャンバスの上で炎のように燃え、透明な油彩がゆっくりと流れ、血色は永遠の世界に固定され、狂気こそが真実の酒蔵です。\n俗世の覚醒を捨て、混沌の極楽に飛び込みこそ、初めて芸術に触れることができます。\nああ、私はこの究極の狂喜と絶望に永遠に沈みたい！\nさあ、この癲狂の饗宴の後に美しい新世界を迎えましょう。"
  },
  Stage_97093_Name = {
    Text = "狂歓の固定·その1"
  },
