  Stage_97227_Desc = {
    Text = "祭品が到着し、血が満ちて、宇宙の至高の主よ！あなたの信者を永遠の国へお連れください！"
  },
  Stage_97228_Desc = {
    Text = "黒い太陽が降臨しましたね？"
  },
  Stage_97228_Name = {
    Text = "黒い太陽"
  },
  Stage_97229_Desc = {
    Text = "裏切りは絶妙なタイミングで起こった。「人にそそのかされて」、「やむを得ず」、「生き残るために」、なんて完璧な裏切りの理由だ。\n残念ながら、裏切る相手を間違えた。"
  },
  Stage_97229_Name = {
    Text = "裏切りの音"
  },
  Stage_97230_Desc = {
    Text = "謎が解けた、あなたは当たったのか？\nありふれたと思う？私は結構面白いと思う、結局…………面白いかどうかなんて気にしない〜"
  },
  Stage_97230_Name = {Text = "黒幕"},
  Stage_97231_Desc = {
    Text = "私たちは1つ1つの情けを忘れませんし、1つ1つの恨みも忘れません。これは私たちがこの厳しい世界に生きる中で、最後の贅沢です。"
  },
  Stage_97231_Name = {
    Text = "忘れない"
  },
  Stage_97232_Desc = {
    Text = "酒に酔った頭を持ち上げ、汚れた杯を持ってください。昨夜の全てを忘れ、新しいパーティーがやってきます。\n私の友よ、表現主義の楽園へようこそ。"
  },
  Stage_97232_Name = {
    Text = "野獣主義酒場"
  },
  Stage_97233_Desc = {
    Text = "最後の一滴の酒が杯から落ちると、すべてを葬る銃声が応じて鳴り響く。"
  },
  Stage_97233_Name = {
    Text = "渇きの酒"
  },
  Stage_97288_Desc = {
    Text = "模擬戦闘"
  },
  Stage_97288_Name = {
    Text = "シミュレーションバトル3"
  },
  Stage_97615_Desc = {
    Text = "神は万物万事に各行其道を促します。\n虬結の根茎は腐土に埋まり、爪や鱗羽は噛みついて這い回ります。繁花は枯骨の上に生じ、羸弱は強大に呑み込まれます。\n彼は生物に相互に絡み合って殺し合う権利を与えました。"
  },
  Stage_97616_Desc = {
    Text = "神は群星を正位に戻し、日月にそれぞれの役割を果たさせます。\n光と闇の残骸は狂気の軌跡を歩み、何千年も迷い続けた魂に帰路を指し示します。\n彼は信者に回復の権利を与えました。"
  },
  Stage_97616_Name = {
    Text = "第三日・癲狂"
  },
  Stage_97617_Desc = {
    Text = "神は無形の胚種を世に生み出しました。\n鰭のある者は海を遡り、翼のある者は空を飛翔します。\n彼は囁きの音色で彼らを深海で呼吸させ、狂乱の吟唱で彼らを雲層で行き来させます。"
  },
  Stage_97618_Desc = {
    Text = "神は無形の胚種を世に生み出しました。\n鰭のある者は海を遡り、翼のある者は空を飛翔します。\n彼は囁きの音色で彼らを深海で呼吸させ、狂乱の吟唱で彼らを雲層で行き来させます。"
  },
  Stage_97619_Desc = {
    Text = "神は天と地、地と海を分けました。\n青空は濃厚で脈動する幕を垂らし、硫黄と海塩の香りが深淵から立ち上ります。\n彼は海の子民にあらゆる場所を行く権利を与えました。"
  },
