    Text = "あなたは懐かしくもあり、見知らぬキャンパスを歩き、賑やかで平凡なすべてを見ながら、これに喜んで魅了されるのでしょうか？それとも、これらを一度も持っていなかったことを悲しむのでしょうか？"
  },
  Stage_97830_Name = {
    Text = "故地の再訪・その4"
  },
  Stage_97831_Desc = {
    Text = "太陽はすでに死んでおり、空に残っているのはただの劣化した死体だ。\nまるでこの腐敗した世界の中で、重い灰の中に残されたのは、いったい生命なのか、それとも生命が死の間際に活動する幻影なのか？"
  },
  Stage_97831_Name = {
    Text = "黒陽に直面する・その5"
  },
  Stage_97832_Desc = {
    Text = "美しい言葉はしばしば苦痛から生まれます。\n彼女は美に気づいた時、すでに生活の影に潜んでいた悲劇が訪れたことを知っていました。\n美とは、短く砕けたすべてです。"
  },
  Stage_97832_Name = {
    Text = "詩的な庭·その三"
  },
  Stage_97833_Desc = {
    Text = "美しい言葉はしばしば苦痛から生まれます。\n彼女は美に気づいた時、すでに生活の影に潜んでいた悲劇が訪れたことを知っていました。\n美とは、短く砕けたすべてです。"
  },
  Stage_97833_Name = {
    Text = "詩的な庭·その四"
  },
  Stage_97834_Desc = {
    Text = "母親、それは人々が生まれてから死ぬまで呟く呪文です。\n子供は成長したいと願い、母親の愛に満ちた抱擁を渇望しています。\nあなたはその残酷な運命を演じ、一度また彼女を母親の抱擁から引き裂くのでしょうか？"
  },
  Stage_97834_Name = {
    Text = "完璧な童話・その一"
  },
  Stage_97835_Desc = {
    Text = "彼女の心の中には明確に理解している：一腔の孤独な勇気は無敵の勝利をもたらさない、過去も今も変わらない。"
  },
  Stage_97835_Name = {Text = "辛勝"},
  Stage_97836_Desc = {
