  },
  Stage_97836_Name = {
    Text = "黒陽に直面する・その1"
  },
  Stage_97837_Desc = {
    Text = "激しい競技場で、各選手が自らの魅力を発揮します…………ディレクター、その放送できない魅力をすべてカットしてください。"
  },
  Stage_97837_Name = {
    Text = "始めましょう！準決勝！"
