  },
  Stage_97845_Desc = {
    Text = "あなたは懐かしくもあり、見知らぬキャンパスを歩き、賑やかで平凡なすべてを見ながら、これに喜んで魅了されるのでしょうか？それとも、これらを一度も持っていなかったことを悲しむのでしょうか？"
  },
  Stage_97845_Name = {
    Text = "故地の再訪・その2"
  },
  Stage_97903_Desc = {
    Text = "久しぶりに故郷に戻った時、君はその「よそ者」として最も場違いな存在になっていた。"
  },
  Stage_97903_Name = {Text = "帰郷"},
  Stage_97904_Desc = {
    Text = "もしあなたが住みたい場所を描くなら、どんな家、どんな緑豊かな森、どんな自分を描くのでしょうか？\nあなたが描くすべては、真の理想か、埋もれた傷か、そのどちらなのでしょうか？"
  },
  Stage_97904_Name = {
    Text = "心象描写"
  },
  Stage_97905_Desc = {
    Text = "希望に向かう道は、まず自ら希望を断ち切らなければならない。"
  },
  Stage_97905_Name = {Text = "明晰夢"},
  Stage_97906_Desc = {
    Text = "彼らに別れを告げ、そして彼らと再会する道を歩み始めよう。"
  },
  Stage_97906_Name = {
    Text = "あなたの夢"
  },
  Stage_97907_Desc = {
    Text = "最も完璧な結末は、最も虚構な結末でもあり、すべての幸せな笑顔の中で、あなたは目覚めと真実を選ぶ必要があります。\nなぜなら、あなたが唯一の守秘者だからです。"
  },
  Stage_97907_Name = {
    Text = "偽りの結末"
  },
  Stage_97908_Desc = {
    Text = "落ちていく花びらよ、まるで真っ赤な火のように。"
  },
  Stage_97908_Name = {
    Text = "花びらが散る時"
  },
  Stage_97909_Desc = {
    Text = "もし運命が残酷でなかったら、彼女たちは理想の初めの姿のまま生きることができたのでしょうか。"
  },
  Stage_97909_Name = {
    Text = "最初の願い"
  },
  Stage_97910_Desc = {
    Text = "白いスカート、ベッド、部屋、そして美しい夢。"
  },
  Stage_97910_Name = {
    Text = "純白の童話"
  },
  Stage_98000_Desc = {
    Text = "虚偽は必ず破壊されます、古代から永遠に続く偉大な存在の前では、どんな陰謀や計算も無力で小さく見えます。\n昼が近づき、火が琥珀色の北落師門から落ちて、万物に平等な破壊と死をもたらします。"
  },
  Stage_98000_Name = {
    Text = "古の太陽を消えずに"
  },
  Stage_98829_Desc = {
    Text = "苦痛は人を目覚めさせる良薬だ。"
  },
  Stage_98829_Name = {
    Text = "静寂の覚醒・その三"
  },
  Stage_98830_Desc = {
    Text = "伝説によれば、双生児の運命は一生絡み合い、分かれることはできない。\n無数の生命を孕んだ星空の下で、私たちはついに再会する。"
  },
  Stage_98830_Name = {
    Text = "双生の翼・その二"
  },
  Stage_98831_Desc = {
    Text = "その翼を支える風は、彼の優しい手のよう。"
  },
  Stage_98831_Name = {
    Text = "風の担ぎ·癲狂"
  },
  Stage_98832_Desc = {
    Text = "勇敢な騎士、熱血の冒険、希望と挑戦に満ちた旅路。\nもし物語が書の結末で止まれば、どんなに素晴らしいだろう。"
  },
  Stage_98832_Name = {
    Text = "冒険のおとぎ話・その一"
  },
  Stage_98833_Desc = {
    Text = "すべての記憶を忘れた後、あなたはかつてのあなたですか？"
  },
  Stage_98833_Name = {
