  Stage_99725_Desc = {
    Text = "批判はアーティストの責任ではなく、創造がそれです。"
  },
  Stage_99725_Name = {
    Text = "汚泥の上のサロン"
  },
  Stage_99726_Desc = {
    Text = "俺たちはずっと同じ天秤の上に閉じ込められ、互いに押し合い続けてきた。だが、弟よ——たとえその天秤を壊せなくとも、俺たちは元々、その天秤から飛び降りることを選べたんだ。"
  },
  Stage_99726_Name = {
    Text = "傾いた天秤"
